INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0032', 'greet', '打招呼', 'dǎ zhāohu', '/ɡriːt/', 'chào hỏi', 'verb', 'Our supervisor asked us to greet without unnecessary delay.', '主管要求我们不要拖延，尽快“打招呼”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "dǎ zhāohu".', 'Quản lý đề nghị chúng tôi chào hỏi kịp thời, không trì hoãn.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0033', 'introduce', '介绍', 'jièshào', '/ˌɪntrəˈduːs/', 'giới thiệu', 'verb', 'Learners should practice how to introduce clearly in real situations.', '学习者应在实际情境中反复练习如何“介绍”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "jièshào".', 'Người học nên luyện tập cách giới thiệu rõ ràng trong tình huống thực tế.', 'Giao tiếp hàng ngày', 1, 'A1', 'HSK 2', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0034', 'invite', '邀请', 'yāoqǐng', '/ɪnˈvaɪt/', 'mời', 'verb', 'Please make sure to invite carefully before moving to the next step.', '在进入下一步之前，请务必认真“邀请”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "yāoqǐng".', 'Hãy nhớ mời cẩn thận trước khi chuyển sang bước tiếp theo.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0035', 'accept', '接受', 'jiēshòu', '/əkˈsept/', 'chấp nhận', 'verb', 'Our supervisor asked us to accept without unnecessary delay.', '主管要求我们不要拖延，尽快“接受”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "jiēshòu".', 'Quản lý đề nghị chúng tôi chấp nhận kịp thời, không trì hoãn.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0036', 'decline', '婉拒', 'wǎnjù', '/dɪˈklaɪn/', 'từ chối lịch sự', 'verb', 'Learners should practice how to decline clearly in real situations.', '学习者应在实际情境中反复练习如何“婉拒”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "wǎnjù".', 'Người học nên luyện tập cách từ chối lịch sự rõ ràng trong tình huống thực tế.', 'Giao tiếp hàng ngày', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0037', 'apologize', '道歉', 'dàoqiàn', '/əˈpɑːlədʒaɪz/', 'xin lỗi', 'verb', 'Please make sure to apologize carefully before moving to the next step.', '在进入下一步之前，请务必认真“道歉”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "dàoqiàn".', 'Hãy nhớ xin lỗi cẩn thận trước khi chuyển sang bước tiếp theo.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0038', 'forgive', '原谅', 'yuánliàng', '/fərˈɡɪv/', 'tha thứ', 'verb', 'Our supervisor asked us to forgive without unnecessary delay.', '主管要求我们不要拖延，尽快“原谅”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "yuánliàng".', 'Quản lý đề nghị chúng tôi tha thứ kịp thời, không trì hoãn.', 'Giao tiếp hàng ngày', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0039', 'remind', '提醒', 'tíxǐng', '/rɪˈmaɪnd/', 'nhắc nhở', 'verb', 'Learners should practice how to remind clearly in real situations.', '学习者应在实际情境中反复练习如何“提醒”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "tíxǐng".', 'Người học nên luyện tập cách nhắc nhở rõ ràng trong tình huống thực tế.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0040', 'promise', '承诺', 'chéngnuò', '/ˈprɑːmɪs/', 'hứa hẹn', 'verb', 'Please make sure to promise carefully before moving to the next step.', '在进入下一步之前，请务必认真“承诺”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "chéngnuò".', 'Hãy nhớ hứa hẹn cẩn thận trước khi chuyển sang bước tiếp theo.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0041', 'explain', '解释', 'jiěshì', '/ɪkˈspleɪn/', 'giải thích', 'verb', 'Our supervisor asked us to explain without unnecessary delay.', '主管要求我们不要拖延，尽快“解释”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "jiěshì".', 'Quản lý đề nghị chúng tôi giải thích kịp thời, không trì hoãn.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0042', 'clarify', '澄清', 'chéngqīng', '/ˈklærəfaɪ/', 'làm rõ', 'verb', 'Learners should practice how to clarify clearly in real situations.', '学习者应在实际情境中反复练习如何“澄清”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "chéngqīng".', 'Người học nên luyện tập cách làm rõ rõ ràng trong tình huống thực tế.', 'Giao tiếp hàng ngày', 1, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0043', 'confirm', '确认', 'quèrèn', '/kənˈfɜːrm/', 'xác nhận', 'verb', 'Please make sure to confirm carefully before moving to the next step.', '在进入下一步之前，请务必认真“确认”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "quèrèn".', 'Hãy nhớ xác nhận cẩn thận trước khi chuyển sang bước tiếp theo.', 'Giao tiếp hàng ngày', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0044', 'cancel', '取消', 'qǔxiāo', '/ˈkænsəl/', 'hủy bỏ', 'verb', 'Our supervisor asked us to cancel without unnecessary delay.', '主管要求我们不要拖延，尽快“取消”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "qǔxiāo".', 'Quản lý đề nghị chúng tôi hủy bỏ kịp thời, không trì hoãn.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0045', 'postpone', '推迟', 'tuīchí', '/poʊstˈpoʊn/', 'hoãn lại', 'verb', 'Learners should practice how to postpone clearly in real situations.', '学习者应在实际情境中反复练习如何“推迟”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "tuīchí".', 'Người học nên luyện tập cách hoãn lại rõ ràng trong tình huống thực tế.', 'Giao tiếp hàng ngày', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0046', 'arrange', '安排', 'ānpái', '/əˈreɪndʒ/', 'sắp xếp', 'verb', 'Please make sure to arrange carefully before moving to the next step.', '在进入下一步之前，请务必认真“安排”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "ānpái".', 'Hãy nhớ sắp xếp cẩn thận trước khi chuyển sang bước tiếp theo.', 'Giao tiếp hàng ngày', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0047', 'borrow', '借入', 'jièrù', '/ˈbɑːroʊ/', 'mượn', 'verb', 'Our supervisor asked us to borrow without unnecessary delay.', '主管要求我们不要拖延，尽快“借入”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "jièrù".', 'Quản lý đề nghị chúng tôi mượn kịp thời, không trì hoãn.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0048', 'lend', '借出', 'jièchū', '/lend/', 'cho mượn', 'verb', 'Learners should practice how to lend clearly in real situations.', '学习者应在实际情境中反复练习如何“借出”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "jièchū".', 'Người học nên luyện tập cách cho mượn rõ ràng trong tình huống thực tế.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0049', 'repair', '修理', 'xiūlǐ', '/rɪˈper/', 'sửa chữa', 'verb', 'Please make sure to repair carefully before moving to the next step.', '在进入下一步之前，请务必认真“修理”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "xiūlǐ".', 'Hãy nhớ sửa chữa cẩn thận trước khi chuyển sang bước tiếp theo.', 'Nhà cửa & sinh hoạt', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0050', 'organize', '整理', 'zhěnglǐ', '/ˈɔːrɡənaɪz/', 'sắp xếp gọn gàng', 'verb', 'Our supervisor asked us to organize without unnecessary delay.', '主管要求我们不要拖延，尽快“整理”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "zhěnglǐ".', 'Quản lý đề nghị chúng tôi sắp xếp gọn gàng kịp thời, không trì hoãn.', 'Nhà cửa & sinh hoạt', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0051', 'polite', '礼貌的', 'lǐmào de', '/pəˈlaɪt/', 'lịch sự', 'adjective', 'The report highlighted a polite factor that shaped the final decision.', '报告重点指出了一项“礼貌的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "lǐmào de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố lịch sự đã tác động tới quyết định cuối cùng.', 'Tính cách & thái độ', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0052', 'patient', '耐心的', 'nàixīn de', '/ˈpeɪʃənt/', 'kiên nhẫn', 'adjective', 'It is important to stay patient when handling complex tasks.', '在处理复杂任务时，保持“耐心的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "nàixīn de" fēicháng zhòngyào.', 'Giữ được tính chất kiên nhẫn rất quan trọng khi xử lý công việc phức tạp.', 'Tính cách & thái độ', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0053', 'punctual', '准时的', 'zhǔnshí de', '/ˈpʌŋktʃuəl/', 'đúng giờ', 'adjective', 'Many readers found the explanation punctual and easy to follow.', '许多读者认为这段解释十分“准时的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "zhǔnshí de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất đúng giờ và dễ theo dõi.', 'Tính cách & thái độ', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0054', 'reliable', '可靠的', 'kěkào de', '/rɪˈlaɪəbəl/', 'đáng tin cậy', 'adjective', 'The report highlighted a reliable factor that shaped the final decision.', '报告重点指出了一项“可靠的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "kěkào de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố đáng tin cậy đã tác động tới quyết định cuối cùng.', 'Tính cách & thái độ', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0055', 'generous', '慷慨的', 'kāngkǎi de', '/ˈdʒenərəs/', 'hào phóng', 'adjective', 'It is important to stay generous when handling complex tasks.', '在处理复杂任务时，保持“慷慨的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "kāngkǎi de" fēicháng zhòngyào.', 'Giữ được tính chất hào phóng rất quan trọng khi xử lý công việc phức tạp.', 'Tính cách & thái độ', 1, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0056', 'curious', '好奇的', 'hàoqí de', '/ˈkjʊriəs/', 'tò mò', 'adjective', 'Many readers found the explanation curious and easy to follow.', '许多读者认为这段解释十分“好奇的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "hàoqí de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất tò mò và dễ theo dõi.', 'Tính cách & thái độ', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0057', 'grateful', '感激的', 'gǎnjī de', '/ˈɡreɪtfəl/', 'biết ơn', 'adjective', 'The report highlighted a grateful factor that shaped the final decision.', '报告重点指出了一项“感激的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "gǎnjī de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố biết ơn đã tác động tới quyết định cuối cùng.', 'Tính cách & thái độ', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0058', 'comfortable', '舒适的', 'shūshì de', '/ˈkʌmftərbəl/', 'thoải mái', 'adjective', 'It is important to stay comfortable when handling complex tasks.', '在处理复杂任务时，保持“舒适的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "shūshì de" fēicháng zhòngyào.', 'Giữ được tính chất thoải mái rất quan trọng khi xử lý công việc phức tạp.', 'Đời sống hàng ngày', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0059', 'convenient', '方便的', 'fāngbiàn de', '/kənˈviːniənt/', 'thuận tiện', 'adjective', 'Many readers found the explanation convenient and easy to follow.', '许多读者认为这段解释十分“方便的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "fāngbiàn de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất thuận tiện và dễ theo dõi.', 'Đời sống hàng ngày', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0060', 'crowded', '拥挤的', 'yōngjǐ de', '/ˈkraʊdɪd/', 'đông đúc', 'adjective', 'The report highlighted a crowded factor that shaped the final decision.', '报告重点指出了一项“拥挤的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "yōngjǐ de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố đông đúc đã tác động tới quyết định cuối cùng.', 'Đời sống hàng ngày', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0061', 'quiet', '安静的', 'ānjìng de', '/ˈkwaɪət/', 'yên tĩnh', 'adjective', 'It is important to stay quiet when handling complex tasks.', '在处理复杂任务时，保持“安静的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "ānjìng de" fēicháng zhòngyào.', 'Giữ được tính chất yên tĩnh rất quan trọng khi xử lý công việc phức tạp.', 'Đời sống hàng ngày', 1, 'A1', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0062', 'tidy', '整洁的', 'zhěngjié de', '/ˈtaɪdi/', 'gọn gàng', 'adjective', 'Many readers found the explanation tidy and easy to follow.', '许多读者认为这段解释十分“整洁的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "zhěngjié de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất gọn gàng và dễ theo dõi.', 'Nhà cửa & sinh hoạt', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0063', 'urgent', '紧急的', 'jǐnjí de', '/ˈɜːrdʒənt/', 'khẩn cấp', 'adjective', 'The report highlighted a urgent factor that shaped the final decision.', '报告重点指出了一项“紧急的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "jǐnjí de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố khẩn cấp đã tác động tới quyết định cuối cùng.', 'Giao tiếp hàng ngày', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0064', 'frequently', '经常地', 'jīngcháng de', '/ˈfriːkwəntli/', 'thường xuyên', 'adverb', 'She spoke frequently so that everyone in the room could follow.', '她“经常地”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "jīngcháng de" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày thường xuyên để mọi người trong phòng đều dễ dàng theo kịp.', 'Tần suất & cách thức', 1, 'B1', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0065', 'occasionally', '偶尔地', 'ǒu''ěr de', '/əˈkeɪʒənəli/', 'thỉnh thoảng', 'adverb', 'The situation changed occasionally over the past few months.', '在过去几个月里，情况“偶尔地”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "ǒu''ěr de" fāshēng le biànhuà.', 'Tình hình đã thay đổi thỉnh thoảng trong vài tháng vừa qua.', 'Tần suất & cách thức', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0066', 'immediately', '立刻', 'lìkè', '/ɪˈmiːdiətli/', 'ngay lập tức', 'adverb', 'She spoke immediately so that everyone in the room could follow.', '她“立刻”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "lìkè" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày ngay lập tức để mọi người trong phòng đều dễ dàng theo kịp.', 'Tần suất & cách thức', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0067', 'gradually', '逐渐地', 'zhújiàn de', '/ˈɡrædʒuəli/', 'dần dần', 'adverb', 'The situation changed gradually over the past few months.', '在过去几个月里，情况“逐渐地”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "zhújiàn de" fāshēng le biànhuà.', 'Tình hình đã thay đổi dần dần trong vài tháng vừa qua.', 'Tần suất & cách thức', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0068', 'eventually', '最终', 'zuìzhōng', '/ɪˈventʃuəli/', 'cuối cùng', 'adverb', 'She spoke eventually so that everyone in the room could follow.', '她“最终”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "zuìzhōng" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày cuối cùng để mọi người trong phòng đều dễ dàng theo kịp.', 'Tần suất & cách thức', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0069', 'apparently', '显然', 'xiǎnrán', '/əˈpærəntli/', 'rõ ràng là', 'adverb', 'The situation changed apparently over the past few months.', '在过去几个月里，情况“显然”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "xiǎnrán" fāshēng le biànhuà.', 'Tình hình đã thay đổi rõ ràng là trong vài tháng vừa qua.', 'Tần suất & cách thức', 1, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0070', 'in advance', '提前', 'tíqián', '/ɪn ədˈvæns/', 'trước (thời hạn)', 'phrase', 'You can use the expression ''in advance'' naturally in everyday conversation.', '在日常交流中，你可以自然地使用“提前”这一表达。', 'Zài rìcháng jiāoliú zhōng, nǐ kěyǐ zìrán de shǐyòng "tíqián" zhè yī biǎodá.', 'Bạn có thể dùng cụm “in advance” (trước (thời hạn)) một cách tự nhiên trong giao tiếp hàng ngày.', 'Cụm từ giao tiếp', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0071', 'on time', '准时', 'zhǔnshí', '/ɑːn taɪm/', 'đúng giờ', 'phrase', 'Try to on time whenever you need a clear and practical phrasing.', '在需要清晰表达时，不妨尝试使用“准时”。', 'Zài xūyào qīngxī biǎodá shí, bùfáng chángshì shǐyòng "zhǔnshí".', 'Hãy thử vận dụng cách diễn đạt “đúng giờ” khi cần nói ngắn gọn, rõ ý.', 'Cụm từ giao tiếp', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0072', 'in person', '亲自', 'qīnzì', '/ɪn ˈpɜːrsən/', 'trực tiếp', 'phrase', 'You can use the expression ''in person'' naturally in everyday conversation.', '在日常交流中，你可以自然地使用“亲自”这一表达。', 'Zài rìcháng jiāoliú zhōng, nǐ kěyǐ zìrán de shǐyòng "qīnzì" zhè yī biǎodá.', 'Bạn có thể dùng cụm “in person” (trực tiếp) một cách tự nhiên trong giao tiếp hàng ngày.', 'Cụm từ giao tiếp', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0073', 'by mistake', '误打误撞', 'wùdǎ wùzhuàng', '/baɪ mɪˈsteɪk/', 'do nhầm lẫn', 'phrase', 'Try to by mistake whenever you need a clear and practical phrasing.', '在需要清晰表达时，不妨尝试使用“误打误撞”。', 'Zài xūyào qīngxī biǎodá shí, bùfáng chángshì shǐyòng "wùdǎ wùzhuàng".', 'Hãy thử vận dụng cách diễn đạt “do nhầm lẫn” khi cần nói ngắn gọn, rõ ý.', 'Cụm từ giao tiếp', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0074', 'keep in touch', '保持联系', 'bǎochí liánxì', '/kiːp ɪn tʌtʃ/', 'giữ liên lạc', 'phrase', 'You can use the expression ''keep in touch'' naturally in everyday conversation.', '在日常交流中，你可以自然地使用“保持联系”这一表达。', 'Zài rìcháng jiāoliú zhōng, nǐ kěyǐ zìrán de shǐyòng "bǎochí liánxì" zhè yī biǎodá.', 'Bạn có thể dùng cụm “keep in touch” (giữ liên lạc) một cách tự nhiên trong giao tiếp hàng ngày.', 'Cụm từ giao tiếp', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0075', 'make sense', '有道理', 'yǒu dàolǐ', '/meɪk sens/', 'hợp lý, có nghĩa', 'phrase', 'Try to make sense whenever you need a clear and practical phrasing.', '在需要清晰表达时，不妨尝试使用“有道理”。', 'Zài xūyào qīngxī biǎodá shí, bùfáng chángshì shǐyòng "yǒu dàolǐ".', 'Hãy thử vận dụng cách diễn đạt “hợp lý, có nghĩa” khi cần nói ngắn gọn, rõ ý.', 'Cụm từ giao tiếp', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0076', 'take turns', '轮流', 'lúnliú', '/teɪk tɜːrnz/', 'thay phiên nhau', 'phrase', 'You can use the expression ''take turns'' naturally in everyday conversation.', '在日常交流中，你可以自然地使用“轮流”这一表达。', 'Zài rìcháng jiāoliú zhōng, nǐ kěyǐ zìrán de shǐyòng "lúnliú" zhè yī biǎodá.', 'Bạn có thể dùng cụm “take turns” (thay phiên nhau) một cách tự nhiên trong giao tiếp hàng ngày.', 'Cụm từ giao tiếp', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0077', 'run out of', '用完', 'yòngwán', '/rʌn aʊt əv/', 'hết, cạn kiệt', 'phrase', 'Try to run out of whenever you need a clear and practical phrasing.', '在需要清晰表达时，不妨尝试使用“用完”。', 'Zài xūyào qīngxī biǎodá shí, bùfáng chángshì shǐyòng "yòngwán".', 'Hãy thử vận dụng cách diễn đạt “hết, cạn kiệt” khi cần nói ngắn gọn, rõ ý.', 'Cụm từ giao tiếp', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0078', 'figure out', '弄清楚', 'nòng qīngchu', '/ˈfɪɡjər aʊt/', 'tìm ra, hiểu ra', 'phrase', 'You can use the expression ''figure out'' naturally in everyday conversation.', '在日常交流中，你可以自然地使用“弄清楚”这一表达。', 'Zài rìcháng jiāoliú zhōng, nǐ kěyǐ zìrán de shǐyòng "nòng qīngchu" zhè yī biǎodá.', 'Bạn có thể dùng cụm “figure out” (tìm ra, hiểu ra) một cách tự nhiên trong giao tiếp hàng ngày.', 'Cụm từ giao tiếp', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0079', 'look forward to', '期待', 'qīdài', '/lʊk ˈfɔːrwərd tuː/', 'mong đợi', 'phrase', 'Try to look forward to whenever you need a clear and practical phrasing.', '在需要清晰表达时，不妨尝试使用“期待”。', 'Zài xūyào qīngxī biǎodá shí, bùfáng chángshì shǐyòng "qīdài".', 'Hãy thử vận dụng cách diễn đạt “mong đợi” khi cần nói ngắn gọn, rõ ý.', 'Cụm từ giao tiếp', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0080', 'subway', '地铁', 'dìtiě', '/ˈsʌbweɪ/', 'tàu điện ngầm', 'noun', 'Understanding the role of ''subway'' is essential in transportation.', '在相关场景中，理解“地铁”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "dìtiě" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “tàu điện ngầm” rất quan trọng trong chủ đề Giao thông công cộng.', 'Giao thông công cộng', 17, 'A1', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0081', 'commuter', '通勤者', 'tōngqínzhě', '/kəˈmjuːtər/', 'người đi làm hàng ngày', 'noun', 'The team reviewed the details about ''commuter'' before the meeting.', '团队在会议前仔细核对了关于“通勤者”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "tōngqínzhě" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “người đi làm hàng ngày” trước cuộc họp.', 'Giao thông công cộng', 17, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0082', 'crosswalk', '人行横道', 'rénxíng héngdào', '/ˈkrɔːswɔːk/', 'vạch sang đường', 'noun', 'We discussed ''crosswalk'' during today''s lesson on transportation.', '我们在今天的课程中重点讨论了“人行横道”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "rénxíng héngdào".', 'Chúng tôi đã thảo luận trọng tâm về “vạch sang đường” trong buổi học hôm nay.', 'An toàn giao thông', 17, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0083', 'intersection', '十字路口', 'shízì lùkǒu', '/ˌɪntərˈsekʃən/', 'ngã tư', 'noun', 'Clear notes on ''intersection'' help learners recall the concept faster.', '关于“十字路口”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "shízì lùkǒu" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “ngã tư” giúp người học ghi nhớ khái niệm nhanh hơn.', 'An toàn giao thông', 17, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0084', 'roundabout', '环岛', 'huándǎo', '/ˈraʊndəbaʊt/', 'vòng xuyến', 'noun', 'Understanding the role of ''roundabout'' is essential in transportation.', '在相关场景中，理解“环岛”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "huándǎo" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “vòng xuyến” rất quan trọng trong chủ đề An toàn giao thông.', 'An toàn giao thông', 17, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0085', 'highway', '高速公路', 'gāosù gōnglù', '/ˈhaɪweɪ/', 'đường cao tốc', 'noun', 'The team reviewed the details about ''highway'' before the meeting.', '团队在会议前仔细核对了关于“高速公路”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "gāosù gōnglù" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “đường cao tốc” trước cuộc họp.', 'Hạ tầng giao thông', 17, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0086', 'overpass', '立交桥', 'lìjiāoqiáo', '/ˈoʊvərpæs/', 'cầu vượt', 'noun', 'We discussed ''overpass'' during today''s lesson on transportation.', '我们在今天的课程中重点讨论了“立交桥”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "lìjiāoqiáo".', 'Chúng tôi đã thảo luận trọng tâm về “cầu vượt” trong buổi học hôm nay.', 'Hạ tầng giao thông', 17, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0087', 'pedestrian', '行人', 'xíngrén', '/pəˈdestriən/', 'người đi bộ', 'noun', 'Clear notes on ''pedestrian'' help learners recall the concept faster.', '关于“行人”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "xíngrén" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “người đi bộ” giúp người học ghi nhớ khái niệm nhanh hơn.', 'An toàn giao thông', 17, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0088', 'congestion', '交通拥堵', 'jiāotōng yōngdǔ', '/kənˈdʒestʃən/', 'tắc nghẽn giao thông', 'noun', 'Understanding the role of ''congestion'' is essential in transportation.', '在相关场景中，理解“交通拥堵”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "jiāotōng yōngdǔ" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “tắc nghẽn giao thông” rất quan trọng trong chủ đề An toàn giao thông.', 'An toàn giao thông', 17, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0089', 'helmet', '头盔', 'tóukuī', '/ˈhelmɪt/', 'mũ bảo hiểm', 'noun', 'The team reviewed the details about ''helmet'' before the meeting.', '团队在会议前仔细核对了关于“头盔”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "tóukuī" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “mũ bảo hiểm” trước cuộc họp.', 'An toàn giao thông', 17, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0090', 'seatbelt', '安全带', 'ānquándài', '/ˈsiːtbelt/', 'dây an toàn', 'noun', 'We discussed ''seatbelt'' during today''s lesson on transportation.', '我们在今天的课程中重点讨论了“安全带”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "ānquándài".', 'Chúng tôi đã thảo luận trọng tâm về “dây an toàn” trong buổi học hôm nay.', 'An toàn giao thông', 17, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0091', 'commute', '通勤', 'tōngqín', '/kəˈmjuːt/', 'đi làm hàng ngày', 'verb', 'Please make sure to commute carefully before moving to the next step.', '在进入下一步之前，请务必认真“通勤”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "tōngqín".', 'Hãy nhớ đi làm hàng ngày cẩn thận trước khi chuyển sang bước tiếp theo.', 'Giao thông công cộng', 17, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0092', 'transfer', '换乘', 'huànchéng', '/trænsˈfɜːr/', 'chuyển tuyến', 'verb', 'Our supervisor asked us to transfer without unnecessary delay.', '主管要求我们不要拖延，尽快“换乘”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "huànchéng".', 'Quản lý đề nghị chúng tôi chuyển tuyến kịp thời, không trì hoãn.', 'Giao thông công cộng', 17, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0093', 'accelerate', '加速', 'jiāsù', '/əkˈseləreɪt/', 'tăng tốc', 'verb', 'Learners should practice how to accelerate clearly in real situations.', '学习者应在实际情境中反复练习如何“加速”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "jiāsù".', 'Người học nên luyện tập cách tăng tốc rõ ràng trong tình huống thực tế.', 'Vận hành phương tiện', 17, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0094', 'brake', '刹车', 'shāchē', '/breɪk/', 'phanh xe', 'verb', 'Please make sure to brake carefully before moving to the next step.', '在进入下一步之前，请务必认真“刹车”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "shāchē".', 'Hãy nhớ phanh xe cẩn thận trước khi chuyển sang bước tiếp theo.', 'Vận hành phương tiện', 17, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0095', 'park', '停车', 'tíngchē', '/pɑːrk/', 'đỗ xe', 'verb', 'Our supervisor asked us to park without unnecessary delay.', '主管要求我们不要拖延，尽快“停车”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "tíngchē".', 'Quản lý đề nghị chúng tôi đỗ xe kịp thời, không trì hoãn.', 'Vận hành phương tiện', 17, 'A1', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0096', 'passport', '护照', 'hùzhào', '/ˈpæspɔːrt/', 'hộ chiếu', 'noun', 'Understanding the role of ''passport'' is essential in travel and hospitality.', '在相关场景中，理解“护照”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "hùzhào" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “hộ chiếu” rất quan trọng trong chủ đề Thủ tục du lịch.', 'Thủ tục du lịch', 30, 'A1', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0097', 'visa', '签证', 'qiānzhèng', '/ˈviːzə/', 'thị thực', 'noun', 'The team reviewed the details about ''visa'' before the meeting.', '团队在会议前仔细核对了关于“签证”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "qiānzhèng" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “thị thực” trước cuộc họp.', 'Thủ tục du lịch', 30, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0098', 'suitcase', '行李箱', 'xínglixiāng', '/ˈsuːtkeɪs/', 'va li', 'noun', 'We discussed ''suitcase'' during today''s lesson on travel and hospitality.', '我们在今天的课程中重点讨论了“行李箱”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "xínglixiāng".', 'Chúng tôi đã thảo luận trọng tâm về “va li” trong buổi học hôm nay.', 'Thủ tục du lịch', 30, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
