INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0100', 'arrival', '到达', 'dàodá', '/əˈraɪvəl/', 'sự đến nơi', 'noun', 'Understanding the role of ''arrival'' is essential in travel and hospitality.', '在相关场景中，理解“到达”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "dàodá" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “sự đến nơi” rất quan trọng trong chủ đề Hàng không & du lịch.', 'Hàng không & du lịch', 30, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0101', 'layover', '中转停留', 'zhōngzhuǎn tíngliú', '/ˈleɪoʊvər/', 'thời gian quá cảnh', 'noun', 'The team reviewed the details about ''layover'' before the meeting.', '团队在会议前仔细核对了关于“中转停留”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "zhōngzhuǎn tíngliú" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “thời gian quá cảnh” trước cuộc họp.', 'Hàng không & du lịch', 30, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0102', 'souvenir', '纪念品', 'jìniànpǐn', '/ˌsuːvəˈnɪr/', 'quà lưu niệm', 'noun', 'We discussed ''souvenir'' during today''s lesson on travel and hospitality.', '我们在今天的课程中重点讨论了“纪念品”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "jìniànpǐn".', 'Chúng tôi đã thảo luận trọng tâm về “quà lưu niệm” trong buổi học hôm nay.', 'Trải nghiệm du lịch', 30, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
