INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0104', 'guidebook', '旅游指南', 'lǚyóu zhǐnán', '/ˈɡaɪdbʊk/', 'sách hướng dẫn du lịch', 'noun', 'Understanding the role of ''guidebook'' is essential in travel and hospitality.', '在相关场景中，理解“旅游指南”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "lǚyóu zhǐnán" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “sách hướng dẫn du lịch” rất quan trọng trong chủ đề Kế hoạch du lịch.', 'Kế hoạch du lịch', 30, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
