INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0110', 'hostel', '青年旅舍', 'qīngnián lǚshè', '/ˈhɑːstəl/', 'nhà nghỉ tập thể', 'noun', 'We discussed ''hostel'' during today''s lesson on travel and hospitality.', '我们在今天的课程中重点讨论了“青年旅舍”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "qīngnián lǚshè".', 'Chúng tôi đã thảo luận trọng tâm về “nhà nghỉ tập thể” trong buổi học hôm nay.', 'Dịch vụ khách sạn', 30, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
