INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0112', 'sightseeing', '观光', 'guānguāng', '/ˈsaɪtsiːɪŋ/', 'ngắm cảnh', 'noun', 'Understanding the role of ''sightseeing'' is essential in travel and hospitality.', '在相关场景中，理解“观光”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "guānguāng" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “ngắm cảnh” rất quan trọng trong chủ đề Trải nghiệm du lịch.', 'Trải nghiệm du lịch', 30, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0113', 'reserve', '预订', 'yùdìng', '/rɪˈzɜːrv/', 'đặt trước', 'verb', 'Our supervisor asked us to reserve without unnecessary delay.', '主管要求我们不要拖延，尽快“预订”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "yùdìng".', 'Quản lý đề nghị chúng tôi đặt trước kịp thời, không trì hoãn.', 'Dịch vụ khách sạn', 30, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0114', 'check in', '办理入住', 'bànlǐ rùzhù', '/tʃek ɪn/', 'làm thủ tục nhận phòng', 'phrase', 'You can use the expression ''check in'' naturally in everyday conversation.', '在日常交流中，你可以自然地使用“办理入住”这一表达。', 'Zài rìcháng jiāoliú zhōng, nǐ kěyǐ zìrán de shǐyòng "bànlǐ rùzhù" zhè yī biǎodá.', 'Bạn có thể dùng cụm “check in” (làm thủ tục nhận phòng) một cách tự nhiên trong giao tiếp hàng ngày.', 'Dịch vụ khách sạn', 30, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0115', 'check out', '办理退房', 'bànlǐ tuìfáng', '/tʃek aʊt/', 'làm thủ tục trả phòng', 'phrase', 'Try to check out whenever you need a clear and practical phrasing.', '在需要清晰表达时，不妨尝试使用“办理退房”。', 'Zài xūyào qīngxī biǎodá shí, bùfáng chángshì shǐyòng "bànlǐ tuìfáng".', 'Hãy thử vận dụng cách diễn đạt “làm thủ tục trả phòng” khi cần nói ngắn gọn, rõ ý.', 'Dịch vụ khách sạn', 30, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0116', 'explore', '探索', 'tànsuǒ', '/ɪkˈsplɔːr/', 'khám phá', 'verb', 'Our supervisor asked us to explore without unnecessary delay.', '主管要求我们不要拖延，尽快“探索”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "tànsuǒ".', 'Quản lý đề nghị chúng tôi khám phá kịp thời, không trì hoãn.', 'Trải nghiệm du lịch', 30, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0117', 'scenic', '风景优美的', 'fēngjǐng yōuměi de', '/ˈsiːnɪk/', 'có phong cảnh đẹp', 'adjective', 'The report highlighted a scenic factor that shaped the final decision.', '报告重点指出了一项“风景优美的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "fēngjǐng yōuměi de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố có phong cảnh đẹp đã tác động tới quyết định cuối cùng.', 'Trải nghiệm du lịch', 30, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
