INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0127', 'teaspoon', '茶匙', 'cháchí', '/ˈtiːspuːn/', 'thìa cà phê', 'noun', 'Clear notes on ''teaspoon'' help learners recall the concept faster.', '关于“茶匙”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "cháchí" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “thìa cà phê” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Nấu nướng & bếp', 31, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0128', 'skillet', '平底锅', 'píngdǐguō', '/ˈskɪlɪt/', 'chảo rán', 'noun', 'Understanding the role of ''skillet'' is essential in culinary arts.', '在相关场景中，理解“平底锅”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "píngdǐguō" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “chảo rán” rất quan trọng trong chủ đề Nấu nướng & bếp.', 'Nấu nướng & bếp', 31, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0129', 'oven', '烤箱', 'kǎoxiāng', '/ˈʌvən/', 'lò nướng', 'noun', 'The team reviewed the details about ''oven'' before the meeting.', '团队在会议前仔细核对了关于“烤箱”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "kǎoxiāng" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “lò nướng” trước cuộc họp.', 'Nấu nướng & bếp', 31, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
