INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0134', 'seafood', '海鲜', 'hǎixiān', '/ˈsiːfuːd/', 'hải sản', 'noun', 'We discussed ''seafood'' during today''s lesson on culinary arts.', '我们在今天的课程中重点讨论了“海鲜”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "hǎixiān".', 'Chúng tôi đã thảo luận trọng tâm về “hải sản” trong buổi học hôm nay.', 'Ẩm thực', 31, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0135', 'vegetarian', '素食者', 'sùshízhě', '/ˌvedʒəˈteriən/', 'người ăn chay', 'noun', 'Clear notes on ''vegetarian'' help learners recall the concept faster.', '关于“素食者”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "sùshízhě" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “người ăn chay” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Ẩm thực', 31, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0136', 'simmer', '小火慢炖', 'xiǎohuǒ màndùn', '/ˈsɪmər/', 'đun nhỏ lửa', 'verb', 'Please make sure to simmer carefully before moving to the next step.', '在进入下一步之前，请务必认真“小火慢炖”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "xiǎohuǒ màndùn".', 'Hãy nhớ đun nhỏ lửa cẩn thận trước khi chuyển sang bước tiếp theo.', 'Kỹ thuật nấu ăn', 31, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0137', 'roast', '烘烤', 'hōngkǎo', '/roʊst/', 'quay, nướng', 'verb', 'Our supervisor asked us to roast without unnecessary delay.', '主管要求我们不要拖延，尽快“烘烤”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "hōngkǎo".', 'Quản lý đề nghị chúng tôi quay, nướng kịp thời, không trì hoãn.', 'Kỹ thuật nấu ăn', 31, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0138', 'steam', '蒸', 'zhēng', '/stiːm/', 'hấp', 'verb', 'Learners should practice how to steam clearly in real situations.', '学习者应在实际情境中反复练习如何“蒸”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "zhēng".', 'Người học nên luyện tập cách hấp rõ ràng trong tình huống thực tế.', 'Kỹ thuật nấu ăn', 31, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0139', 'stir-fry', '翻炒', 'fānchǎo', '/ˈstɜːrfraɪ/', 'xào nhanh', 'verb', 'Please make sure to stir-fry carefully before moving to the next step.', '在进入下一步之前，请务必认真“翻炒”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "fānchǎo".', 'Hãy nhớ xào nhanh cẩn thận trước khi chuyển sang bước tiếp theo.', 'Kỹ thuật nấu ăn', 31, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0140', 'slice', '切片', 'qiēpiàn', '/slaɪs/', 'thái lát', 'verb', 'Our supervisor asked us to slice without unnecessary delay.', '主管要求我们不要拖延，尽快“切片”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "qiēpiàn".', 'Quản lý đề nghị chúng tôi thái lát kịp thời, không trì hoãn.', 'Kỹ thuật nấu ăn', 31, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0141', 'marinate', '腌制', 'yānzhì', '/ˈmærɪneɪt/', 'ướp gia vị', 'verb', 'Learners should practice how to marinate clearly in real situations.', '学习者应在实际情境中反复练习如何“腌制”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "yānzhì".', 'Người học nên luyện tập cách ướp gia vị rõ ràng trong tình huống thực tế.', 'Kỹ thuật nấu ăn', 31, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0142', 'crispy', '酥脆的', 'sūcuì de', '/ˈkrɪspi/', 'giòn rụm', 'adjective', 'It is important to stay crispy when handling complex tasks.', '在处理复杂任务时，保持“酥脆的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "sūcuì de" fēicháng zhòngyào.', 'Giữ được tính chất giòn rụm rất quan trọng khi xử lý công việc phức tạp.', 'Hương vị', 31, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0143', 'spicy', '辛辣的', 'xīnlà de', '/ˈspaɪsi/', 'cay', 'adjective', 'Many readers found the explanation spicy and easy to follow.', '许多读者认为这段解释十分“辛辣的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "xīnlà de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất cay và dễ theo dõi.', 'Hương vị', 31, 'A1', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0144', 'savory', '咸香的', 'xiánxiāng de', '/ˈseɪvəri/', 'đậm đà, mặn mà', 'adjective', 'The report highlighted a savory factor that shaped the final decision.', '报告重点指出了一项“咸香的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "xiánxiāng de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố đậm đà, mặn mà đã tác động tới quyết định cuối cùng.', 'Hương vị', 31, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0145', 'bitter', '苦的', 'kǔ de', '/ˈbɪtər/', 'đắng', 'adjective', 'It is important to stay bitter when handling complex tasks.', '在处理复杂任务时，保持“苦的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "kǔ de" fēicháng zhòngyào.', 'Giữ được tính chất đắng rất quan trọng khi xử lý công việc phức tạp.', 'Hương vị', 31, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0146', 'sour', '酸的', 'suān de', '/ˈsaʊər/', 'chua', 'adjective', 'Many readers found the explanation sour and easy to follow.', '许多读者认为这段解释十分“酸的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "suān de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất chua và dễ theo dõi.', 'Hương vị', 31, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0147', 'fresh', '新鲜的', 'xīnxiān de', '/freʃ/', 'tươi ngon', 'adjective', 'The report highlighted a fresh factor that shaped the final decision.', '报告重点指出了一项“新鲜的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "xīnxiān de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố tươi ngon đã tác động tới quyết định cuối cùng.', 'Hương vị', 31, 'A1', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0148', 'homemade', '自制的', 'zìzhì de', '/ˌhoʊmˈmeɪd/', 'nhà làm', 'adjective', 'It is important to stay homemade when handling complex tasks.', '在处理复杂任务时，保持“自制的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "zìzhì de" fēicháng zhòngyào.', 'Giữ được tính chất nhà làm rất quan trọng khi xử lý công việc phức tạp.', 'Ẩm thực', 31, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0149', 'nutritious', '有营养的', 'yǒu yíngyǎng de', '/nuˈtrɪʃəs/', 'giàu dinh dưỡng', 'adjective', 'Many readers found the explanation nutritious and easy to follow.', '许多读者认为这段解释十分“有营养的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "yǒu yíngyǎng de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất giàu dinh dưỡng và dễ theo dõi.', 'Ẩm thực', 31, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0150', 'takeaway', '外卖', 'wàimài', '/ˈteɪkəweɪ/', 'đồ ăn mang đi', 'noun', 'We discussed ''takeaway'' during today''s lesson on culinary arts.', '我们在今天的课程中重点讨论了“外卖”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "wàimài".', 'Chúng tôi đã thảo luận trọng tâm về “đồ ăn mang đi” trong buổi học hôm nay.', 'Thực đơn nhà hàng', 31, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0151', 'buffet', '自助餐', 'zìzhùcān', '/bəˈfeɪ/', 'tiệc đứng tự chọn', 'noun', 'Clear notes on ''buffet'' help learners recall the concept faster.', '关于“自助餐”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "zìzhùcān" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “tiệc đứng tự chọn” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Thực đơn nhà hàng', 31, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0152', 'tip', '小费', 'xiǎofèi', '/tɪp/', 'tiền boa', 'noun', 'Understanding the role of ''tip'' is essential in culinary arts.', '在相关场景中，理解“小费”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "xiǎofèi" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “tiền boa” rất quan trọng trong chủ đề Thực đơn nhà hàng.', 'Thực đơn nhà hàng', 31, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
