INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0175', 'opportunity', '机会', 'jīhuì', '/ˌɑːpərˈtuːnəti/', 'cơ hội', 'noun', 'Clear notes on ''opportunity'' help learners recall the concept faster.', '关于“机会”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "jīhuì" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “cơ hội” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Đời sống hàng ngày', 1, 'B1', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0176', 'responsibility', '责任', 'zérèn', '/rɪˌspɑːnsəˈbɪləti/', 'trách nhiệm', 'noun', 'Understanding the role of ''responsibility'' is essential in everyday communication.', '在相关场景中，理解“责任”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "zérèn" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “trách nhiệm” rất quan trọng trong chủ đề Đời sống hàng ngày.', 'Đời sống hàng ngày', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0177', 'celebrate', '庆祝', 'qìngzhù', '/ˈselɪbreɪt/', 'ăn mừng', 'verb', 'Learners should practice how to celebrate clearly in real situations.', '学习者应在实际情境中反复练习如何“庆祝”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "qìngzhù".', 'Người học nên luyện tập cách ăn mừng rõ ràng trong tình huống thực tế.', 'Đời sống hàng ngày', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0178', 'decorate', '装饰', 'zhuāngshì', '/ˈdekəreɪt/', 'trang trí', 'verb', 'Please make sure to decorate carefully before moving to the next step.', '在进入下一步之前，请务必认真“装饰”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "zhuāngshì".', 'Hãy nhớ trang trí cẩn thận trước khi chuyển sang bước tiếp theo.', 'Nhà cửa & sinh hoạt', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0179', 'compare', '比较', 'bǐjiào', '/kəmˈper/', 'so sánh', 'verb', 'Our supervisor asked us to compare without unnecessary delay.', '主管要求我们不要拖延，尽快“比较”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "bǐjiào".', 'Quản lý đề nghị chúng tôi so sánh kịp thời, không trì hoãn.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0180', 'prefer', '更喜欢', 'gèng xǐhuan', '/prɪˈfɜːr/', 'thích hơn', 'verb', 'Learners should practice how to prefer clearly in real situations.', '学习者应在实际情境中反复练习如何“更喜欢”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "gèng xǐhuan".', 'Người học nên luyện tập cách thích hơn rõ ràng trong tình huống thực tế.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0181', 'recommend', '推荐', 'tuījiàn', '/ˌrekəˈmend/', 'gợi ý, tiến cử', 'verb', 'Please make sure to recommend carefully before moving to the next step.', '在进入下一步之前，请务必认真“推荐”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "tuījiàn".', 'Hãy nhớ gợi ý, tiến cử cẩn thận trước khi chuyển sang bước tiếp theo.', 'Giao tiếp hàng ngày', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0182', 'suggest', '建议', 'jiànyì', '/səɡˈdʒest/', 'đề xuất', 'verb', 'Our supervisor asked us to suggest without unnecessary delay.', '主管要求我们不要拖延，尽快“建议”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "jiànyì".', 'Quản lý đề nghị chúng tôi đề xuất kịp thời, không trì hoãn.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0183', 'encourage', '鼓励', 'gǔlì', '/ɪnˈkɜːrɪdʒ/', 'khuyến khích', 'verb', 'Learners should practice how to encourage clearly in real situations.', '学习者应在实际情境中反复练习如何“鼓励”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "gǔlì".', 'Người học nên luyện tập cách khuyến khích rõ ràng trong tình huống thực tế.', 'Giao tiếp hàng ngày', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0184', 'support', '支持', 'zhīchí', '/səˈpɔːrt/', 'ủng hộ', 'verb', 'Please make sure to support carefully before moving to the next step.', '在进入下一步之前，请务必认真“支持”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "zhīchí".', 'Hãy nhớ ủng hộ cẩn thận trước khi chuyển sang bước tiếp theo.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0185', 'trust', '信任', 'xìnrèn', '/trʌst/', 'tin tưởng', 'verb', 'Our supervisor asked us to trust without unnecessary delay.', '主管要求我们不要拖延，尽快“信任”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "xìnrèn".', 'Quản lý đề nghị chúng tôi tin tưởng kịp thời, không trì hoãn.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0186', 'respect', '尊重', 'zūnzhòng', '/rɪˈspekt/', 'tôn trọng', 'verb', 'Learners should practice how to respect clearly in real situations.', '学习者应在实际情境中反复练习如何“尊重”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "zūnzhòng".', 'Người học nên luyện tập cách tôn trọng rõ ràng trong tình huống thực tế.', 'Giao tiếp hàng ngày', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0187', 'avoid', '避免', 'bìmiǎn', '/əˈvɔɪd/', 'tránh', 'verb', 'Please make sure to avoid carefully before moving to the next step.', '在进入下一步之前，请务必认真“避免”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "bìmiǎn".', 'Hãy nhớ tránh cẩn thận trước khi chuyển sang bước tiếp theo.', 'Giao tiếp hàng ngày', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0188', 'notice', '注意到', 'zhùyì dào', '/ˈnoʊtɪs/', 'nhận thấy', 'verb', 'Our supervisor asked us to notice without unnecessary delay.', '主管要求我们不要拖延，尽快“注意到”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "zhùyì dào".', 'Quản lý đề nghị chúng tôi nhận thấy kịp thời, không trì hoãn.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0189', 'recognize', '认出', 'rènchū', '/ˈrekəɡnaɪz/', 'nhận ra', 'verb', 'Learners should practice how to recognize clearly in real situations.', '学习者应在实际情境中反复练习如何“认出”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "rènchū".', 'Người học nên luyện tập cách nhận ra rõ ràng trong tình huống thực tế.', 'Giao tiếp hàng ngày', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0190', 'realize', '意识到', 'yìshí dào', '/ˈriːəlaɪz/', 'nhận thức được', 'verb', 'Please make sure to realize carefully before moving to the next step.', '在进入下一步之前，请务必认真“意识到”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "yìshí dào".', 'Hãy nhớ nhận thức được cẩn thận trước khi chuyển sang bước tiếp theo.', 'Giao tiếp hàng ngày', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0191', 'wonder', '想知道', 'xiǎng zhīdào', '/ˈwʌndər/', 'tự hỏi', 'verb', 'Our supervisor asked us to wonder without unnecessary delay.', '主管要求我们不要拖延，尽快“想知道”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "xiǎng zhīdào".', 'Quản lý đề nghị chúng tôi tự hỏi kịp thời, không trì hoãn.', 'Giao tiếp hàng ngày', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0192', 'deliver', '递送', 'dìsòng', '/dɪˈlɪvər/', 'giao, chuyển phát', 'verb', 'Learners should practice how to deliver clearly in real situations.', '学习者应在实际情境中反复练习如何“递送”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "dìsòng".', 'Người học nên luyện tập cách giao, chuyển phát rõ ràng trong tình huống thực tế.', 'Mua sắm & dịch vụ', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0193', 'exchange', '调换', 'diàohuàn', '/ɪksˈtʃeɪndʒ/', 'đổi hàng', 'verb', 'Please make sure to exchange carefully before moving to the next step.', '在进入下一步之前，请务必认真“调换”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "diàohuàn".', 'Hãy nhớ đổi hàng cẩn thận trước khi chuyển sang bước tiếp theo.', 'Mua sắm & dịch vụ', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0194', 'afford', '负担得起', 'fùdān de qǐ', '/əˈfɔːrd/', 'đủ khả năng chi trả', 'verb', 'Our supervisor asked us to afford without unnecessary delay.', '主管要求我们不要拖延，尽快“负担得起”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "fùdān de qǐ".', 'Quản lý đề nghị chúng tôi đủ khả năng chi trả kịp thời, không trì hoãn.', 'Mua sắm & dịch vụ', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0195', 'cheerful', '愉快的', 'yúkuài de', '/ˈtʃɪrfəl/', 'vui vẻ', 'adjective', 'The report highlighted a cheerful factor that shaped the final decision.', '报告重点指出了一项“愉快的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "yúkuài de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố vui vẻ đã tác động tới quyết định cuối cùng.', 'Tính cách & thái độ', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0196', 'thoughtful', '体贴的', 'tǐtiē de', '/ˈθɔːtfəl/', 'chu đáo', 'adjective', 'It is important to stay thoughtful when handling complex tasks.', '在处理复杂任务时，保持“体贴的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "tǐtiē de" fēicháng zhòngyào.', 'Giữ được tính chất chu đáo rất quan trọng khi xử lý công việc phức tạp.', 'Tính cách & thái độ', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0197', 'humble', '谦虚的', 'qiānxū de', '/ˈhʌmbəl/', 'khiêm tốn', 'adjective', 'Many readers found the explanation humble and easy to follow.', '许多读者认为这段解释十分“谦虚的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "qiānxū de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất khiêm tốn và dễ theo dõi.', 'Tính cách & thái độ', 1, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0198', 'stubborn', '固执的', 'gùzhí de', '/ˈstʌbərn/', 'bướng bỉnh', 'adjective', 'The report highlighted a stubborn factor that shaped the final decision.', '报告重点指出了一项“固执的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "gùzhí de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố bướng bỉnh đã tác động tới quyết định cuối cùng.', 'Tính cách & thái độ', 1, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0199', 'anxious', '焦虑的', 'jiāolǜ de', '/ˈæŋkʃəs/', 'lo âu', 'adjective', 'It is important to stay anxious when handling complex tasks.', '在处理复杂任务时，保持“焦虑的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "jiāolǜ de" fēicháng zhòngyào.', 'Giữ được tính chất lo âu rất quan trọng khi xử lý công việc phức tạp.', 'Tính cách & thái độ', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0200', 'relieved', '放心的', 'fàngxīn de', '/rɪˈliːvd/', 'nhẹ nhõm', 'adjective', 'Many readers found the explanation relieved and easy to follow.', '许多读者认为这段解释十分“放心的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "fàngxīn de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất nhẹ nhõm và dễ theo dõi.', 'Tính cách & thái độ', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0201', 'exhausted', '筋疲力尽的', 'jīnpí lìjìn de', '/ɪɡˈzɔːstɪd/', 'kiệt sức', 'adjective', 'The report highlighted a exhausted factor that shaped the final decision.', '报告重点指出了一项“筋疲力尽的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "jīnpí lìjìn de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố kiệt sức đã tác động tới quyết định cuối cùng.', 'Đời sống hàng ngày', 1, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
