INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0206', 'portable', '便携的', 'biànxié de', '/ˈpɔːrtəbəl/', 'di động, nhỏ gọn', 'adjective', 'Many readers found the explanation portable and easy to follow.', '许多读者认为这段解释十分“便携的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "biànxié de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất di động, nhỏ gọn và dễ theo dõi.', 'Đồ dùng cá nhân', 1, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0207', 'affordable', '实惠的', 'shíhuì de', '/əˈfɔːrdəbəl/', 'giá cả phải chăng', 'adjective', 'The report highlighted a affordable factor that shaped the final decision.', '报告重点指出了一项“实惠的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "shíhuì de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố giá cả phải chăng đã tác động tới quyết định cuối cùng.', 'Mua sắm & dịch vụ', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0208', 'reasonable', '合理的', 'hélǐ de', '/ˈriːzənəbəl/', 'hợp lý', 'adjective', 'It is important to stay reasonable when handling complex tasks.', '在处理复杂任务时，保持“合理的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "hélǐ de" fēicháng zhòngyào.', 'Giữ được tính chất hợp lý rất quan trọng khi xử lý công việc phức tạp.', 'Mua sắm & dịch vụ', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0209', 'essential', '必不可少的', 'bìbùkěshǎo de', '/ɪˈsenʃəl/', 'thiết yếu', 'adjective', 'Many readers found the explanation essential and easy to follow.', '许多读者认为这段解释十分“必不可少的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "bìbùkěshǎo de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất thiết yếu và dễ theo dõi.', 'Đời sống hàng ngày', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0210', 'ordinary', '普通的', 'pǔtōng de', '/ˈɔːrdəneri/', 'bình thường', 'adjective', 'The report highlighted a ordinary factor that shaped the final decision.', '报告重点指出了一项“普通的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "pǔtōng de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố bình thường đã tác động tới quyết định cuối cùng.', 'Đời sống hàng ngày', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0211', 'familiar', '熟悉的', 'shúxī de', '/fəˈmɪljər/', 'quen thuộc', 'adjective', 'It is important to stay familiar when handling complex tasks.', '在处理复杂任务时，保持“熟悉的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "shúxī de" fēicháng zhòngyào.', 'Giữ được tính chất quen thuộc rất quan trọng khi xử lý công việc phức tạp.', 'Đời sống hàng ngày', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0212', 'rarely', '很少', 'hěnshǎo', '/ˈrerli/', 'hiếm khi', 'adverb', 'She spoke rarely so that everyone in the room could follow.', '她“很少”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "hěnshǎo" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày hiếm khi để mọi người trong phòng đều dễ dàng theo kịp.', 'Tần suất & cách thức', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0213', 'barely', '几乎不', 'jīhū bù', '/ˈberli/', 'hầu như không', 'adverb', 'The situation changed barely over the past few months.', '在过去几个月里，情况“几乎不”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "jīhū bù" fāshēng le biànhuà.', 'Tình hình đã thay đổi hầu như không trong vài tháng vừa qua.', 'Tần suất & cách thức', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0214', 'roughly', '大约', 'dàyuē', '/ˈrʌfli/', 'khoảng chừng', 'adverb', 'She spoke roughly so that everyone in the room could follow.', '她“大约”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "dàyuē" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày khoảng chừng để mọi người trong phòng đều dễ dàng theo kịp.', 'Tần suất & cách thức', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0215', 'precisely', '精确地', 'jīngquè de', '/prɪˈsaɪsli/', 'chính xác', 'adverb', 'The situation changed precisely over the past few months.', '在过去几个月里，情况“精确地”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "jīngquè de" fāshēng le biànhuà.', 'Tình hình đã thay đổi chính xác trong vài tháng vừa qua.', 'Tần suất & cách thức', 1, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0216', 'honestly', '诚实地', 'chéngshí de', '/ˈɑːnɪstli/', 'thành thật mà nói', 'adverb', 'She spoke honestly so that everyone in the room could follow.', '她“诚实地”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "chéngshí de" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày thành thật mà nói để mọi người trong phòng đều dễ dàng theo kịp.', 'Tần suất & cách thức', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0217', 'fortunately', '幸运地', 'xìngyùn de', '/ˈfɔːrtʃənətli/', 'may mắn thay', 'adverb', 'The situation changed fortunately over the past few months.', '在过去几个月里，情况“幸运地”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "xìngyùn de" fāshēng le biànhuà.', 'Tình hình đã thay đổi may mắn thay trong vài tháng vừa qua.', 'Tần suất & cách thức', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0218', 'unfortunately', '不幸地', 'bùxìng de', '/ʌnˈfɔːrtʃənətli/', 'tiếc thay', 'adverb', 'She spoke unfortunately so that everyone in the room could follow.', '她“不幸地”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "bùxìng de" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày tiếc thay để mọi người trong phòng đều dễ dàng theo kịp.', 'Tần suất & cách thức', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0219', 'in particular', '特别是', 'tèbié shì', '/ɪn pərˈtɪkjələr/', 'đặc biệt là', 'phrase', 'Try to in particular whenever you need a clear and practical phrasing.', '在需要清晰表达时，不妨尝试使用“特别是”。', 'Zài xūyào qīngxī biǎodá shí, bùfáng chángshì shǐyòng "tèbié shì".', 'Hãy thử vận dụng cách diễn đạt “đặc biệt là” khi cần nói ngắn gọn, rõ ý.', 'Cụm từ giao tiếp', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0220', 'for instance', '例如', 'lìrú', '/fɔːr ˈɪnstəns/', 'ví dụ như', 'phrase', 'You can use the expression ''for instance'' naturally in everyday conversation.', '在日常交流中，你可以自然地使用“例如”这一表达。', 'Zài rìcháng jiāoliú zhōng, nǐ kěyǐ zìrán de shǐyòng "lìrú" zhè yī biǎodá.', 'Bạn có thể dùng cụm “for instance” (ví dụ như) một cách tự nhiên trong giao tiếp hàng ngày.', 'Cụm từ giao tiếp', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0221', 'on purpose', '故意地', 'gùyì de', '/ɑːn ˈpɜːrpəs/', 'cố ý', 'phrase', 'Try to on purpose whenever you need a clear and practical phrasing.', '在需要清晰表达时，不妨尝试使用“故意地”。', 'Zài xūyào qīngxī biǎodá shí, bùfáng chángshì shǐyòng "gùyì de".', 'Hãy thử vận dụng cách diễn đạt “cố ý” khi cần nói ngắn gọn, rõ ý.', 'Cụm từ giao tiếp', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0222', 'at once', '立刻', 'lìkè', '/æt wʌns/', 'ngay lập tức', 'phrase', 'You can use the expression ''at once'' naturally in everyday conversation.', '在日常交流中，你可以自然地使用“立刻”这一表达。', 'Zài rìcháng jiāoliú zhōng, nǐ kěyǐ zìrán de shǐyòng "lìkè" zhè yī biǎodá.', 'Bạn có thể dùng cụm “at once” (ngay lập tức) một cách tự nhiên trong giao tiếp hàng ngày.', 'Cụm từ giao tiếp', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
