INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0241', 'curriculum', '课程体系', 'kèchéng tǐxì', '/kəˈrɪkjələm/', 'chương trình giảng dạy', 'noun', 'The team reviewed the details about ''curriculum'' before the meeting.', '团队在会议前仔细核对了关于“课程体系”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "kèchéng tǐxì" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “chương trình giảng dạy” trước cuộc họp.', 'Giáo dục đại học', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0242', 'assignment', '作业', 'zuòyè', '/əˈsaɪnmənt/', 'bài tập được giao', 'noun', 'We discussed ''assignment'' during today''s lesson on academic study.', '我们在今天的课程中重点讨论了“作业”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "zuòyè".', 'Chúng tôi đã thảo luận trọng tâm về “bài tập được giao” trong buổi học hôm nay.', 'Học tập & thi cử', 2, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0243', 'essay', '论文', 'lùnwén', '/ˈeseɪ/', 'bài tiểu luận', 'noun', 'Clear notes on ''essay'' help learners recall the concept faster.', '关于“论文”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "lùnwén" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “bài tiểu luận” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Học tập & thi cử', 2, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0244', 'thesis', '学位论文', 'xuéwèi lùnwén', '/ˈθiːsɪs/', 'luận văn', 'noun', 'Understanding the role of ''thesis'' is essential in academic study.', '在相关场景中，理解“学位论文”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "xuéwèi lùnwén" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “luận văn” rất quan trọng trong chủ đề Nghiên cứu học thuật.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
