INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0267', 'summary', '总结', 'zǒngjié', '/ˈsʌməri/', 'bản tóm tắt', 'noun', 'Clear notes on ''summary'' help learners recall the concept faster.', '关于“总结”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "zǒngjié" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “bản tóm tắt” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Học tập & thi cử', 2, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0268', 'enroll', '注册入学', 'zhùcè rùxué', '/ɪnˈroʊl/', 'ghi danh', 'verb', 'Please make sure to enroll carefully before moving to the next step.', '在进入下一步之前，请务必认真“注册入学”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "zhùcè rùxué".', 'Hãy nhớ ghi danh cẩn thận trước khi chuyển sang bước tiếp theo.', 'Giáo dục đại học', 2, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0269', 'memorize', '记住', 'jìzhù', '/ˈmeməraɪz/', 'ghi nhớ, học thuộc', 'verb', 'Our supervisor asked us to memorize without unnecessary delay.', '主管要求我们不要拖延，尽快“记住”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "jìzhù".', 'Quản lý đề nghị chúng tôi ghi nhớ, học thuộc kịp thời, không trì hoãn.', 'Học tập & thi cử', 2, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0270', 'review', '复习', 'fùxí', '/rɪˈvjuː/', 'ôn tập', 'verb', 'Learners should practice how to review clearly in real situations.', '学习者应在实际情境中反复练习如何“复习”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "fùxí".', 'Người học nên luyện tập cách ôn tập rõ ràng trong tình huống thực tế.', 'Học tập & thi cử', 2, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0271', 'summarize', '总结', 'zǒngjié', '/ˈsʌməraɪz/', 'tóm tắt', 'verb', 'Please make sure to summarize carefully before moving to the next step.', '在进入下一步之前，请务必认真“总结”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "zǒngjié".', 'Hãy nhớ tóm tắt cẩn thận trước khi chuyển sang bước tiếp theo.', 'Học tập & thi cử', 2, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0272', 'analyze', '分析', 'fēnxī', '/ˈænəlaɪz/', 'phân tích', 'verb', 'Our supervisor asked us to analyze without unnecessary delay.', '主管要求我们不要拖延，尽快“分析”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "fēnxī".', 'Quản lý đề nghị chúng tôi phân tích kịp thời, không trì hoãn.', 'Nghiên cứu học thuật', 2, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0273', 'evaluate', '评估', 'pínggū', '/ɪˈvæljueɪt/', 'đánh giá', 'verb', 'Learners should practice how to evaluate clearly in real situations.', '学习者应在实际情境中反复练习如何“评估”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "pínggū".', 'Người học nên luyện tập cách đánh giá rõ ràng trong tình huống thực tế.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0274', 'interpret', '解读', 'jiědú', '/ɪnˈtɜːrprɪt/', 'diễn giải', 'verb', 'Please make sure to interpret carefully before moving to the next step.', '在进入下一步之前，请务必认真“解读”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "jiědú".', 'Hãy nhớ diễn giải cẩn thận trước khi chuyển sang bước tiếp theo.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0275', 'demonstrate', '演示', 'yǎnshì', '/ˈdemənstreɪt/', 'chứng minh, minh họa', 'verb', 'Our supervisor asked us to demonstrate without unnecessary delay.', '主管要求我们不要拖延，尽快“演示”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "yǎnshì".', 'Quản lý đề nghị chúng tôi chứng minh, minh họa kịp thời, không trì hoãn.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0276', 'revise', '修改', 'xiūgǎi', '/rɪˈvaɪz/', 'chỉnh sửa, ôn lại', 'verb', 'Learners should practice how to revise clearly in real situations.', '学习者应在实际情境中反复练习如何“修改”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "xiūgǎi".', 'Người học nên luyện tập cách chỉnh sửa, ôn lại rõ ràng trong tình huống thực tế.', 'Học tập & thi cử', 2, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0277', 'submit', '提交', 'tíjiāo', '/səbˈmɪt/', 'nộp bài', 'verb', 'Please make sure to submit carefully before moving to the next step.', '在进入下一步之前，请务必认真“提交”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "tíjiāo".', 'Hãy nhớ nộp bài cẩn thận trước khi chuyển sang bước tiếp theo.', 'Học tập & thi cử', 2, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0278', 'academic', '学术的', 'xuéshù de', '/ˌækəˈdemɪk/', 'thuộc học thuật', 'adjective', 'Many readers found the explanation academic and easy to follow.', '许多读者认为这段解释十分“学术的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "xuéshù de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất thuộc học thuật và dễ theo dõi.', 'Nghiên cứu học thuật', 2, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0279', 'theoretical', '理论的', 'lǐlùn de', '/ˌθiːəˈretɪkəl/', 'mang tính lý thuyết', 'adjective', 'The report highlighted a theoretical factor that shaped the final decision.', '报告重点指出了一项“理论的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "lǐlùn de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố mang tính lý thuyết đã tác động tới quyết định cuối cùng.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0280', 'practical', '实用的', 'shíyòng de', '/ˈpræktɪkəl/', 'thực tiễn', 'adjective', 'It is important to stay practical when handling complex tasks.', '在处理复杂任务时，保持“实用的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "shíyòng de" fēicháng zhòngyào.', 'Giữ được tính chất thực tiễn rất quan trọng khi xử lý công việc phức tạp.', 'Học tập & thi cử', 2, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0281', 'logical', '合乎逻辑的', 'héhū luóji de', '/ˈlɑːdʒɪkəl/', 'hợp logic', 'adjective', 'Many readers found the explanation logical and easy to follow.', '许多读者认为这段解释十分“合乎逻辑的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "héhū luóji de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất hợp logic và dễ theo dõi.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0282', 'thorough', '彻底的', 'chèdǐ de', '/ˈθɜːroʊ/', 'kỹ lưỡng', 'adjective', 'The report highlighted a thorough factor that shaped the final decision.', '报告重点指出了一项“彻底的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "chèdǐ de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố kỹ lưỡng đã tác động tới quyết định cuối cùng.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0283', 'organism', '生物体', 'shēngwùtǐ', '/ˈɔːrɡənɪzəm/', 'sinh vật', 'noun', 'Clear notes on ''organism'' help learners recall the concept faster.', '关于“生物体”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "shēngwùtǐ" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “sinh vật” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Sinh học cơ bản', 22, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0284', 'cell', '细胞', 'xìbāo', '/sel/', 'tế bào', 'noun', 'Understanding the role of ''cell'' is essential in biology.', '在相关场景中，理解“细胞”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "xìbāo" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “tế bào” rất quan trọng trong chủ đề Sinh học cơ bản.', 'Sinh học cơ bản', 22, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0285', 'tissue', '生物组织', 'shēngwù zǔzhī', '/ˈtɪʃuː/', 'mô sinh học', 'noun', 'The team reviewed the details about ''tissue'' before the meeting.', '团队在会议前仔细核对了关于“生物组织”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "shēngwù zǔzhī" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “mô sinh học” trước cuộc họp.', 'Sinh học cơ bản', 22, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0286', 'mutation', '突变', 'tūbiàn', '/mjuːˈteɪʃən/', 'đột biến', 'noun', 'We discussed ''mutation'' during today''s lesson on biology.', '我们在今天的课程中重点讨论了“突变”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "tūbiàn".', 'Chúng tôi đã thảo luận trọng tâm về “đột biến” trong buổi học hôm nay.', 'Di truyền học', 22, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0287', 'evolution', '进化', 'jìnhuà', '/ˌevəˈluːʃən/', 'tiến hóa', 'noun', 'Clear notes on ''evolution'' help learners recall the concept faster.', '关于“进化”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "jìnhuà" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “tiến hóa” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Sinh học cơ bản', 22, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0288', 'species', '物种', 'wùzhǒng', '/ˈspiːʃiːz/', 'loài sinh vật', 'noun', 'Understanding the role of ''species'' is essential in biology.', '在相关场景中，理解“物种”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "wùzhǒng" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “loài sinh vật” rất quan trọng trong chủ đề Sinh thái học.', 'Sinh thái học', 22, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0289', 'bacteria', '细菌', 'xìjūn', '/bækˈtɪriə/', 'vi khuẩn', 'noun', 'The team reviewed the details about ''bacteria'' before the meeting.', '团队在会议前仔细核对了关于“细菌”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "xìjūn" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “vi khuẩn” trước cuộc họp.', 'Vi sinh vật', 22, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0290', 'virus', '病毒', 'bìngdú', '/ˈvaɪrəs/', 'vi rút', 'noun', 'We discussed ''virus'' during today''s lesson on biology.', '我们在今天的课程中重点讨论了“病毒”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "bìngdú".', 'Chúng tôi đã thảo luận trọng tâm về “vi rút” trong buổi học hôm nay.', 'Vi sinh vật', 22, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0291', 'antibody', '抗体', 'kàngtǐ', '/ˈæntɪbɑːdi/', 'kháng thể', 'noun', 'Clear notes on ''antibody'' help learners recall the concept faster.', '关于“抗体”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "kàngtǐ" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “kháng thể” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Miễn dịch học', 22, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0292', 'photosynthesis', '光合作用', 'guānghé zuòyòng', '/ˌfoʊtoʊˈsɪnθəsɪs/', 'quang hợp', 'noun', 'Understanding the role of ''photosynthesis'' is essential in biology.', '在相关场景中，理解“光合作用”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "guānghé zuòyòng" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “quang hợp” rất quan trọng trong chủ đề Sinh học thực vật.', 'Sinh học thực vật', 22, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0293', 'metabolism', '新陈代谢', 'xīnchén dàixiè', '/məˈtæbəlɪzəm/', 'trao đổi chất', 'noun', 'The team reviewed the details about ''metabolism'' before the meeting.', '团队在会议前仔细核对了关于“新陈代谢”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "xīnchén dàixiè" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “trao đổi chất” trước cuộc họp.', 'Sinh học cơ bản', 22, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0294', 'genetics', '遗传学', 'yíchuánxué', '/dʒəˈnetɪks/', 'di truyền học', 'noun', 'We discussed ''genetics'' during today''s lesson on biology.', '我们在今天的课程中重点讨论了“遗传学”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "yíchuánxué".', 'Chúng tôi đã thảo luận trọng tâm về “di truyền học” trong buổi học hôm nay.', 'Di truyền học', 22, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0295', 'ecosystem', '生态系统', 'shēngtài xìtǒng', '/ˈiːkoʊsɪstəm/', 'hệ sinh thái', 'noun', 'Clear notes on ''ecosystem'' help learners recall the concept faster.', '关于“生态系统”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "shēngtài xìtǒng" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “hệ sinh thái” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Sinh thái học', 22, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0296', 'molecule', '分子', 'fēnzǐ', '/ˈmɑːlɪkjuːl/', 'phân tử', 'noun', 'Understanding the role of ''molecule'' is essential in chemistry.', '在相关场景中，理解“分子”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "fēnzǐ" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “phân tử” rất quan trọng trong chủ đề Hóa học cơ bản.', 'Hóa học cơ bản', 23, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0297', 'atom', '原子', 'yuánzǐ', '/ˈætəm/', 'nguyên tử', 'noun', 'The team reviewed the details about ''atom'' before the meeting.', '团队在会议前仔细核对了关于“原子”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "yuánzǐ" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “nguyên tử” trước cuộc họp.', 'Hóa học cơ bản', 23, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0298', 'element', '化学元素', 'huàxué yuánsù', '/ˈelɪmənt/', 'nguyên tố hóa học', 'noun', 'We discussed ''element'' during today''s lesson on chemistry.', '我们在今天的课程中重点讨论了“化学元素”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "huàxué yuánsù".', 'Chúng tôi đã thảo luận trọng tâm về “nguyên tố hóa học” trong buổi học hôm nay.', 'Hóa học cơ bản', 23, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0299', 'compound', '化合物', 'huàhéwù', '/ˈkɑːmpaʊnd/', 'hợp chất', 'noun', 'Clear notes on ''compound'' help learners recall the concept faster.', '关于“化合物”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "huàhéwù" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “hợp chất” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Hóa học cơ bản', 23, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0300', 'alkali', '碱', 'jiǎn', '/ˈælkəlaɪ/', 'kiềm', 'noun', 'Understanding the role of ''alkali'' is essential in chemistry.', '在相关场景中，理解“碱”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "jiǎn" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “kiềm” rất quan trọng trong chủ đề Hóa học cơ bản.', 'Hóa học cơ bản', 23, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0301', 'oxygen', '氧气', 'yǎngqì', '/ˈɑːksɪdʒən/', 'khí oxy', 'noun', 'The team reviewed the details about ''oxygen'' before the meeting.', '团队在会议前仔细核对了关于“氧气”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "yǎngqì" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “khí oxy” trước cuộc họp.', 'Hóa học cơ bản', 23, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0302', 'hydrogen', '氢气', 'qīngqì', '/ˈhaɪdrədʒən/', 'khí hydro', 'noun', 'We discussed ''hydrogen'' during today''s lesson on chemistry.', '我们在今天的课程中重点讨论了“氢气”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "qīngqì".', 'Chúng tôi đã thảo luận trọng tâm về “khí hydro” trong buổi học hôm nay.', 'Hóa học cơ bản', 23, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0303', 'carbon', '碳', 'tàn', '/ˈkɑːrbən/', 'cacbon', 'noun', 'Clear notes on ''carbon'' help learners recall the concept faster.', '关于“碳”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "tàn" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “cacbon” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Hóa học cơ bản', 23, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0304', 'dissolve', '溶解', 'róngjiě', '/dɪˈzɑːlv/', 'hòa tan', 'verb', 'Please make sure to dissolve carefully before moving to the next step.', '在进入下一步之前，请务必认真“溶解”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "róngjiě".', 'Hãy nhớ hòa tan cẩn thận trước khi chuyển sang bước tiếp theo.', 'Phản ứng hóa học', 23, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0305', 'evaporate', '蒸发', 'zhēngfā', '/ɪˈvæpəreɪt/', 'bay hơi', 'verb', 'Our supervisor asked us to evaporate without unnecessary delay.', '主管要求我们不要拖延，尽快“蒸发”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "zhēngfā".', 'Quản lý đề nghị chúng tôi bay hơi kịp thời, không trì hoãn.', 'Phản ứng hóa học', 23, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0306', 'oxidize', '氧化', 'yǎnghuà', '/ˈɑːksɪdaɪz/', 'oxy hóa', 'verb', 'Learners should practice how to oxidize clearly in real situations.', '学习者应在实际情境中反复练习如何“氧化”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "yǎnghuà".', 'Người học nên luyện tập cách oxy hóa rõ ràng trong tình huống thực tế.', 'Phản ứng hóa học', 23, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0307', 'synthetic', '合成的', 'héchéng de', '/sɪnˈθetɪk/', 'tổng hợp nhân tạo', 'adjective', 'It is important to stay synthetic when handling complex tasks.', '在处理复杂任务时，保持“合成的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "héchéng de" fēicháng zhòngyào.', 'Giữ được tính chất tổng hợp nhân tạo rất quan trọng khi xử lý công việc phức tạp.', 'Hóa học vật liệu', 23, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0308', 'friction', '摩擦力', 'mócālì', '/ˈfrɪkʃən/', 'lực ma sát', 'noun', 'Understanding the role of ''friction'' is essential in physics and astronomy.', '在相关场景中，理解“摩擦力”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "mócālì" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “lực ma sát” rất quan trọng trong chủ đề Cơ học.', 'Cơ học', 24, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
