INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0315', 'atmosphere', '大气层', 'dàqìcéng', '/ˈætməsfɪr/', 'khí quyển', 'noun', 'Clear notes on ''atmosphere'' help learners recall the concept faster.', '关于“大气层”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "dàqìcéng" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “khí quyển” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Thiên văn học', 24, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0316', 'spectrum', '光谱', 'guāngpǔ', '/ˈspektrəm/', 'quang phổ', 'noun', 'Understanding the role of ''spectrum'' is essential in physics and astronomy.', '在相关场景中，理解“光谱”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "guāngpǔ" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “quang phổ” rất quan trọng trong chủ đề Quang học & sóng.', 'Quang học & sóng', 24, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0317', 'refract', '折射', 'zhéshè', '/rɪˈfrækt/', 'khúc xạ', 'verb', 'Our supervisor asked us to refract without unnecessary delay.', '主管要求我们不要拖延，尽快“折射”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "zhéshè".', 'Quản lý đề nghị chúng tôi khúc xạ kịp thời, không trì hoãn.', 'Quang học & sóng', 24, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0318', 'equation', '方程', 'fāngchéng', '/ɪˈkweɪʒən/', 'phương trình', 'noun', 'We discussed ''equation'' during today''s lesson on mathematics.', '我们在今天的课程中重点讨论了“方程”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "fāngchéng".', 'Chúng tôi đã thảo luận trọng tâm về “phương trình” trong buổi học hôm nay.', 'Đại số', 25, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0319', 'decimal', '小数', 'xiǎoshù', '/ˈdesɪməl/', 'số thập phân', 'noun', 'Clear notes on ''decimal'' help learners recall the concept faster.', '关于“小数”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "xiǎoshù" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “số thập phân” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Số học', 25, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0320', 'percentage', '百分比', 'bǎifēnbǐ', '/pərˈsentɪdʒ/', 'tỷ lệ phần trăm', 'noun', 'Understanding the role of ''percentage'' is essential in mathematics.', '在相关场景中，理解“百分比”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "bǎifēnbǐ" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “tỷ lệ phần trăm” rất quan trọng trong chủ đề Số học.', 'Số học', 25, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
