INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0339', 'symmetry', '对称', 'duìchèn', '/ˈsɪmətri/', 'tính đối xứng', 'noun', 'Clear notes on ''symmetry'' help learners recall the concept faster.', '关于“对称”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "duìchèn" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “tính đối xứng” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Thiết kế đồ họa', 37, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0340', 'exhibition', '展览', 'zhǎnlǎn', '/ˌeksɪˈbɪʃən/', 'triển lãm', 'noun', 'Understanding the role of ''exhibition'' is essential in art and design.', '在相关场景中，理解“展览”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "zhǎnlǎn" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “triển lãm” rất quan trọng trong chủ đề Mỹ thuật.', 'Mỹ thuật', 37, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0341', 'gallery', '画廊', 'huàláng', '/ˈɡæləri/', 'phòng trưng bày tranh', 'noun', 'The team reviewed the details about ''gallery'' before the meeting.', '团队在会议前仔细核对了关于“画廊”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "huàláng" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “phòng trưng bày tranh” trước cuộc họp.', 'Mỹ thuật', 37, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0342', 'craftsmanship', '工艺', 'gōngyì', '/ˈkræftsmənʃɪp/', 'tay nghề thủ công', 'noun', 'We discussed ''craftsmanship'' during today''s lesson on art and design.', '我们在今天的课程中重点讨论了“工艺”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "gōngyì".', 'Chúng tôi đã thảo luận trọng tâm về “tay nghề thủ công” trong buổi học hôm nay.', 'Thủ công mỹ nghệ', 37, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0343', 'minimalist', '极简主义的', 'jíjiǎn zhǔyì de', '/ˈmɪnɪməlɪst/', 'tối giản', 'adjective', 'It is important to stay minimalist when handling complex tasks.', '在处理复杂任务时，保持“极简主义的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "jíjiǎn zhǔyì de" fēicháng zhòngyào.', 'Giữ được tính chất tối giản rất quan trọng khi xử lý công việc phức tạp.', 'Thiết kế đồ họa', 37, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0344', 'aesthetic', '审美的', 'shěnměi de', '/esˈθetɪk/', 'thuộc thẩm mỹ', 'adjective', 'Many readers found the explanation aesthetic and easy to follow.', '许多读者认为这段解释十分“审美的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "shěnměi de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất thuộc thẩm mỹ và dễ theo dõi.', 'Mỹ thuật', 37, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
