INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0358', 'compose', '作曲', 'zuòqǔ', '/kəmˈpoʊz/', 'sáng tác nhạc', 'verb', 'Please make sure to compose carefully before moving to the next step.', '在进入下一步之前，请务必认真“作曲”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "zuòqǔ".', 'Hãy nhớ sáng tác nhạc cẩn thận trước khi chuyển sang bước tiếp theo.', 'Âm nhạc', 38, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0359', 'perform', '演出', 'yǎnchū', '/pərˈfɔːrm/', 'biểu diễn', 'verb', 'Our supervisor asked us to perform without unnecessary delay.', '主管要求我们不要拖延，尽快“演出”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "yǎnchū".', 'Quản lý đề nghị chúng tôi biểu diễn kịp thời, không trì hoãn.', 'Biểu diễn', 38, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0360', 'capture', '捕捉画面', 'bǔzhuō huàmiàn', '/ˈkæptʃər/', 'ghi lại khoảnh khắc', 'verb', 'Learners should practice how to capture clearly in real situations.', '学习者应在实际情境中反复练习如何“捕捉画面”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "bǔzhuō huàmiàn".', 'Người học nên luyện tập cách ghi lại khoảnh khắc rõ ràng trong tình huống thực tế.', 'Nhiếp ảnh', 38, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0361', 'edit', '剪辑', 'jiǎnjí', '/ˈedɪt/', 'biên tập, dựng phim', 'verb', 'Please make sure to edit carefully before moving to the next step.', '在进入下一步之前，请务必认真“剪辑”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "jiǎnjí".', 'Hãy nhớ biên tập, dựng phim cẩn thận trước khi chuyển sang bước tiếp theo.', 'Điện ảnh', 38, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
