INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0363', 'journal', '学术期刊', 'xuéshù qīkān', '/ˈdʒɜːrnəl/', 'tạp chí khoa học', 'noun', 'Clear notes on ''journal'' help learners recall the concept faster.', '关于“学术期刊”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "xuéshù qīkān" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “tạp chí khoa học” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0364', 'monograph', '专著', 'zhuānzhù', '/ˈmɑːnəɡræf/', 'chuyên khảo', 'noun', 'Understanding the role of ''monograph'' is essential in academic study.', '在相关场景中，理解“专著”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "zhuānzhù" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “chuyên khảo” rất quan trọng trong chủ đề Nghiên cứu học thuật.', 'Nghiên cứu học thuật', 2, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0365', 'peer review', '同行评审', 'tóngháng píngshěn', '/pɪr rɪˈvjuː/', 'phản biện đồng cấp', 'noun', 'The team reviewed the details about ''peer review'' before the meeting.', '团队在会议前仔细核对了关于“同行评审”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "tóngháng píngshěn" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “phản biện đồng cấp” trước cuộc họp.', 'Nghiên cứu học thuật', 2, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0366', 'benchmark', '基准', 'jīzhǔn', '/ˈbentʃmɑːrk/', 'chuẩn đối sánh', 'noun', 'We discussed ''benchmark'' during today''s lesson on academic study.', '我们在今天的课程中重点讨论了“基准”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "jīzhǔn".', 'Chúng tôi đã thảo luận trọng tâm về “chuẩn đối sánh” trong buổi học hôm nay.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0367', 'criterion', '标准', 'biāozhǔn', '/kraɪˈtɪriən/', 'tiêu chí', 'noun', 'Clear notes on ''criterion'' help learners recall the concept faster.', '关于“标准”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "biāozhǔn" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “tiêu chí” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
