INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0373', 'argument', '论点', 'lùndiǎn', '/ˈɑːrɡjumənt/', 'lập luận', 'noun', 'The team reviewed the details about ''argument'' before the meeting.', '团队在会议前仔细核对了关于“论点”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "lùndiǎn" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “lập luận” trước cuộc họp.', 'Nghiên cứu học thuật', 2, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0374', 'counterargument', '反论点', 'fǎnlùndiǎn', '/ˈkaʊntərɑːrɡjumənt/', 'luận điểm phản biện', 'noun', 'We discussed ''counterargument'' during today''s lesson on academic study.', '我们在今天的课程中重点讨论了“反论点”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "fǎnlùndiǎn".', 'Chúng tôi đã thảo luận trọng tâm về “luận điểm phản biện” trong buổi học hôm nay.', 'Nghiên cứu học thuật', 2, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0375', 'assumption', '前提假设', 'qiántí jiǎshè', '/əˈsʌmpʃən/', 'giả định', 'noun', 'Clear notes on ''assumption'' help learners recall the concept faster.', '关于“前提假设”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "qiántí jiǎshè" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “giả định” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0376', 'implication', '含义', 'hányì', '/ˌɪmplɪˈkeɪʃən/', 'hàm ý, hệ quả', 'noun', 'Understanding the role of ''implication'' is essential in academic study.', '在相关场景中，理解“含义”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "hányì" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “hàm ý, hệ quả” rất quan trọng trong chủ đề Nghiên cứu học thuật.', 'Nghiên cứu học thuật', 2, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0377', 'classify', '分类', 'fēnlèi', '/ˈklæsɪfaɪ/', 'phân loại', 'verb', 'Our supervisor asked us to classify without unnecessary delay.', '主管要求我们不要拖延，尽快“分类”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "fēnlèi".', 'Quản lý đề nghị chúng tôi phân loại kịp thời, không trì hoãn.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0378', 'distinguish', '区分', 'qūfēn', '/dɪˈstɪŋɡwɪʃ/', 'phân biệt', 'verb', 'Learners should practice how to distinguish clearly in real situations.', '学习者应在实际情境中反复练习如何“区分”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "qūfēn".', 'Người học nên luyện tập cách phân biệt rõ ràng trong tình huống thực tế.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0379', 'illustrate', '举例说明', 'jǔlì shuōmíng', '/ˈɪləstreɪt/', 'minh họa', 'verb', 'Please make sure to illustrate carefully before moving to the next step.', '在进入下一步之前，请务必认真“举例说明”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "jǔlì shuōmíng".', 'Hãy nhớ minh họa cẩn thận trước khi chuyển sang bước tiếp theo.', 'Nghiên cứu học thuật', 2, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0380', 'investigate', '调查研究', 'diàochá yánjiū', '/ɪnˈvestɪɡeɪt/', 'điều tra, khảo cứu', 'verb', 'Our supervisor asked us to investigate without unnecessary delay.', '主管要求我们不要拖延，尽快“调查研究”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "diàochá yánjiū".', 'Quản lý đề nghị chúng tôi điều tra, khảo cứu kịp thời, không trì hoãn.', 'Nghiên cứu học thuật', 2, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0381', 'verify', '核实', 'héshí', '/ˈverɪfaɪ/', 'xác minh', 'verb', 'Learners should practice how to verify clearly in real situations.', '学习者应在实际情境中反复练习如何“核实”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "héshí".', 'Người học nên luyện tập cách xác minh rõ ràng trong tình huống thực tế.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0382', 'cite', '引用', 'yǐnyòng', '/saɪt/', 'trích dẫn', 'verb', 'Please make sure to cite carefully before moving to the next step.', '在进入下一步之前，请务必认真“引用”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "yǐnyòng".', 'Hãy nhớ trích dẫn cẩn thận trước khi chuyển sang bước tiếp theo.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0383', 'paraphrase', '改写转述', 'gǎixiě zhuǎnshù', '/ˈpærəfreɪz/', 'diễn đạt lại', 'verb', 'Our supervisor asked us to paraphrase without unnecessary delay.', '主管要求我们不要拖延，尽快“改写转述”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "gǎixiě zhuǎnshù".', 'Quản lý đề nghị chúng tôi diễn đạt lại kịp thời, không trì hoãn.', 'Học tập & thi cử', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0384', 'translate', '翻译', 'fānyì', '/trænzˈleɪt/', 'dịch thuật', 'verb', 'Learners should practice how to translate clearly in real situations.', '学习者应在实际情境中反复练习如何“翻译”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "fānyì".', 'Người học nên luyện tập cách dịch thuật rõ ràng trong tình huống thực tế.', 'Học tập & thi cử', 2, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0385', 'pronounce', '发音', 'fāyīn', '/prəˈnaʊns/', 'phát âm', 'verb', 'Please make sure to pronounce carefully before moving to the next step.', '在进入下一步之前，请务必认真“发音”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "fāyīn".', 'Hãy nhớ phát âm cẩn thận trước khi chuyển sang bước tiếp theo.', 'Học tập & thi cử', 2, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0386', 'spell', '拼写', 'pīnxiě', '/spel/', 'đánh vần', 'verb', 'Our supervisor asked us to spell without unnecessary delay.', '主管要求我们不要拖延，尽快“拼写”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "pīnxiě".', 'Quản lý đề nghị chúng tôi đánh vần kịp thời, không trì hoãn.', 'Học tập & thi cử', 2, 'A1', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0387', 'coherent', '连贯的', 'liánguàn de', '/koʊˈhɪrənt/', 'mạch lạc', 'adjective', 'The report highlighted a coherent factor that shaped the final decision.', '报告重点指出了一项“连贯的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "liánguàn de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố mạch lạc đã tác động tới quyết định cuối cùng.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0388', 'concise', '简明的', 'jiǎnmíng de', '/kənˈsaɪs/', 'súc tích', 'adjective', 'It is important to stay concise when handling complex tasks.', '在处理复杂任务时，保持“简明的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "jiǎnmíng de" fēicháng zhòngyào.', 'Giữ được tính chất súc tích rất quan trọng khi xử lý công việc phức tạp.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0389', 'objective', '客观的', 'kèguān de', '/əbˈdʒektɪv/', 'khách quan', 'adjective', 'Many readers found the explanation objective and easy to follow.', '许多读者认为这段解释十分“客观的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "kèguān de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất khách quan và dễ theo dõi.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0390', 'subjective', '主观的', 'zhǔguān de', '/səbˈdʒektɪv/', 'chủ quan', 'adjective', 'The report highlighted a subjective factor that shaped the final decision.', '报告重点指出了一项“主观的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "zhǔguān de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố chủ quan đã tác động tới quyết định cuối cùng.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
