INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0394', 'significant', '显著的', 'xiǎnzhù de', '/sɪɡˈnɪfɪkənt/', 'đáng kể', 'adjective', 'It is important to stay significant when handling complex tasks.', '在处理复杂任务时，保持“显著的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "xiǎnzhù de" fēicháng zhòngyào.', 'Giữ được tính chất đáng kể rất quan trọng khi xử lý công việc phức tạp.', 'Nghiên cứu học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
