INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0397', 'startup', '初创企业', 'chūchuàng qǐyè', '/ˈstɑːrtʌp/', 'doanh nghiệp khởi nghiệp', 'noun', 'The team reviewed the details about ''startup'' before the meeting.', '团队在会议前仔细核对了关于“初创企业”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "chūchuàng qǐyè" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “doanh nghiệp khởi nghiệp” trước cuộc họp.', 'Khởi nghiệp & kinh doanh', 3, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0398', 'entrepreneur', '创业者', 'chuàngyèzhě', '/ˌɑːntrəprəˈnɜːr/', 'doanh nhân khởi nghiệp', 'noun', 'We discussed ''entrepreneur'' during today''s lesson on business operations.', '我们在今天的课程中重点讨论了“创业者”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "chuàngyèzhě".', 'Chúng tôi đã thảo luận trọng tâm về “doanh nhân khởi nghiệp” trong buổi học hôm nay.', 'Khởi nghiệp & kinh doanh', 3, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0399', 'competitor', '竞争对手', 'jìngzhēng duìshǒu', '/kəmˈpetɪtər/', 'đối thủ cạnh tranh', 'noun', 'Clear notes on ''competitor'' help learners recall the concept faster.', '关于“竞争对手”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "jìngzhēng duìshǒu" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “đối thủ cạnh tranh” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Chiến lược kinh doanh', 3, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0400', 'stakeholder', '利益相关方', 'lìyì xiāngguānfāng', '/ˈsteɪkhoʊldər/', 'bên liên quan', 'noun', 'Understanding the role of ''stakeholder'' is essential in business operations.', '在相关场景中，理解“利益相关方”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "lìyì xiāngguānfāng" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “bên liên quan” rất quan trọng trong chủ đề Chiến lược kinh doanh.', 'Chiến lược kinh doanh', 3, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
