INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0409', 'supply', '市场供给', 'shìchǎng gōngjǐ', '/səˈplaɪ/', 'nguồn cung', 'noun', 'The team reviewed the details about ''supply'' before the meeting.', '团队在会议前仔细核对了关于“市场供给”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "shìchǎng gōngjǐ" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “nguồn cung” trước cuộc họp.', 'Kinh tế học', 3, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0410', 'surplus', '盈余', 'yíngyú', '/ˈsɜːrpləs/', 'thặng dư', 'noun', 'We discussed ''surplus'' during today''s lesson on business operations.', '我们在今天的课程中重点讨论了“盈余”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "yíngyú".', 'Chúng tôi đã thảo luận trọng tâm về “thặng dư” trong buổi học hôm nay.', 'Kinh tế học', 3, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0411', 'negotiate', '谈判', 'tánpàn', '/nɪˈɡoʊʃieɪt/', 'đàm phán', 'verb', 'Learners should practice how to negotiate clearly in real situations.', '学习者应在实际情境中反复练习如何“谈判”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "tánpàn".', 'Người học nên luyện tập cách đàm phán rõ ràng trong tình huống thực tế.', 'Giao dịch kinh doanh', 3, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0412', 'expand', '扩张', 'kuòzhāng', '/ɪkˈspænd/', 'mở rộng', 'verb', 'Please make sure to expand carefully before moving to the next step.', '在进入下一步之前，请务必认真“扩张”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "kuòzhāng".', 'Hãy nhớ mở rộng cẩn thận trước khi chuyển sang bước tiếp theo.', 'Chiến lược kinh doanh', 3, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0413', 'merge', '合并', 'hébìng', '/mɜːrdʒ/', 'sáp nhập', 'verb', 'Our supervisor asked us to merge without unnecessary delay.', '主管要求我们不要拖延，尽快“合并”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "hébìng".', 'Quản lý đề nghị chúng tôi sáp nhập kịp thời, không trì hoãn.', 'Chiến lược kinh doanh', 3, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0414', 'outsource', '外包', 'wàibāo', '/ˈaʊtsɔːrs/', 'thuê ngoài', 'verb', 'Learners should practice how to outsource clearly in real situations.', '学习者应在实际情境中反复练习如何“外包”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "wàibāo".', 'Người học nên luyện tập cách thuê ngoài rõ ràng trong tình huống thực tế.', 'Vận hành doanh nghiệp', 3, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0415', 'profitable', '盈利的', 'yínglì de', '/ˈprɑːfɪtəbəl/', 'có lãi', 'adjective', 'It is important to stay profitable when handling complex tasks.', '在处理复杂任务时，保持“盈利的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "yínglì de" fēicháng zhòngyào.', 'Giữ được tính chất có lãi rất quan trọng khi xử lý công việc phức tạp.', 'Kinh doanh', 3, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0416', 'competitive', '有竞争力的', 'yǒu jìngzhēnglì de', '/kəmˈpetətɪv/', 'có sức cạnh tranh', 'adjective', 'Many readers found the explanation competitive and easy to follow.', '许多读者认为这段解释十分“有竞争力的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "yǒu jìngzhēnglì de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất có sức cạnh tranh và dễ theo dõi.', 'Chiến lược kinh doanh', 3, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0417', 'sustainable', '可持续的', 'kě chíxù de', '/səˈsteɪnəbəl/', 'bền vững', 'adjective', 'The report highlighted a sustainable factor that shaped the final decision.', '报告重点指出了一项“可持续的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "kě chíxù de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố bền vững đã tác động tới quyết định cuối cùng.', 'Chiến lược kinh doanh', 3, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0418', 'voucher', '会计凭证', 'kuàijì píngzhèng', '/ˈvaʊtʃər/', 'chứng từ kế toán', 'noun', 'We discussed ''voucher'' during today''s lesson on accounting practice.', '我们在今天的课程中重点讨论了“会计凭证”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "kuàijì píngzhèng".', 'Chúng tôi đã thảo luận trọng tâm về “chứng từ kế toán” trong buổi học hôm nay.', 'Kế toán doanh nghiệp', 4, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0419', 'receivable', '应收账款', 'yīngshōu zhàngkuǎn', '/rɪˈsiːvəbəl/', 'khoản phải thu', 'noun', 'Clear notes on ''receivable'' help learners recall the concept faster.', '关于“应收账款”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "yīngshōu zhàngkuǎn" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “khoản phải thu” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Kế toán doanh nghiệp', 4, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0420', 'payable', '应付账款', 'yīngfù zhàngkuǎn', '/ˈpeɪəbəl/', 'khoản phải trả', 'noun', 'Understanding the role of ''payable'' is essential in accounting practice.', '在相关场景中，理解“应付账款”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "yīngfù zhàngkuǎn" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “khoản phải trả” rất quan trọng trong chủ đề Kế toán doanh nghiệp.', 'Kế toán doanh nghiệp', 4, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0421', 'depreciation', '折旧', 'zhéjiù', '/dɪˌpriːʃiˈeɪʃən/', 'khấu hao', 'noun', 'The team reviewed the details about ''depreciation'' before the meeting.', '团队在会议前仔细核对了关于“折旧”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "zhéjiù" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “khấu hao” trước cuộc họp.', 'Kế toán doanh nghiệp', 4, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0422', 'amortization', '摊销', 'tānxiāo', '/ˌæmərtəˈzeɪʃən/', 'phân bổ tài sản vô hình', 'noun', 'We discussed ''amortization'' during today''s lesson on accounting practice.', '我们在今天的课程中重点讨论了“摊销”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "tānxiāo".', 'Chúng tôi đã thảo luận trọng tâm về “phân bổ tài sản vô hình” trong buổi học hôm nay.', 'Kế toán doanh nghiệp', 4, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0423', 'balance sheet', '资产负债表', 'zīchǎn fùzhàibiǎo', '/ˈbæləns ʃiːt/', 'bảng cân đối kế toán', 'noun', 'Clear notes on ''balance sheet'' help learners recall the concept faster.', '关于“资产负债表”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "zīchǎn fùzhàibiǎo" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “bảng cân đối kế toán” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Báo cáo tài chính', 4, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0424', 'income statement', '利润表', 'lìrùnbiǎo', '/ˈɪnkʌm ˈsteɪtmənt/', 'báo cáo kết quả kinh doanh', 'noun', 'Understanding the role of ''income statement'' is essential in accounting practice.', '在相关场景中，理解“利润表”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "lìrùnbiǎo" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “báo cáo kết quả kinh doanh” rất quan trọng trong chủ đề Báo cáo tài chính.', 'Báo cáo tài chính', 4, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0425', 'reconcile', '对账', 'duìzhàng', '/ˈrekənsaɪl/', 'đối chiếu sổ sách', 'verb', 'Our supervisor asked us to reconcile without unnecessary delay.', '主管要求我们不要拖延，尽快“对账”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "duìzhàng".', 'Quản lý đề nghị chúng tôi đối chiếu sổ sách kịp thời, không trì hoãn.', 'Kiểm toán', 4, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0426', 'deduct', '扣除', 'kòuchú', '/dɪˈdʌkt/', 'khấu trừ', 'verb', 'Learners should practice how to deduct clearly in real situations.', '学习者应在实际情境中反复练习如何“扣除”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "kòuchú".', 'Người học nên luyện tập cách khấu trừ rõ ràng trong tình huống thực tế.', 'Kế toán thuế', 4, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0427', 'mortgage', '抵押贷款', 'dǐyā dàikuǎn', '/ˈmɔːrɡɪdʒ/', 'khoản vay thế chấp', 'noun', 'Clear notes on ''mortgage'' help learners recall the concept faster.', '关于“抵押贷款”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "dǐyā dàikuǎn" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “khoản vay thế chấp” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Ngân hàng', 5, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0428', 'dividend', '股息', 'gǔxī', '/ˈdɪvɪdend/', 'cổ tức', 'noun', 'Understanding the role of ''dividend'' is essential in finance and banking.', '在相关场景中，理解“股息”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "gǔxī" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “cổ tức” rất quan trọng trong chủ đề Đầu tư tài chính.', 'Đầu tư tài chính', 5, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0429', 'portfolio', '投资组合', 'tóuzī zǔhé', '/pɔːrtˈfoʊlioʊ/', 'danh mục đầu tư', 'noun', 'The team reviewed the details about ''portfolio'' before the meeting.', '团队在会议前仔细核对了关于“投资组合”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "tóuzī zǔhé" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “danh mục đầu tư” trước cuộc họp.', 'Đầu tư tài chính', 5, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0430', 'bond', '债券', 'zhàiquàn', '/bɑːnd/', 'trái phiếu', 'noun', 'We discussed ''bond'' during today''s lesson on finance and banking.', '我们在今天的课程中重点讨论了“债券”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "zhàiquàn".', 'Chúng tôi đã thảo luận trọng tâm về “trái phiếu” trong buổi học hôm nay.', 'Đầu tư tài chính', 5, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0431', 'equity', '股权', 'gǔquán', '/ˈekwəti/', 'vốn chủ sở hữu', 'noun', 'Clear notes on ''equity'' help learners recall the concept faster.', '关于“股权”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "gǔquán" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “vốn chủ sở hữu” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Đầu tư tài chính', 5, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0432', 'currency', '货币', 'huòbì', '/ˈkɜːrənsi/', 'tiền tệ', 'noun', 'Understanding the role of ''currency'' is essential in finance and banking.', '在相关场景中，理解“货币”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "huòbì" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “tiền tệ” rất quan trọng trong chủ đề Tài chính quốc tế.', 'Tài chính quốc tế', 5, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0433', 'collateral', '担保物', 'dānbǎowù', '/kəˈlætərəl/', 'tài sản thế chấp', 'noun', 'The team reviewed the details about ''collateral'' before the meeting.', '团队在会议前仔细核对了关于“担保物”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "dānbǎowù" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “tài sản thế chấp” trước cuộc họp.', 'Ngân hàng', 5, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0434', 'remittance', '汇款', 'huìkuǎn', '/rɪˈmɪtəns/', 'chuyển tiền', 'noun', 'We discussed ''remittance'' during today''s lesson on finance and banking.', '我们在今天的课程中重点讨论了“汇款”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "huìkuǎn".', 'Chúng tôi đã thảo luận trọng tâm về “chuyển tiền” trong buổi học hôm nay.', 'Ngân hàng', 5, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0435', 'invest', '投资', 'tóuzī', '/ɪnˈvest/', 'đầu tư', 'verb', 'Learners should practice how to invest clearly in real situations.', '学习者应在实际情境中反复练习如何“投资”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "tóuzī".', 'Người học nên luyện tập cách đầu tư rõ ràng trong tình huống thực tế.', 'Đầu tư tài chính', 5, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0436', 'allocate', '分配资金', 'fēnpèi zījīn', '/ˈæləkeɪt/', 'phân bổ ngân sách', 'verb', 'Please make sure to allocate carefully before moving to the next step.', '在进入下一步之前，请务必认真“分配资金”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "fēnpèi zījīn".', 'Hãy nhớ phân bổ ngân sách cẩn thận trước khi chuyển sang bước tiếp theo.', 'Quản trị tài chính', 5, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0437', 'reimburse', '报销', 'bàoxiāo', '/ˌriːɪmˈbɜːrs/', 'hoàn ứng chi phí', 'verb', 'Our supervisor asked us to reimburse without unnecessary delay.', '主管要求我们不要拖延，尽快“报销”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "bàoxiāo".', 'Quản lý đề nghị chúng tôi hoàn ứng chi phí kịp thời, không trì hoãn.', 'Quản trị tài chính', 5, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0438', 'candidate', '候选人', 'hòuxuǎnrén', '/ˈkændɪdət/', 'ứng viên', 'noun', 'We discussed ''candidate'' during today''s lesson on workplace management.', '我们在今天的课程中重点讨论了“候选人”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "hòuxuǎnrén".', 'Chúng tôi đã thảo luận trọng tâm về “ứng viên” trong buổi học hôm nay.', 'Nhân sự', 7, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0439', 'resume', '简历', 'jiǎnlì', '/ˈrezəmeɪ/', 'sơ yếu lý lịch', 'noun', 'Clear notes on ''resume'' help learners recall the concept faster.', '关于“简历”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "jiǎnlì" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “sơ yếu lý lịch” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Nhân sự', 7, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0440', 'probation', '试用期', 'shìyòngqī', '/proʊˈbeɪʃən/', 'thời gian thử việc', 'noun', 'Understanding the role of ''probation'' is essential in workplace management.', '在相关场景中，理解“试用期”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "shìyòngqī" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “thời gian thử việc” rất quan trọng trong chủ đề Nhân sự.', 'Nhân sự', 7, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
