INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0456', 'engagement', '互动度', 'hùdòngdù', '/ɪnˈɡeɪdʒmənt/', 'mức độ tương tác', 'noun', 'Understanding the role of ''engagement'' is essential in marketing and media.', '在相关场景中，理解“互动度”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "hùdòngdù" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “mức độ tương tác” rất quan trọng trong chủ đề Tiếp thị số.', 'Tiếp thị số', 8, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0457', 'sponsorship', '赞助', 'zànzhù', '/ˈspɑːnsərʃɪp/', 'tài trợ', 'noun', 'The team reviewed the details about ''sponsorship'' before the meeting.', '团队在会议前仔细核对了关于“赞助”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "zànzhù" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “tài trợ” trước cuộc họp.', 'Truyền thông', 8, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0458', 'endorsement', '代言', 'dàiyán', '/ɪnˈdɔːrsmənt/', 'sự chứng thực, đại diện', 'noun', 'We discussed ''endorsement'' during today''s lesson on marketing and media.', '我们在今天的课程中重点讨论了“代言”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "dàiyán".', 'Chúng tôi đã thảo luận trọng tâm về “sự chứng thực, đại diện” trong buổi học hôm nay.', 'Thương hiệu', 8, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0459', 'promote', '推广', 'tuīguǎng', '/prəˈmoʊt/', 'quảng bá', 'verb', 'Learners should practice how to promote clearly in real situations.', '学习者应在实际情境中反复练习如何“推广”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "tuīguǎng".', 'Người học nên luyện tập cách quảng bá rõ ràng trong tình huống thực tế.', 'Tiếp thị', 8, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0460', 'launch', '发布', 'fābù', '/lɔːntʃ/', 'ra mắt sản phẩm', 'verb', 'Please make sure to launch carefully before moving to the next step.', '在进入下一步之前，请务必认真“发布”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "fābù".', 'Hãy nhớ ra mắt sản phẩm cẩn thận trước khi chuyển sang bước tiếp theo.', 'Tiếp thị', 8, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0461', 'persuade', '说服', 'shuōfú', '/pərˈsweɪd/', 'thuyết phục', 'verb', 'Our supervisor asked us to persuade without unnecessary delay.', '主管要求我们不要拖延，尽快“说服”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "shuōfú".', 'Quản lý đề nghị chúng tôi thuyết phục kịp thời, không trì hoãn.', 'Truyền thông', 8, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0462', 'viral', '病毒式传播的', 'bìngdúshì chuánbō de', '/ˈvaɪrəl/', 'lan truyền nhanh', 'adjective', 'The report highlighted a viral factor that shaped the final decision.', '报告重点指出了一项“病毒式传播的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "bìngdúshì chuánbō de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố lan truyền nhanh đã tác động tới quyết định cuối cùng.', 'Tiếp thị số', 8, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0463', 'shipment', '货运批次', 'huòyùn pīcì', '/ˈʃɪpmənt/', 'lô hàng vận chuyển', 'noun', 'Clear notes on ''shipment'' help learners recall the concept faster.', '关于“货运批次”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "huòyùn pīcì" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “lô hàng vận chuyển” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Vận tải hàng hóa', 32, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0464', 'freight', '货运', 'huòyùn', '/freɪt/', 'hàng hóa vận chuyển', 'noun', 'Understanding the role of ''freight'' is essential in logistics.', '在相关场景中，理解“货运”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "huòyùn" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “hàng hóa vận chuyển” rất quan trọng trong chủ đề Vận tải hàng hóa.', 'Vận tải hàng hóa', 32, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0465', 'container', '集装箱', 'jízhuāngxiāng', '/kənˈteɪnər/', 'thùng container', 'noun', 'The team reviewed the details about ''container'' before the meeting.', '团队在会议前仔细核对了关于“集装箱”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "jízhuāngxiāng" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “thùng container” trước cuộc họp.', 'Vận tải hàng hóa', 32, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0466', 'distributor', '分销商', 'fēnxiāoshāng', '/dɪˈstrɪbjətər/', 'nhà phân phối', 'noun', 'We discussed ''distributor'' during today''s lesson on logistics.', '我们在今天的课程中重点讨论了“分销商”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "fēnxiāoshāng".', 'Chúng tôi đã thảo luận trọng tâm về “nhà phân phối” trong buổi học hôm nay.', 'Chuỗi cung ứng', 32, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0467', 'replenish', '补货', 'bǔhuò', '/rɪˈplenɪʃ/', 'bổ sung hàng tồn', 'verb', 'Our supervisor asked us to replenish without unnecessary delay.', '主管要求我们不要拖延，尽快“补货”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "bǔhuò".', 'Quản lý đề nghị chúng tôi bổ sung hàng tồn kịp thời, không trì hoãn.', 'Kho vận', 32, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0468', 'quota', '配额', 'pèi''é', '/ˈkwoʊtə/', 'hạn ngạch', 'noun', 'Understanding the role of ''quota'' is essential in international trade.', '在相关场景中，理解“配额”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "pèi''é" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “hạn ngạch” rất quan trọng trong chủ đề Xuất nhập khẩu.', 'Xuất nhập khẩu', 33, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
