INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0471', 'export', '出口', 'chūkǒu', '/ˈekspɔːrt/', 'xuất khẩu', 'noun', 'Clear notes on ''export'' help learners recall the concept faster.', '关于“出口”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "chūkǒu" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “xuất khẩu” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Xuất nhập khẩu', 33, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
