INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0473', 'embargo', '禁运', 'jìnyùn', '/ɪmˈbɑːrɡoʊ/', 'lệnh cấm vận', 'noun', 'The team reviewed the details about ''embargo'' before the meeting.', '团队在会议前仔细核对了关于“禁运”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "jìnyùn" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “lệnh cấm vận” trước cuộc họp.', 'Thương mại quốc tế', 33, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
