INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0475', 'claim', '理赔申请', 'lǐpéi shēnqǐng', '/kleɪm/', 'yêu cầu bồi thường', 'noun', 'Clear notes on ''claim'' help learners recall the concept faster.', '关于“理赔申请”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "lǐpéi shēnqǐng" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “yêu cầu bồi thường” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Bảo hiểm', 35, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0476', 'coverage', '承保范围', 'chéngbǎo fànwéi', '/ˈkʌvərɪdʒ/', 'phạm vi bảo hiểm', 'noun', 'Understanding the role of ''coverage'' is essential in risk management.', '在相关场景中，理解“承保范围”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "chéngbǎo fànwéi" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “phạm vi bảo hiểm” rất quan trọng trong chủ đề Bảo hiểm.', 'Bảo hiểm', 35, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0477', 'mitigate', '降低风险', 'jiàngdī fēngxiǎn', '/ˈmɪtɪɡeɪt/', 'giảm thiểu rủi ro', 'verb', 'Learners should practice how to mitigate clearly in real situations.', '学习者应在实际情境中反复练习如何“降低风险”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "jiàngdī fēngxiǎn".', 'Người học nên luyện tập cách giảm thiểu rủi ro rõ ràng trong tình huống thực tế.', 'Quản trị rủi ro', 35, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0478', 'contingency', '应急预案', 'yìngjí yù''àn', '/kənˈtɪndʒənsi/', 'phương án dự phòng', 'noun', 'We discussed ''contingency'' during today''s lesson on risk management.', '我们在今天的课程中重点讨论了“应急预案”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "yìngjí yù''àn".', 'Chúng tôi đã thảo luận trọng tâm về “phương án dự phòng” trong buổi học hôm nay.', 'Quản trị rủi ro', 35, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0479', 'proposal', '方案建议', 'fāng''àn jiànyì', '/prəˈpoʊzəl/', 'đề xuất dự án', 'noun', 'Clear notes on ''proposal'' help learners recall the concept faster.', '关于“方案建议”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "fāng''àn jiànyì" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “đề xuất dự án” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Giao dịch kinh doanh', 3, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0480', 'budget', '预算', 'yùsuàn', '/ˈbʌdʒɪt/', 'ngân sách', 'noun', 'Understanding the role of ''budget'' is essential in finance and banking.', '在相关场景中，理解“预算”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "yùsuàn" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “ngân sách” rất quan trọng trong chủ đề Quản trị tài chính.', 'Quản trị tài chính', 5, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0481', 'revenue', '营业收入', 'yíngyè shōurù', '/ˈrevənuː/', 'doanh thu', 'noun', 'The team reviewed the details about ''revenue'' before the meeting.', '团队在会议前仔细核对了关于“营业收入”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "yíngyè shōurù" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “doanh thu” trước cuộc họp.', 'Báo cáo tài chính', 4, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0482', 'forecast', '预测', 'yùcè', '/ˈfɔːrkæst/', 'dự báo', 'noun', 'We discussed ''forecast'' during today''s lesson on business operations.', '我们在今天的课程中重点讨论了“预测”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "yùcè".', 'Chúng tôi đã thảo luận trọng tâm về “dự báo” trong buổi học hôm nay.', 'Chiến lược kinh doanh', 3, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0483', 'quarterly', '季度的', 'jìdù de', '/ˈkwɔːrtərli/', 'hàng quý', 'adjective', 'The report highlighted a quarterly factor that shaped the final decision.', '报告重点指出了一项“季度的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "jìdù de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố hàng quý đã tác động tới quyết định cuối cùng.', 'Báo cáo tài chính', 4, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0484', 'annual', '年度的', 'niándù de', '/ˈænjuəl/', 'hàng năm', 'adjective', 'It is important to stay annual when handling complex tasks.', '在处理复杂任务时，保持“年度的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "niándù de" fēicháng zhòngyào.', 'Giữ được tính chất hàng năm rất quan trọng khi xử lý công việc phức tạp.', 'Báo cáo tài chính', 4, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0485', 'fiscal', '财政的', 'cáizhèng de', '/ˈfɪskəl/', 'thuộc tài khóa', 'adjective', 'Many readers found the explanation fiscal and easy to follow.', '许多读者认为这段解释十分“财政的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "cáizhèng de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất thuộc tài khóa và dễ theo dõi.', 'Tài chính', 5, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0486', 'commercial', '商业的', 'shāngyè de', '/kəˈmɜːrʃəl/', 'thuộc thương mại', 'adjective', 'The report highlighted a commercial factor that shaped the final decision.', '报告重点指出了一项“商业的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "shāngyè de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố thuộc thương mại đã tác động tới quyết định cuối cùng.', 'Kinh doanh', 3, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0487', 'corporate', '企业的', 'qǐyè de', '/ˈkɔːrpərət/', 'thuộc doanh nghiệp', 'adjective', 'It is important to stay corporate when handling complex tasks.', '在处理复杂任务时，保持“企业的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "qǐyè de" fēicháng zhòngyào.', 'Giữ được tính chất thuộc doanh nghiệp rất quan trọng khi xử lý công việc phức tạp.', 'Cơ cấu doanh nghiệp', 3, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0488', 'executive', '高管', 'gāoguǎn', '/ɪɡˈzekjətɪv/', 'giám đốc điều hành', 'noun', 'Understanding the role of ''executive'' is essential in workplace management.', '在相关场景中，理解“高管”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "gāoguǎn" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “giám đốc điều hành” rất quan trọng trong chủ đề Quản trị.', 'Quản trị', 7, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0489', 'boardroom', '董事会会议室', 'dǒngshìhuì huìyìshì', '/ˈbɔːrdruːm/', 'phòng họp hội đồng', 'noun', 'The team reviewed the details about ''boardroom'' before the meeting.', '团队在会议前仔细核对了关于“董事会会议室”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "dǒngshìhuì huìyìshì" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “phòng họp hội đồng” trước cuộc họp.', 'Quản trị', 7, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0490', 'briefing', '简报会', 'jiǎnbàohuì', '/ˈbriːfɪŋ/', 'buổi họp giao ban', 'noun', 'We discussed ''briefing'' during today''s lesson on workplace management.', '我们在今天的课程中重点讨论了“简报会”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "jiǎnbàohuì".', 'Chúng tôi đã thảo luận trọng tâm về “buổi họp giao ban” trong buổi học hôm nay.', 'Quản trị', 7, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0491', 'presentation', '演示汇报', 'yǎnshì huìbào', '/ˌprezənˈteɪʃən/', 'bài thuyết trình', 'noun', 'Clear notes on ''presentation'' help learners recall the concept faster.', '关于“演示汇报”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "yǎnshì huìbào" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “bài thuyết trình” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Giao tiếp công sở', 7, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0492', 'handout', '分发材料', 'fēnfā cáiliào', '/ˈhændaʊt/', 'tài liệu phát tay', 'noun', 'Understanding the role of ''handout'' is essential in workplace management.', '在相关场景中，理解“分发材料”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "fēnfā cáiliào" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “tài liệu phát tay” rất quan trọng trong chủ đề Giao tiếp công sở.', 'Giao tiếp công sở', 7, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0493', 'follow-up', '跟进事项', 'gēnjìn shìxiàng', '/ˈfɑːloʊʌp/', 'bước theo dõi tiếp theo', 'noun', 'The team reviewed the details about ''follow-up'' before the meeting.', '团队在会议前仔细核对了关于“跟进事项”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "gēnjìn shìxiàng" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “bước theo dõi tiếp theo” trước cuộc họp.', 'Giao tiếp công sở', 7, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0494', 'deliverable', '交付成果', 'jiāofù chéngguǒ', '/dɪˈlɪvərəbəl/', 'sản phẩm bàn giao', 'noun', 'We discussed ''deliverable'' during today''s lesson on workplace management.', '我们在今天的课程中重点讨论了“交付成果”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "jiāofù chéngguǒ".', 'Chúng tôi đã thảo luận trọng tâm về “sản phẩm bàn giao” trong buổi học hôm nay.', 'Quản lý dự án', 7, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0495', 'bottleneck', '瓶颈', 'píngjǐng', '/ˈbɑːtəlnek/', 'điểm nghẽn', 'noun', 'Clear notes on ''bottleneck'' help learners recall the concept faster.', '关于“瓶颈”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "píngjǐng" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “điểm nghẽn” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Quản lý dự án', 7, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0496', 'priority', '优先事项', 'yōuxiān shìxiàng', '/praɪˈɔːrəti/', 'ưu tiên hàng đầu', 'noun', 'Understanding the role of ''priority'' is essential in workplace management.', '在相关场景中，理解“优先事项”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "yōuxiān shìxiàng" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “ưu tiên hàng đầu” rất quan trọng trong chủ đề Quản lý dự án.', 'Quản lý dự án', 7, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0497', 'efficiency', '效率', 'xiàolǜ', '/ɪˈfɪʃənsi/', 'hiệu suất', 'noun', 'The team reviewed the details about ''efficiency'' before the meeting.', '团队在会议前仔细核对了关于“效率”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "xiàolǜ" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “hiệu suất” trước cuộc họp.', 'Vận hành doanh nghiệp', 7, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0498', 'benchmarking', '对标分析', 'duìbiāo fēnxī', '/ˈbentʃmɑːrkɪŋ/', 'đánh giá đối chuẩn', 'noun', 'We discussed ''benchmarking'' during today''s lesson on business operations.', '我们在今天的课程中重点讨论了“对标分析”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "duìbiāo fēnxī".', 'Chúng tôi đã thảo luận trọng tâm về “đánh giá đối chuẩn” trong buổi học hôm nay.', 'Chiến lược kinh doanh', 3, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0499', 'streamline', '精简流程', 'jīngjiǎn liúchéng', '/ˈstriːmlaɪn/', 'tinh gọn quy trình', 'verb', 'Please make sure to streamline carefully before moving to the next step.', '在进入下一步之前，请务必认真“精简流程”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "jīngjiǎn liúchéng".', 'Hãy nhớ tinh gọn quy trình cẩn thận trước khi chuyển sang bước tiếp theo.', 'Vận hành doanh nghiệp', 7, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0500', 'implement', '实施', 'shíshī', '/ˈɪmplɪment/', 'triển khai thực hiện', 'verb', 'Our supervisor asked us to implement without unnecessary delay.', '主管要求我们不要拖延，尽快“实施”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "shíshī".', 'Quản lý đề nghị chúng tôi triển khai thực hiện kịp thời, không trì hoãn.', 'Quản lý dự án', 7, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0501', 'approve', '批准', 'pīzhǔn', '/əˈpruːv/', 'phê duyệt', 'verb', 'Learners should practice how to approve clearly in real situations.', '学习者应在实际情境中反复练习如何“批准”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "pīzhǔn".', 'Người học nên luyện tập cách phê duyệt rõ ràng trong tình huống thực tế.', 'Quản trị', 7, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0502', 'authorize', '授权', 'shòuquán', '/ˈɔːθəraɪz/', 'ủy quyền', 'verb', 'Please make sure to authorize carefully before moving to the next step.', '在进入下一步之前，请务必认真“授权”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "shòuquán".', 'Hãy nhớ ủy quyền cẩn thận trước khi chuyển sang bước tiếp theo.', 'Quản trị', 7, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0503', 'notify', '通知', 'tōngzhī', '/ˈnoʊtɪfaɪ/', 'thông báo chính thức', 'verb', 'Our supervisor asked us to notify without unnecessary delay.', '主管要求我们不要拖延，尽快“通知”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "tōngzhī".', 'Quản lý đề nghị chúng tôi thông báo chính thức kịp thời, không trì hoãn.', 'Giao tiếp công sở', 7, 'B2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0504', 'escalate', '升级处理', 'shēngjí chǔlǐ', '/ˈeskəleɪt/', 'chuyển lên cấp cao hơn', 'verb', 'Learners should practice how to escalate clearly in real situations.', '学习者应在实际情境中反复练习如何“升级处理”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "shēngjí chǔlǐ".', 'Người học nên luyện tập cách chuyển lên cấp cao hơn rõ ràng trong tình huống thực tế.', 'Quản lý dự án', 7, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0505', 'finalize', '最终敲定', 'zuìzhōng qiāodìng', '/ˈfaɪnəlaɪz/', 'hoàn tất chốt phương án', 'verb', 'Please make sure to finalize carefully before moving to the next step.', '在进入下一步之前，请务必认真“最终敲定”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "zuìzhōng qiāodìng".', 'Hãy nhớ hoàn tất chốt phương án cẩn thận trước khi chuyển sang bước tiếp theo.', 'Quản lý dự án', 7, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0506', 'prioritize', '排定优先级', 'páidìng yōuxiānjí', '/praɪˈɔːrətaɪz/', 'sắp xếp thứ tự ưu tiên', 'verb', 'Our supervisor asked us to prioritize without unnecessary delay.', '主管要求我们不要拖延，尽快“排定优先级”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "páidìng yōuxiānjí".', 'Quản lý đề nghị chúng tôi sắp xếp thứ tự ưu tiên kịp thời, không trì hoãn.', 'Quản lý dự án', 7, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0507', 'feasible', '可行的', 'kěxíng de', '/ˈfiːzəbəl/', 'khả thi', 'adjective', 'The report highlighted a feasible factor that shaped the final decision.', '报告重点指出了一项“可行的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "kěxíng de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố khả thi đã tác động tới quyết định cuối cùng.', 'Chiến lược kinh doanh', 3, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0508', 'cost-effective', '划算高效的', 'huásuàn gāoxiào de', '/ˌkɔːst ɪˈfektɪv/', 'hiệu quả về chi phí', 'adjective', 'It is important to stay cost-effective when handling complex tasks.', '在处理复杂任务时，保持“划算高效的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "huásuàn gāoxiào de" fēicháng zhòngyào.', 'Giữ được tính chất hiệu quả về chi phí rất quan trọng khi xử lý công việc phức tạp.', 'Chiến lược kinh doanh', 3, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0509', 'transparent', '透明的', 'tòumíng de', '/trænsˈpærənt/', 'minh bạch', 'adjective', 'Many readers found the explanation transparent and easy to follow.', '许多读者认为这段解释十分“透明的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "tòumíng de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất minh bạch và dễ theo dõi.', 'Quản trị', 7, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0510', 'accountable', '负有责任的', 'fùyǒu zérèn de', '/əˈkaʊntəbəl/', 'chịu trách nhiệm giải trình', 'adjective', 'The report highlighted a accountable factor that shaped the final decision.', '报告重点指出了一项“负有责任的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "fùyǒu zérèn de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố chịu trách nhiệm giải trình đã tác động tới quyết định cuối cùng.', 'Quản trị', 7, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0511', 'ahead of schedule', '提前完成', 'tíqián wánchéng', '/əˈhed əv ˈskedʒuːl/', 'vượt tiến độ', 'phrase', 'Try to ahead of schedule whenever you need a clear and practical phrasing.', '在需要清晰表达时，不妨尝试使用“提前完成”。', 'Zài xūyào qīngxī biǎodá shí, bùfáng chángshì shǐyòng "tíqián wánchéng".', 'Hãy thử vận dụng cách diễn đạt “vượt tiến độ” khi cần nói ngắn gọn, rõ ý.', 'Quản lý dự án', 7, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0512', 'behind schedule', '落后于进度', 'luòhòu yú jìndù', '/bɪˈhaɪnd ˈskedʒuːl/', 'chậm tiến độ', 'phrase', 'You can use the expression ''behind schedule'' naturally in everyday conversation.', '在日常交流中，你可以自然地使用“落后于进度”这一表达。', 'Zài rìcháng jiāoliú zhōng, nǐ kěyǐ zìrán de shǐyòng "luòhòu yú jìndù" zhè yī biǎodá.', 'Bạn có thể dùng cụm “behind schedule” (chậm tiến độ) một cách tự nhiên trong giao tiếp hàng ngày.', 'Quản lý dự án', 7, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0513', 'on behalf of', '代表', 'dàibiǎo', '/ɑːn bɪˈhæf əv/', 'thay mặt cho', 'phrase', 'Try to on behalf of whenever you need a clear and practical phrasing.', '在需要清晰表达时，不妨尝试使用“代表”。', 'Zài xūyào qīngxī biǎodá shí, bùfáng chángshì shǐyòng "dàibiǎo".', 'Hãy thử vận dụng cách diễn đạt “thay mặt cho” khi cần nói ngắn gọn, rõ ý.', 'Giao tiếp công sở', 7, 'B2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0514', 'in charge of', '负责', 'fùzé', '/ɪn tʃɑːrdʒ əv/', 'phụ trách', 'phrase', 'You can use the expression ''in charge of'' naturally in everyday conversation.', '在日常交流中，你可以自然地使用“负责”这一表达。', 'Zài rìcháng jiāoliú zhōng, nǐ kěyǐ zìrán de shǐyòng "fùzé" zhè yī biǎodá.', 'Bạn có thể dùng cụm “in charge of” (phụ trách) một cách tự nhiên trong giao tiếp hàng ngày.', 'Quản trị', 7, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0515', 'meet a deadline', '按时完工', 'ànshí wángōng', '/miːt ə ˈdedlaɪn/', 'kịp hạn chót', 'phrase', 'Try to meet a deadline whenever you need a clear and practical phrasing.', '在需要清晰表达时，不妨尝试使用“按时完工”。', 'Zài xūyào qīngxī biǎodá shí, bùfáng chángshì shǐyòng "ànshí wángōng".', 'Hãy thử vận dụng cách diễn đạt “kịp hạn chót” khi cần nói ngắn gọn, rõ ý.', 'Quản lý dự án', 7, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0516', 'reach an agreement', '达成协议', 'dáchéng xiéyì', '/riːtʃ ən əˈɡriːmənt/', 'đạt được thỏa thuận', 'phrase', 'You can use the expression ''reach an agreement'' naturally in everyday conversation.', '在日常交流中，你可以自然地使用“达成协议”这一表达。', 'Zài rìcháng jiāoliú zhōng, nǐ kěyǐ zìrán de shǐyòng "dáchéng xiéyì" zhè yī biǎodá.', 'Bạn có thể dùng cụm “reach an agreement” (đạt được thỏa thuận) một cách tự nhiên trong giao tiếp hàng ngày.', 'Giao dịch kinh doanh', 3, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0517', 'break even', '收支平衡', 'shōuzhī pínghéng', '/breɪk ˈiːvən/', 'hòa vốn', 'phrase', 'Try to break even whenever you need a clear and practical phrasing.', '在需要清晰表达时，不妨尝试使用“收支平衡”。', 'Zài xūyào qīngxī biǎodá shí, bùfáng chángshì shǐyòng "shōuzhī pínghéng".', 'Hãy thử vận dụng cách diễn đạt “hòa vốn” khi cần nói ngắn gọn, rõ ý.', 'Báo cáo tài chính', 4, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0518', 'bottom line', '底线净利润', 'dǐxiàn jìnglìrùn', '/ˈbɑːtəm laɪn/', 'mấu chốt, lợi nhuận ròng', 'phrase', 'You can use the expression ''bottom line'' naturally in everyday conversation.', '在日常交流中，你可以自然地使用“底线净利润”这一表达。', 'Zài rìcháng jiāoliú zhōng, nǐ kěyǐ zìrán de shǐyòng "dǐxiàn jìnglìrùn" zhè yī biǎodá.', 'Bạn có thể dùng cụm “bottom line” (mấu chốt, lợi nhuận ròng) một cách tự nhiên trong giao tiếp hàng ngày.', 'Báo cáo tài chính', 4, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0519', 'server', '服务器', 'fúwùqì', '/ˈsɜːrvər/', 'máy chủ', 'noun', 'Clear notes on ''server'' help learners recall the concept faster.', '关于“服务器”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "fúwùqì" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “máy chủ” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Hạ tầng CNTT', 9, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0520', 'database', '数据库', 'shùjùkù', '/ˈdeɪtəbeɪs/', 'cơ sở dữ liệu', 'noun', 'Understanding the role of ''database'' is essential in information technology.', '在相关场景中，理解“数据库”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "shùjùkù" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “cơ sở dữ liệu” rất quan trọng trong chủ đề Hạ tầng CNTT.', 'Hạ tầng CNTT', 9, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0521', 'bandwidth', '带宽', 'dàikuān', '/ˈbændwɪdθ/', 'băng thông', 'noun', 'The team reviewed the details about ''bandwidth'' before the meeting.', '团队在会议前仔细核对了关于“带宽”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "dàikuān" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “băng thông” trước cuộc họp.', 'Mạng máy tính', 9, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0522', 'latency', '延迟', 'yánchí', '/ˈleɪtənsi/', 'độ trễ mạng', 'noun', 'We discussed ''latency'' during today''s lesson on information technology.', '我们在今天的课程中重点讨论了“延迟”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "yánchí".', 'Chúng tôi đã thảo luận trọng tâm về “độ trễ mạng” trong buổi học hôm nay.', 'Mạng máy tính', 9, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0523', 'router', '路由器', 'lùyóuqì', '/ˈraʊtər/', 'bộ định tuyến', 'noun', 'Clear notes on ''router'' help learners recall the concept faster.', '关于“路由器”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "lùyóuqì" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “bộ định tuyến” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Mạng máy tính', 9, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0524', 'cloud storage', '云存储', 'yúncúnchǔ', '/klaʊd ˈstɔːrɪdʒ/', 'lưu trữ đám mây', 'noun', 'Understanding the role of ''cloud storage'' is essential in information technology.', '在相关场景中，理解“云存储”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "yúncúnchǔ" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “lưu trữ đám mây” rất quan trọng trong chủ đề Điện toán đám mây.', 'Điện toán đám mây', 9, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0525', 'downtime', '停机时间', 'tíngjī shíjiān', '/ˈdaʊntaɪm/', 'thời gian gián đoạn hệ thống', 'noun', 'The team reviewed the details about ''downtime'' before the meeting.', '团队在会议前仔细核对了关于“停机时间”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "tíngjī shíjiān" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “thời gian gián đoạn hệ thống” trước cuộc họp.', 'Vận hành hệ thống', 9, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0526', 'interface', '界面', 'jièmiàn', '/ˈɪntərfeɪs/', 'giao diện', 'noun', 'We discussed ''interface'' during today''s lesson on information technology.', '我们在今天的课程中重点讨论了“界面”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "jièmiàn".', 'Chúng tôi đã thảo luận trọng tâm về “giao diện” trong buổi học hôm nay.', 'Phần mềm', 9, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0527', 'protocol', '通信协议', 'tōngxìn xiéyì', '/ˈproʊtəkɑːl/', 'giao thức mạng', 'noun', 'Clear notes on ''protocol'' help learners recall the concept faster.', '关于“通信协议”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "tōngxìn xiéyì" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “giao thức mạng” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Mạng máy tính', 9, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0528', 'browser', '浏览器', 'liúlǎnqì', '/ˈbraʊzər/', 'trình duyệt web', 'noun', 'Understanding the role of ''browser'' is essential in information technology.', '在相关场景中，理解“浏览器”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "liúlǎnqì" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “trình duyệt web” rất quan trọng trong chủ đề Ứng dụng CNTT.', 'Ứng dụng CNTT', 9, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0529', 'hardware', '硬件', 'yìngjiàn', '/ˈhɑːrdwer/', 'phần cứng', 'noun', 'The team reviewed the details about ''hardware'' before the meeting.', '团队在会议前仔细核对了关于“硬件”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "yìngjiàn" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “phần cứng” trước cuộc họp.', 'Hạ tầng CNTT', 9, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
