INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0531', 'update', '系统更新', 'xìtǒng gēngxīn', '/ˈʌpdeɪt/', 'bản cập nhật', 'noun', 'Clear notes on ''update'' help learners recall the concept faster.', '关于“系统更新”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "xìtǒng gēngxīn" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “bản cập nhật” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Phần mềm', 9, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0532', 'configure', '配置', 'pèizhì', '/kənˈfɪɡjər/', 'cấu hình', 'verb', 'Please make sure to configure carefully before moving to the next step.', '在进入下一步之前，请务必认真“配置”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "pèizhì".', 'Hãy nhớ cấu hình cẩn thận trước khi chuyển sang bước tiếp theo.', 'Vận hành hệ thống', 9, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0533', 'troubleshoot', '排查故障', 'páichá gùzhàng', '/ˈtrʌbəlʃuːt/', 'khắc phục sự cố', 'verb', 'Our supervisor asked us to troubleshoot without unnecessary delay.', '主管要求我们不要拖延，尽快“排查故障”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "páichá gùzhàng".', 'Quản lý đề nghị chúng tôi khắc phục sự cố kịp thời, không trì hoãn.', 'Vận hành hệ thống', 9, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0534', 'synchronize', '同步', 'tóngbù', '/ˈsɪŋkrənaɪz/', 'đồng bộ hóa', 'verb', 'Learners should practice how to synchronize clearly in real situations.', '学习者应在实际情境中反复练习如何“同步”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "tóngbù".', 'Người học nên luyện tập cách đồng bộ hóa rõ ràng trong tình huống thực tế.', 'Hạ tầng CNTT', 9, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0535', 'migrate', '迁移数据', 'qiānyí shùjù', '/ˈmaɪɡreɪt/', 'di chuyển hệ thống', 'verb', 'Please make sure to migrate carefully before moving to the next step.', '在进入下一步之前，请务必认真“迁移数据”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "qiānyí shùjù".', 'Hãy nhớ di chuyển hệ thống cẩn thận trước khi chuyển sang bước tiếp theo.', 'Hạ tầng CNTT', 9, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0536', 'algorithm', '算法', 'suànfǎ', '/ˈælɡərɪðəm/', 'thuật toán', 'noun', 'Understanding the role of ''algorithm'' is essential in data science and AI.', '在相关场景中，理解“算法”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "suànfǎ" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “thuật toán” rất quan trọng trong chủ đề Khoa học dữ liệu.', 'Khoa học dữ liệu', 10, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0537', 'neural network', '神经网络', 'shénjīng wǎngluò', '/ˈnʊrəl ˈnetwɜːrk/', 'mạng nơ-ron nhân tạo', 'noun', 'The team reviewed the details about ''neural network'' before the meeting.', '团队在会议前仔细核对了关于“神经网络”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "shénjīng wǎngluò" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “mạng nơ-ron nhân tạo” trước cuộc họp.', 'Trí tuệ nhân tạo', 10, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
