INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0542', 'anomaly', '异常值', 'yìchángzhí', '/əˈnɑːməli/', 'điểm bất thường', 'noun', 'We discussed ''anomaly'' during today''s lesson on data science and AI.', '我们在今天的课程中重点讨论了“异常值”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "yìchángzhí".', 'Chúng tôi đã thảo luận trọng tâm về “điểm bất thường” trong buổi học hôm nay.', 'Khoa học dữ liệu', 10, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
