INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0545', 'preprocess', '预处理', 'yùchǔlǐ', '/ˌpriːˈprɑːses/', 'tiền xử lý dữ liệu', 'verb', 'Our supervisor asked us to preprocess without unnecessary delay.', '主管要求我们不要拖延，尽快“预处理”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "yùchǔlǐ".', 'Quản lý đề nghị chúng tôi tiền xử lý dữ liệu kịp thời, không trì hoãn.', 'Khoa học dữ liệu', 10, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0546', 'firewall', '防火墙', 'fánghuǒqiáng', '/ˈfaɪərwɔːl/', 'tường lửa', 'noun', 'We discussed ''firewall'' during today''s lesson on cybersecurity.', '我们在今天的课程中重点讨论了“防火墙”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "fánghuǒqiáng".', 'Chúng tôi đã thảo luận trọng tâm về “tường lửa” trong buổi học hôm nay.', 'Bảo mật mạng', 11, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0547', 'encryption', '加密', 'jiāmì', '/ɪnˈkrɪpʃən/', 'mã hóa dữ liệu', 'noun', 'Clear notes on ''encryption'' help learners recall the concept faster.', '关于“加密”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "jiāmì" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “mã hóa dữ liệu” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Bảo mật mạng', 11, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0548', 'authentication', '身份验证', 'shēnfèn yànzhèng', '/ɔːˌθentɪˈkeɪʃən/', 'xác thực danh tính', 'noun', 'Understanding the role of ''authentication'' is essential in cybersecurity.', '在相关场景中，理解“身份验证”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "shēnfèn yànzhèng" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “xác thực danh tính” rất quan trọng trong chủ đề Bảo mật mạng.', 'Bảo mật mạng', 11, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0549', 'vulnerability', '安全漏洞', 'ānquán lòudòng', '/ˌvʌlnərəˈbɪləti/', 'lỗ hổng bảo mật', 'noun', 'The team reviewed the details about ''vulnerability'' before the meeting.', '团队在会议前仔细核对了关于“安全漏洞”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "ānquán lòudòng" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “lỗ hổng bảo mật” trước cuộc họp.', 'An toàn thông tin', 11, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0550', 'breach', '数据泄露', 'shùjù xièlòu', '/briːtʃ/', 'sự cố rò rỉ dữ liệu', 'noun', 'We discussed ''breach'' during today''s lesson on cybersecurity.', '我们在今天的课程中重点讨论了“数据泄露”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "shùjù xièlòu".', 'Chúng tôi đã thảo luận trọng tâm về “sự cố rò rỉ dữ liệu” trong buổi học hôm nay.', 'An toàn thông tin', 11, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0551', 'credential', '登录凭证', 'dēnglù píngzhèng', '/krəˈdenʃəl/', 'thông tin xác thực', 'noun', 'Clear notes on ''credential'' help learners recall the concept faster.', '关于“登录凭证”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "dēnglù píngzhèng" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “thông tin xác thực” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Bảo mật mạng', 11, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0552', 'decrypt', '解密', 'jiěmì', '/diːˈkrɪpt/', 'giải mã', 'verb', 'Learners should practice how to decrypt clearly in real situations.', '学习者应在实际情境中反复练习如何“解密”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "jiěmì".', 'Người học nên luyện tập cách giải mã rõ ràng trong tình huống thực tế.', 'Bảo mật mạng', 11, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0553', 'patch', '打补丁', 'dǎ bǔdīng', '/pætʃ/', 'vá lỗi bảo mật', 'verb', 'Please make sure to patch carefully before moving to the next step.', '在进入下一步之前，请务必认真“打补丁”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "dǎ bǔdīng".', 'Hãy nhớ vá lỗi bảo mật cẩn thận trước khi chuyển sang bước tiếp theo.', 'An toàn thông tin', 11, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0554', 'repository', '代码仓库', 'dàimǎ cāngkù', '/rɪˈpɑːzətɔːri/', 'kho lưu trữ mã nguồn', 'noun', 'We discussed ''repository'' during today''s lesson on software engineering.', '我们在今天的课程中重点讨论了“代码仓库”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "dàimǎ cāngkù".', 'Chúng tôi đã thảo luận trọng tâm về “kho lưu trữ mã nguồn” trong buổi học hôm nay.', 'Phát triển phần mềm', 12, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0555', 'deployment', '上线部署', 'shàngxiàn bùshǔ', '/dɪˈplɔɪmənt/', 'triển khai phát hành', 'noun', 'Clear notes on ''deployment'' help learners recall the concept faster.', '关于“上线部署”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "shàngxiàn bùshǔ" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “triển khai phát hành” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Phát triển phần mềm', 12, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0556', 'debugger', '调试工具', 'tiáoshì gōngjù', '/diːˈbʌɡər/', 'trình gỡ lỗi', 'noun', 'Understanding the role of ''debugger'' is essential in software engineering.', '在相关场景中，理解“调试工具”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "tiáoshì gōngjù" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “trình gỡ lỗi” rất quan trọng trong chủ đề Phát triển phần mềm.', 'Phát triển phần mềm', 12, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0557', 'compiler', '编译器', 'biānyìqì', '/kəmˈpaɪlər/', 'trình biên dịch', 'noun', 'The team reviewed the details about ''compiler'' before the meeting.', '团队在会议前仔细核对了关于“编译器”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "biānyìqì" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “trình biên dịch” trước cuộc họp.', 'Phát triển phần mềm', 12, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0558', 'architecture', '系统架构', 'xìtǒng jiàgòu', '/ˈɑːrkɪtektʃər/', 'kiến trúc phần mềm', 'noun', 'We discussed ''architecture'' during today''s lesson on software engineering.', '我们在今天的课程中重点讨论了“系统架构”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "xìtǒng jiàgòu".', 'Chúng tôi đã thảo luận trọng tâm về “kiến trúc phần mềm” trong buổi học hôm nay.', 'Thiết kế hệ thống', 12, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0559', 'endpoint', '接口端点', 'jiēkǒu duāndiǎn', '/ˈendpɔɪnt/', 'điểm cuối API', 'noun', 'Clear notes on ''endpoint'' help learners recall the concept faster.', '关于“接口端点”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "jiēkǒu duāndiǎn" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “điểm cuối API” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Phát triển phần mềm', 12, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0560', 'module', '功能模块', 'gōngnéng mókuài', '/ˈmɑːdʒuːl/', 'mô-đun chức năng', 'noun', 'Understanding the role of ''module'' is essential in software engineering.', '在相关场景中，理解“功能模块”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "gōngnéng mókuài" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “mô-đun chức năng” rất quan trọng trong chủ đề Thiết kế hệ thống.', 'Thiết kế hệ thống', 12, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0561', 'versioning', '版本控制', 'bǎnběn kòngzhì', '/ˈvɜːrʒənɪŋ/', 'quản lý phiên bản', 'noun', 'The team reviewed the details about ''versioning'' before the meeting.', '团队在会议前仔细核对了关于“版本控制”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "bǎnběn kòngzhì" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “quản lý phiên bản” trước cuộc họp.', 'Phát triển phần mềm', 12, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0562', 'refactor', '重构代码', 'chónggòu dàimǎ', '/ˌriːˈfæktər/', 'tái cấu trúc mã nguồn', 'verb', 'Please make sure to refactor carefully before moving to the next step.', '在进入下一步之前，请务必认真“重构代码”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "chónggòu dàimǎ".', 'Hãy nhớ tái cấu trúc mã nguồn cẩn thận trước khi chuyển sang bước tiếp theo.', 'Phát triển phần mềm', 12, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0563', 'deploy', '部署上线', 'bùshǔ shàngxiàn', '/dɪˈplɔɪ/', 'triển khai lên máy chủ', 'verb', 'Our supervisor asked us to deploy without unnecessary delay.', '主管要求我们不要拖延，尽快“部署上线”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "bùshǔ shàngxiàn".', 'Quản lý đề nghị chúng tôi triển khai lên máy chủ kịp thời, không trì hoãn.', 'Phát triển phần mềm', 12, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0564', 'compile', '编译', 'biānyì', '/kəmˈpaɪl/', 'biên dịch mã', 'verb', 'Learners should practice how to compile clearly in real situations.', '学习者应在实际情境中反复练习如何“编译”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "biānyì".', 'Người học nên luyện tập cách biên dịch mã rõ ràng trong tình huống thực tế.', 'Phát triển phần mềm', 12, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0565', 'scalable', '可扩展的', 'kě kuòzhǎn de', '/ˈskeɪləbəl/', 'có khả năng mở rộng', 'adjective', 'It is important to stay scalable when handling complex tasks.', '在处理复杂任务时，保持“可扩展的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "kě kuòzhǎn de" fēicháng zhòngyào.', 'Giữ được tính chất có khả năng mở rộng rất quan trọng khi xử lý công việc phức tạp.', 'Thiết kế hệ thống', 12, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0566', 'solder', '焊接', 'hànjiē', '/ˈsɑːdər/', 'hàn mạch điện', 'verb', 'Our supervisor asked us to solder without unnecessary delay.', '主管要求我们不要拖延，尽快“焊接”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "hànjiē".', 'Quản lý đề nghị chúng tôi hàn mạch điện kịp thời, không trì hoãn.', 'Điện tử', 13, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0567', 'piston', '活塞', 'huósāi', '/ˈpɪstən/', 'pít-tông', 'noun', 'Clear notes on ''piston'' help learners recall the concept faster.', '关于“活塞”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "huósāi" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “pít-tông” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Động cơ', 14, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0568', 'turbine', '涡轮机', 'wōlúnjī', '/ˈtɜːrbaɪn/', 'tua-bin', 'noun', 'Understanding the role of ''turbine'' is essential in mechanical engineering.', '在相关场景中，理解“涡轮机”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "wōlúnjī" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “tua-bin” rất quan trọng trong chủ đề Chế tạo máy.', 'Chế tạo máy', 14, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0569', 'alloy', '合金', 'héjīn', '/ˈælɔɪ/', 'hợp kim', 'noun', 'The team reviewed the details about ''alloy'' before the meeting.', '团队在会议前仔细核对了关于“合金”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "héjīn" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “hợp kim” trước cuộc họp.', 'Vật liệu cơ khí', 14, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0570', 'prototype', '原型样机', 'yuánxíng yàngjī', '/ˈproʊtətaɪp/', 'nguyên mẫu thử nghiệm', 'noun', 'We discussed ''prototype'' during today''s lesson on mechanical engineering.', '我们在今天的课程中重点讨论了“原型样机”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "yuánxíng yàngjī".', 'Chúng tôi đã thảo luận trọng tâm về “nguyên mẫu thử nghiệm” trong buổi học hôm nay.', 'Chế tạo máy', 14, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0571', 'calibrate', '校准', 'jiàozhǔn', '/ˈkælɪbreɪt/', 'hiệu chuẩn thiết bị', 'verb', 'Please make sure to calibrate carefully before moving to the next step.', '在进入下一步之前，请务必认真“校准”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "jiàozhǔn".', 'Hãy nhớ hiệu chuẩn thiết bị cẩn thận trước khi chuyển sang bước tiếp theo.', 'Đo lường', 14, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0572', 'weld', '电焊', 'diànhàn', '/weld/', 'hàn kim loại', 'verb', 'Our supervisor asked us to weld without unnecessary delay.', '主管要求我们不要拖延，尽快“电焊”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "diànhàn".', 'Quản lý đề nghị chúng tôi hàn kim loại kịp thời, không trì hoãn.', 'Gia công cơ khí', 14, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0573', 'generator', '发电机', 'fādiànjī', '/ˈdʒenəreɪtər/', 'máy phát điện', 'noun', 'The team reviewed the details about ''generator'' before the meeting.', '团队在会议前仔细核对了关于“发电机”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "fādiànjī" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “máy phát điện” trước cuộc họp.', 'Hệ thống điện', 15, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0574', 'transformer', '变压器', 'biànyāqì', '/trænsˈfɔːrmər/', 'máy biến áp', 'noun', 'We discussed ''transformer'' during today''s lesson on electrical automation.', '我们在今天的课程中重点讨论了“变压器”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "biànyāqì".', 'Chúng tôi đã thảo luận trọng tâm về “máy biến áp” trong buổi học hôm nay.', 'Hệ thống điện', 15, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0575', 'insulator', '绝缘体', 'juéyuántǐ', '/ˈɪnsəleɪtər/', 'vật liệu cách điện', 'noun', 'Clear notes on ''insulator'' help learners recall the concept faster.', '关于“绝缘体”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "juéyuántǐ" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “vật liệu cách điện” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Hệ thống điện', 15, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0576', 'actuator', '执行器', 'zhíxíngqì', '/ˈæktʃueɪtər/', 'bộ truyền động', 'noun', 'Understanding the role of ''actuator'' is essential in electrical automation.', '在相关场景中，理解“执行器”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "zhíxíngqì" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “bộ truyền động” rất quan trọng trong chủ đề Tự động hóa.', 'Tự động hóa', 15, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0577', 'robotics', '机器人技术', 'jīqìrén jìshù', '/roʊˈbɑːtɪks/', 'kỹ thuật rô-bốt', 'noun', 'The team reviewed the details about ''robotics'' before the meeting.', '团队在会议前仔细核对了关于“机器人技术”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "jīqìrén jìshù" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “kỹ thuật rô-bốt” trước cuộc họp.', 'Tự động hóa', 15, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
