INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0580', 'facade', '建筑立面', 'jiànzhù lìmiàn', '/fəˈsɑːd/', 'mặt tiền công trình', 'noun', 'Understanding the role of ''facade'' is essential in architecture and construction.', '在相关场景中，理解“建筑立面”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "jiànzhù lìmiàn" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “mặt tiền công trình” rất quan trọng trong chủ đề Kiến trúc.', 'Kiến trúc', 16, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
