INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0594', 'pier', '码头', 'mǎtóu', '/pɪr/', 'cầu cảng', 'noun', 'We discussed ''pier'' during today''s lesson on aviation and maritime.', '我们在今天的课程中重点讨论了“码头”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "mǎtóu".', 'Chúng tôi đã thảo luận trọng tâm về “cầu cảng” trong buổi học hôm nay.', 'Hàng hải', 18, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0595', 'hydropower', '水力发电', 'shuǐlì fādiàn', '/ˈhaɪdroʊpaʊər/', 'thủy điện', 'noun', 'Clear notes on ''hydropower'' help learners recall the concept faster.', '关于“水力发电”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "shuǐlì fādiàn" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “thủy điện” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Năng lượng tái tạo', 36, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0596', 'geothermal', '地热能', 'dìrènéng', '/ˌdʒiːoʊˈθɜːrməl/', 'địa nhiệt', 'noun', 'Understanding the role of ''geothermal'' is essential in green energy.', '在相关场景中，理解“地热能”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "dìrènéng" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “địa nhiệt” rất quan trọng trong chủ đề Năng lượng tái tạo.', 'Năng lượng tái tạo', 36, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0597', 'biofuel', '生物燃料', 'shēngwù ránliào', '/ˈbaɪoʊfjuːəl/', 'nhiên liệu sinh học', 'noun', 'The team reviewed the details about ''biofuel'' before the meeting.', '团队在会议前仔细核对了关于“生物燃料”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "shēngwù ránliào" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “nhiên liệu sinh học” trước cuộc họp.', 'Năng lượng tái tạo', 36, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0598', 'emission', '碳排放', 'tàn páifàng', '/ɪˈmɪʃən/', 'khí thải', 'noun', 'We discussed ''emission'' during today''s lesson on green energy.', '我们在今天的课程中重点讨论了“碳排放”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "tàn páifàng".', 'Chúng tôi đã thảo luận trọng tâm về “khí thải” trong buổi học hôm nay.', 'Công nghệ xanh', 36, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0599', 'renewable', '可再生的', 'kě zàishēng de', '/rɪˈnuːəbəl/', 'tái tạo được', 'adjective', 'Many readers found the explanation renewable and easy to follow.', '许多读者认为这段解释十分“可再生的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "kě zàishēng de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất tái tạo được và dễ theo dõi.', 'Năng lượng tái tạo', 36, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0600', 'energy-efficient', '节能的', 'jiénéng de', '/ˈenərdʒi ɪˈfɪʃənt/', 'tiết kiệm năng lượng', 'adjective', 'The report highlighted a energy-efficient factor that shaped the final decision.', '报告重点指出了一项“节能的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "jiénéng de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố tiết kiệm năng lượng đã tác động tới quyết định cuối cùng.', 'Công nghệ xanh', 36, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
