INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0620', 'bandage', '绷带', 'bēngdài', '/ˈbændɪdʒ/', 'băng gạc', 'noun', 'Understanding the role of ''bandage'' is essential in healthcare.', '在相关场景中，理解“绷带”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "bēngdài" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “băng gạc” rất quan trọng trong chủ đề Sơ cứu.', 'Sơ cứu', 26, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0621', 'thermometer', '体温计', 'tǐwēnjì', '/θərˈmɑːmɪtər/', 'nhiệt kế', 'noun', 'The team reviewed the details about ''thermometer'' before the meeting.', '团队在会议前仔细核对了关于“体温计”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "tǐwēnjì" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “nhiệt kế” trước cuộc họp.', 'Thiết bị y tế', 26, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0622', 'stethoscope', '听诊器', 'tīngzhěnqì', '/ˈsteθəskoʊp/', 'ống nghe bác sĩ', 'noun', 'We discussed ''stethoscope'' during today''s lesson on healthcare.', '我们在今天的课程中重点讨论了“听诊器”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "tīngzhěnqì".', 'Chúng tôi đã thảo luận trọng tâm về “ống nghe bác sĩ” trong buổi học hôm nay.', 'Thiết bị y tế', 26, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0623', 'ward', '病房', 'bìngfáng', '/wɔːrd/', 'phòng bệnh', 'noun', 'Clear notes on ''ward'' help learners recall the concept faster.', '关于“病房”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "bìngfáng" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “phòng bệnh” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Y tế', 26, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0624', 'surgeon', '外科医生', 'wàikē yīshēng', '/ˈsɜːrdʒən/', 'bác sĩ phẫu thuật', 'noun', 'Understanding the role of ''surgeon'' is essential in healthcare.', '在相关场景中，理解“外科医生”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "wàikē yīshēng" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “bác sĩ phẫu thuật” rất quan trọng trong chủ đề Y tế.', 'Y tế', 26, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0625', 'dentist', '牙医', 'yáyī', '/ˈdentɪst/', 'nha sĩ', 'noun', 'The team reviewed the details about ''dentist'' before the meeting.', '团队在会议前仔细核对了关于“牙医”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "yáyī" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “nha sĩ” trước cuộc họp.', 'Y tế', 26, 'A1', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0626', 'checkup', '体检', 'tǐjiǎn', '/ˈtʃekʌp/', 'khám sức khỏe tổng quát', 'noun', 'We discussed ''checkup'' during today''s lesson on healthcare.', '我们在今天的课程中重点讨论了“体检”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "tǐjiǎn".', 'Chúng tôi đã thảo luận trọng tâm về “khám sức khỏe tổng quát” trong buổi học hôm nay.', 'Y tế dự phòng', 26, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0627', 'diagnose', '诊断出', 'zhěnduàn chū', '/ˈdaɪəɡnoʊz/', 'chẩn đoán bệnh', 'verb', 'Learners should practice how to diagnose clearly in real situations.', '学习者应在实际情境中反复练习如何“诊断出”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "zhěnduàn chū".', 'Người học nên luyện tập cách chẩn đoán bệnh rõ ràng trong tình huống thực tế.', 'Khám chữa bệnh', 26, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0628', 'prescribe', '开处方', 'kāi chǔfāng', '/prɪˈskraɪb/', 'kê đơn thuốc', 'verb', 'Please make sure to prescribe carefully before moving to the next step.', '在进入下一步之前，请务必认真“开处方”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "kāi chǔfāng".', 'Hãy nhớ kê đơn thuốc cẩn thận trước khi chuyển sang bước tiếp theo.', 'Khám chữa bệnh', 26, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0629', 'recover', '恢复健康', 'huīfù jiànkāng', '/rɪˈkʌvər/', 'bình phục', 'verb', 'Our supervisor asked us to recover without unnecessary delay.', '主管要求我们不要拖延，尽快“恢复健康”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "huīfù jiànkāng".', 'Quản lý đề nghị chúng tôi bình phục kịp thời, không trì hoãn.', 'Khám chữa bệnh', 26, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0630', 'heal', '愈合', 'yùhé', '/hiːl/', 'lành vết thương', 'verb', 'Learners should practice how to heal clearly in real situations.', '学习者应在实际情境中反复练习如何“愈合”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "yùhé".', 'Người học nên luyện tập cách lành vết thương rõ ràng trong tình huống thực tế.', 'Khám chữa bệnh', 26, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0631', 'prevent', '预防', 'yùfáng', '/prɪˈvent/', 'phòng ngừa', 'verb', 'Please make sure to prevent carefully before moving to the next step.', '在进入下一步之前，请务必认真“预防”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "yùfáng".', 'Hãy nhớ phòng ngừa cẩn thận trước khi chuyển sang bước tiếp theo.', 'Y tế dự phòng', 26, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0632', 'chronic', '慢性的', 'mànxìng de', '/ˈkrɑːnɪk/', 'mãn tính', 'adjective', 'Many readers found the explanation chronic and easy to follow.', '许多读者认为这段解释十分“慢性的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "mànxìng de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất mãn tính và dễ theo dõi.', 'Bệnh lý', 26, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0633', 'contagious', '传染性的', 'chuánrǎnxìng de', '/kənˈteɪdʒəs/', 'dễ lây nhiễm', 'adjective', 'The report highlighted a contagious factor that shaped the final decision.', '报告重点指出了一项“传染性的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "chuánrǎnxìng de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố dễ lây nhiễm đã tác động tới quyết định cuối cùng.', 'Bệnh lý', 26, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0634', 'antibiotic', '抗生素', 'kàngshēngsù', '/ˌæntibaɪˈɑːtɪk/', 'thuốc kháng sinh', 'noun', 'We discussed ''antibiotic'' during today''s lesson on pharmacy.', '我们在今天的课程中重点讨论了“抗生素”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "kàngshēngsù".', 'Chúng tôi đã thảo luận trọng tâm về “thuốc kháng sinh” trong buổi học hôm nay.', 'Dược phẩm', 27, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0635', 'painkiller', '止痛药', 'zhǐtòngyào', '/ˈpeɪnkɪlər/', 'thuốc giảm đau', 'noun', 'Clear notes on ''painkiller'' help learners recall the concept faster.', '关于“止痛药”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "zhǐtòngyào" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “thuốc giảm đau” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Dược phẩm', 27, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0636', 'side effect', '副作用', 'fùzuòyòng', '/saɪd ɪˈfekt/', 'tác dụng phụ', 'noun', 'Understanding the role of ''side effect'' is essential in pharmacy.', '在相关场景中，理解“副作用”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "fùzuòyòng" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “tác dụng phụ” rất quan trọng trong chủ đề An toàn thuốc.', 'An toàn thuốc', 27, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0637', 'supplement', '营养补充剂', 'yíngyǎng bǔchōngjì', '/ˈsʌplɪmənt/', 'thực phẩm bổ sung', 'noun', 'The team reviewed the details about ''supplement'' before the meeting.', '团队在会议前仔细核对了关于“营养补充剂”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "yíngyǎng bǔchōngjì" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “thực phẩm bổ sung” trước cuộc họp.', 'Dược phẩm', 27, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0638', 'dispense', '配药', 'pèiyào', '/dɪˈspens/', 'cấp phát thuốc', 'verb', 'Our supervisor asked us to dispense without unnecessary delay.', '主管要求我们不要拖延，尽快“配药”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "pèiyào".', 'Quản lý đề nghị chúng tôi cấp phát thuốc kịp thời, không trì hoãn.', 'Dược học', 27, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0639', 'mindfulness', '正念', 'zhèngniàn', '/ˈmaɪndfəlnəs/', 'chánh niệm', 'noun', 'Clear notes on ''mindfulness'' help learners recall the concept faster.', '关于“正念”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "zhèngniàn" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “chánh niệm” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Sức khỏe tinh thần', 28, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0640', 'resilience', '心理韧性', 'xīnlǐ rènxìng', '/rɪˈzɪliəns/', 'khả năng phục hồi tinh thần', 'noun', 'Understanding the role of ''resilience'' is essential in psychology.', '在相关场景中，理解“心理韧性”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "xīnlǐ rènxìng" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “khả năng phục hồi tinh thần” rất quan trọng trong chủ đề Sức khỏe tinh thần.', 'Sức khỏe tinh thần', 28, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0641', 'perception', '感知', 'gǎnzhī', '/pərˈsepʃən/', 'nhận thức, cảm nhận', 'noun', 'The team reviewed the details about ''perception'' before the meeting.', '团队在会议前仔细核对了关于“感知”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "gǎnzhī" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “nhận thức, cảm nhận” trước cuộc họp.', 'Tâm lý nhận thức', 28, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0642', 'cognition', '认知', 'rènzhī', '/kɑːɡˈnɪʃən/', 'quá trình nhận thức', 'noun', 'We discussed ''cognition'' during today''s lesson on psychology.', '我们在今天的课程中重点讨论了“认知”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "rènzhī".', 'Chúng tôi đã thảo luận trọng tâm về “quá trình nhận thức” trong buổi học hôm nay.', 'Tâm lý nhận thức', 28, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0643', 'burnout', '职业倦怠', 'zhíyè juàndài', '/ˈbɜːrnaʊt/', 'kiệt sức tinh thần', 'noun', 'Clear notes on ''burnout'' help learners recall the concept faster.', '关于“职业倦怠”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "zhíyè juàndài" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “kiệt sức tinh thần” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Sức khỏe tinh thần', 28, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0644', 'insomnia', '失眠', 'shīmián', '/ɪnˈsɑːmniə/', 'chứng mất ngủ', 'noun', 'Understanding the role of ''insomnia'' is essential in psychology.', '在相关场景中，理解“失眠”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "shīmián" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “chứng mất ngủ” rất quan trọng trong chủ đề Sức khỏe tinh thần.', 'Sức khỏe tinh thần', 28, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0645', 'counseling', '心理咨询', 'xīnlǐ zīxún', '/ˈkaʊnsəlɪŋ/', 'tham vấn tâm lý', 'noun', 'The team reviewed the details about ''counseling'' before the meeting.', '团队在会议前仔细核对了关于“心理咨询”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "xīnlǐ zīxún" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “tham vấn tâm lý” trước cuộc họp.', 'Sức khỏe tinh thần', 28, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0646', 'behavior', '行为', 'xíngwéi', '/bɪˈheɪvjər/', 'hành vi', 'noun', 'We discussed ''behavior'' during today''s lesson on psychology.', '我们在今天的课程中重点讨论了“行为”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "xíngwéi".', 'Chúng tôi đã thảo luận trọng tâm về “hành vi” trong buổi học hôm nay.', 'Tâm lý học', 28, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0647', 'emotion', '情绪', 'qíngxù', '/ɪˈmoʊʃən/', 'cảm xúc', 'noun', 'Clear notes on ''emotion'' help learners recall the concept faster.', '关于“情绪”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "qíngxù" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “cảm xúc” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Tâm lý học', 28, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0648', 'cope', '应对压力', 'yìngduì yālì', '/koʊp/', 'đối phó, vượt qua', 'verb', 'Learners should practice how to cope clearly in real situations.', '学习者应在实际情境中反复练习如何“应对压力”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "yìngduì yālì".', 'Người học nên luyện tập cách đối phó, vượt qua rõ ràng trong tình huống thực tế.', 'Sức khỏe tinh thần', 28, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0649', 'reflect', '反思', 'fǎnsī', '/rɪˈflekt/', 'suy ngẫm, tự phản chiếu', 'verb', 'Please make sure to reflect carefully before moving to the next step.', '在进入下一步之前，请务必认真“反思”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "fǎnsī".', 'Hãy nhớ suy ngẫm, tự phản chiếu cẩn thận trước khi chuyển sang bước tiếp theo.', 'Tâm lý học', 28, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0650', 'optimistic', '乐观的', 'lèguān de', '/ˌɑːptɪˈmɪstɪk/', 'lạc quan', 'adjective', 'Many readers found the explanation optimistic and easy to follow.', '许多读者认为这段解释十分“乐观的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "lèguān de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất lạc quan và dễ theo dõi.', 'Tâm lý học', 28, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0651', 'pessimistic', '悲观的', 'bēiguān de', '/ˌpesɪˈmɪstɪk/', 'bi quan', 'adjective', 'The report highlighted a pessimistic factor that shaped the final decision.', '报告重点指出了一项“悲观的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "bēiguān de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố bi quan đã tác động tới quyết định cuối cùng.', 'Tâm lý học', 28, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0652', 'community', '社区', 'shèqū', '/kəˈmjuːnəti/', 'cộng đồng', 'noun', 'Understanding the role of ''community'' is essential in social work.', '在相关场景中，理解“社区”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "shèqū" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “cộng đồng” rất quan trọng trong chủ đề Xã hội.', 'Xã hội', 29, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
