INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0663', 'advocate', '倡导', 'chàngdǎo', '/ˈædvəkeɪt/', 'vận động, ủng hộ', 'verb', 'Learners should practice how to advocate clearly in real situations.', '学习者应在实际情境中反复练习如何“倡导”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "chàngdǎo".', 'Người học nên luyện tập cách vận động, ủng hộ rõ ràng trong tình huống thực tế.', 'Công tác xã hội', 29, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0664', 'participate', '参与', 'cānyù', '/pɑːrˈtɪsɪpeɪt/', 'tham gia', 'verb', 'Please make sure to participate carefully before moving to the next step.', '在进入下一步之前，请务必认真“参与”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "cānyù".', 'Hãy nhớ tham gia cẩn thận trước khi chuyển sang bước tiếp theo.', 'Xã hội', 29, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
