INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0667', 'tournament', '锦标赛', 'jǐnbiāosài', '/ˈtʊrnəmənt/', 'giải đấu', 'noun', 'Clear notes on ''tournament'' help learners recall the concept faster.', '关于“锦标赛”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "jǐnbiāosài" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “giải đấu” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Thể thao', 39, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0668', 'stadium', '体育场', 'tǐyùchǎng', '/ˈsteɪdiəm/', 'sân vận động', 'noun', 'Understanding the role of ''stadium'' is essential in sports science.', '在相关场景中，理解“体育场”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "tǐyùchǎng" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “sân vận động” rất quan trọng trong chủ đề Thể thao.', 'Thể thao', 39, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
