INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0674', 'sprint', '短跑冲刺', 'duǎnpǎo chōngcì', '/sprɪnt/', 'chạy nước rút', 'verb', 'Our supervisor asked us to sprint without unnecessary delay.', '主管要求我们不要拖延，尽快“短跑冲刺”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "duǎnpǎo chōngcì".', 'Quản lý đề nghị chúng tôi chạy nước rút kịp thời, không trì hoãn.', 'Tập luyện', 39, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0675', 'stretch', '拉伸', 'lāshēn', '/stretʃ/', 'giãn cơ', 'verb', 'Learners should practice how to stretch clearly in real situations.', '学习者应在实际情境中反复练习如何“拉伸”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "lāshēn".', 'Người học nên luyện tập cách giãn cơ rõ ràng trong tình huống thực tế.', 'Tập luyện', 39, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0676', 'compete', '比赛竞争', 'bǐsài jìngzhēng', '/kəmˈpiːt/', 'thi đấu', 'verb', 'Please make sure to compete carefully before moving to the next step.', '在进入下一步之前，请务必认真“比赛竞争”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "bǐsài jìngzhēng".', 'Hãy nhớ thi đấu cẩn thận trước khi chuyển sang bước tiếp theo.', 'Thể thao', 39, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
