INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0689', 'enforce', '强制执行', 'qiángzhì zhíxíng', '/ɪnˈfɔːrs/', 'thực thi luật', 'verb', 'Our supervisor asked us to enforce without unnecessary delay.', '主管要求我们不要拖延，尽快“强制执行”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "qiángzhì zhíxíng".', 'Quản lý đề nghị chúng tôi thực thi luật kịp thời, không trì hoãn.', 'Pháp luật', 6, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0690', 'violate', '违反', 'wéifǎn', '/ˈvaɪəleɪt/', 'vi phạm', 'verb', 'Learners should practice how to violate clearly in real situations.', '学习者应在实际情境中反复练习如何“违反”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "wéifǎn".', 'Người học nên luyện tập cách vi phạm rõ ràng trong tình huống thực tế.', 'Pháp luật', 6, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0691', 'legal', '合法的', 'héfǎ de', '/ˈliːɡəl/', 'hợp pháp', 'adjective', 'It is important to stay legal when handling complex tasks.', '在处理复杂任务时，保持“合法的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "héfǎ de" fēicháng zhòngyào.', 'Giữ được tính chất hợp pháp rất quan trọng khi xử lý công việc phức tạp.', 'Pháp luật', 6, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0692', 'binding', '具有约束力的', 'jùyǒu yuēshùlì de', '/ˈbaɪndɪŋ/', 'có giá trị ràng buộc', 'adjective', 'Many readers found the explanation binding and easy to follow.', '许多读者认为这段解释十分“具有约束力的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "jùyǒu yuēshùlì de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất có giá trị ràng buộc và dễ theo dõi.', 'Pháp luật', 6, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0693', 'property', '房产', 'fángchǎn', '/ˈprɑːpərti/', 'bất động sản', 'noun', 'The team reviewed the details about ''property'' before the meeting.', '团队在会议前仔细核对了关于“房产”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "fángchǎn" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “bất động sản” trước cuộc họp.', 'Bất động sản', 34, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0694', 'zoning', '区域规划', 'qūyù guīhuà', '/ˈzoʊnɪŋ/', 'phân vùng quy hoạch', 'noun', 'We discussed ''zoning'' during today''s lesson on real estate.', '我们在今天的课程中重点讨论了“区域规划”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "qūyù guīhuà".', 'Chúng tôi đã thảo luận trọng tâm về “phân vùng quy hoạch” trong buổi học hôm nay.', 'Quy hoạch đô thị', 34, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0695', 'suburb', '郊区', 'jiāoqū', '/ˈsʌbɜːrb/', 'vùng ngoại ô', 'noun', 'Clear notes on ''suburb'' help learners recall the concept faster.', '关于“郊区”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "jiāoqū" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “vùng ngoại ô” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Quy hoạch đô thị', 34, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0696', 'downtown', '市中心', 'shìzhōngxīn', '/ˌdaʊnˈtaʊn/', 'trung tâm thành phố', 'noun', 'Understanding the role of ''downtown'' is essential in real estate.', '在相关场景中，理解“市中心”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "shìzhōngxīn" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “trung tâm thành phố” rất quan trọng trong chủ đề Quy hoạch đô thị.', 'Quy hoạch đô thị', 34, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0697', 'broker', '房产经纪人', 'fángchǎn jīngjìrén', '/ˈbroʊkər/', 'nhân viên môi giới', 'noun', 'The team reviewed the details about ''broker'' before the meeting.', '团队在会议前仔细核对了关于“房产经纪人”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "fángchǎn jīngjìrén" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “nhân viên môi giới” trước cuộc họp.', 'Bất động sản', 34, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0698', 'rent', '租借', 'zūjiè', '/rent/', 'thuê nhà', 'verb', 'Our supervisor asked us to rent without unnecessary delay.', '主管要求我们不要拖延，尽快“租借”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "zūjiè".', 'Quản lý đề nghị chúng tôi thuê nhà kịp thời, không trì hoãn.', 'Thuê mua nhà', 34, 'A1', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0699', 'inspect', '验房检查', 'yànfáng jiǎnchá', '/ɪnˈspekt/', 'kiểm tra hiện trạng', 'verb', 'Learners should practice how to inspect clearly in real situations.', '学习者应在实际情境中反复练习如何“验房检查”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "yànfáng jiǎnchá".', 'Người học nên luyện tập cách kiểm tra hiện trạng rõ ràng trong tình huống thực tế.', 'Bất động sản', 34, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
