INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0712', 'govern', '治理', 'zhìlǐ', '/ˈɡʌvərn/', 'quản trị, điều hành', 'verb', 'Please make sure to govern carefully before moving to the next step.', '在进入下一步之前，请务必认真“治理”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "zhìlǐ".', 'Hãy nhớ quản trị, điều hành cẩn thận trước khi chuyển sang bước tiếp theo.', 'Hành chính công', 40, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0713', 'preserve', '保护遗产', 'bǎohù yíchǎn', '/prɪˈzɜːrv/', 'bảo tồn', 'verb', 'Our supervisor asked us to preserve without unnecessary delay.', '主管要求我们不要拖延，尽快“保护遗产”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "bǎohù yíchǎn".', 'Quản lý đề nghị chúng tôi bảo tồn kịp thời, không trì hoãn.', 'Lịch sử', 40, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0714', 'historical', '历史的', 'lìshǐ de', '/hɪˈstɔːrɪkəl/', 'thuộc lịch sử', 'adjective', 'The report highlighted a historical factor that shaped the final decision.', '报告重点指出了一项“历史的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "lìshǐ de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố thuộc lịch sử đã tác động tới quyết định cuối cùng.', 'Lịch sử', 40, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0715', 'civic', '公民的', 'gōngmín de', '/ˈsɪvɪk/', 'thuộc công dân, đô thị', 'adjective', 'It is important to stay civic when handling complex tasks.', '在处理复杂任务时，保持“公民的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "gōngmín de" fēicháng zhòngyào.', 'Giữ được tính chất thuộc công dân, đô thị rất quan trọng khi xử lý công việc phức tạp.', 'Hành chính công', 40, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0716', 'muscle', '肌肉', 'jīròu', '/ˈmʌsəl/', 'cơ bắp', 'noun', 'Understanding the role of ''muscle'' is essential in healthcare.', '在相关场景中，理解“肌肉”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "jīròu" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “cơ bắp” rất quan trọng trong chủ đề Cơ thể người.', 'Cơ thể người', 26, 'A2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0717', 'skeleton', '骨骼', 'gǔgé', '/ˈskelətən/', 'bộ xương', 'noun', 'The team reviewed the details about ''skeleton'' before the meeting.', '团队在会议前仔细核对了关于“骨骼”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "gǔgé" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “bộ xương” trước cuộc họp.', 'Cơ thể người', 26, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0718', 'lung', '肺', 'fèi', '/lʌŋ/', 'phổi', 'noun', 'We discussed ''lung'' during today''s lesson on healthcare.', '我们在今天的课程中重点讨论了“肺”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "fèi".', 'Chúng tôi đã thảo luận trọng tâm về “phổi” trong buổi học hôm nay.', 'Cơ thể người', 26, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0719', 'liver', '肝脏', 'gānzàng', '/ˈlɪvər/', 'gan', 'noun', 'Clear notes on ''liver'' help learners recall the concept faster.', '关于“肝脏”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "gānzàng" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “gan” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Cơ thể người', 26, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
