INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0725', 'hydration', '补水', 'bǔshuǐ', '/haɪˈdreɪʃən/', 'bổ sung nước cho cơ thể', 'noun', 'The team reviewed the details about ''hydration'' before the meeting.', '团队在会议前仔细核对了关于“补水”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "bǔshuǐ" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “bổ sung nước cho cơ thể” trước cuộc họp.', 'Chăm sóc sức khỏe', 26, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0726', 'allergic', '过敏的', 'guòmǐn de', '/əˈlɜːrdʒɪk/', 'bị dị ứng', 'adjective', 'The report highlighted a allergic factor that shaped the final decision.', '报告重点指出了一项“过敏的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "guòmǐn de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố bị dị ứng đã tác động tới quyết định cuối cùng.', 'Triệu chứng', 26, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0727', 'healthy', '健康的', 'jiànkāng de', '/ˈhelθi/', 'khỏe mạnh', 'adjective', 'It is important to stay healthy when handling complex tasks.', '在处理复杂任务时，保持“健康的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "jiànkāng de" fēicháng zhòngyào.', 'Giữ được tính chất khỏe mạnh rất quan trọng khi xử lý công việc phức tạp.', 'Chăm sóc sức khỏe', 26, 'A1', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0728', 'balanced', '均衡的', 'jūnhéng de', '/ˈbælənst/', 'cân bằng', 'adjective', 'Many readers found the explanation balanced and easy to follow.', '许多读者认为这段解释十分“均衡的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "jūnhéng de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất cân bằng và dễ theo dõi.', 'Chăm sóc sức khỏe', 26, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0729', 'energetic', '精力充沛的', 'jīnglì chōngpèi de', '/ˌenərˈdʒetɪk/', 'tràn đầy năng lượng', 'adjective', 'The report highlighted a energetic factor that shaped the final decision.', '报告重点指出了一项“精力充沛的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "jīnglì chōngpèi de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố tràn đầy năng lượng đã tác động tới quyết định cuối cùng.', 'Tập luyện', 39, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0730', 'agile', '敏捷的', 'mǐnjié de', '/ˈædʒəl/', 'nhanh nhẹn, linh hoạt', 'adjective', 'It is important to stay agile when handling complex tasks.', '在处理复杂任务时，保持“敏捷的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "mǐnjié de" fēicháng zhòngyào.', 'Giữ được tính chất nhanh nhẹn, linh hoạt rất quan trọng khi xử lý công việc phức tạp.', 'Khoa học vận động', 39, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
