INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0733', 'crop', '农作物', 'nóngzuòwù', '/krɑːp/', 'hoa màu, cây trồng', 'noun', 'The team reviewed the details about ''crop'' before the meeting.', '团队在会议前仔细核对了关于“农作物”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "nóngzuòwù" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “hoa màu, cây trồng” trước cuộc họp.', 'Canh tác', 19, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0734', 'cultivate', '耕作栽培', 'gēngzuò zāipéi', '/ˈkʌltɪveɪt/', 'canh tác, trồng trọt', 'verb', 'Our supervisor asked us to cultivate without unnecessary delay.', '主管要求我们不要拖延，尽快“耕作栽培”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "gēngzuò zāipéi".', 'Quản lý đề nghị chúng tôi canh tác, trồng trọt kịp thời, không trì hoãn.', 'Canh tác', 19, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0735', 'sow', '播种', 'bōzhǒng', '/soʊ/', 'gieo hạt', 'verb', 'Learners should practice how to sow clearly in real situations.', '学习者应在实际情境中反复练习如何“播种”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "bōzhǒng".', 'Người học nên luyện tập cách gieo hạt rõ ràng trong tình huống thực tế.', 'Canh tác', 19, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0736', 'organic', '有机的', 'yǒujī de', '/ɔːrˈɡænɪk/', 'hữu cơ', 'adjective', 'It is important to stay organic when handling complex tasks.', '在处理复杂任务时，保持“有机的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "yǒujī de" fēicháng zhòngyào.', 'Giữ được tính chất hữu cơ rất quan trọng khi xử lý công việc phức tạp.', 'Nông sản', 19, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0737', 'fertile', '肥沃的', 'féiwò de', '/ˈfɜːrtəl/', 'màu mỡ', 'adjective', 'Many readers found the explanation fertile and easy to follow.', '许多读者认为这段解释十分“肥沃的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "féiwò de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất màu mỡ và dễ theo dõi.', 'Canh tác', 19, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0738', 'timber', '木材', 'mùcái', '/ˈtɪmbər/', 'gỗ xây dựng', 'noun', 'We discussed ''timber'' during today''s lesson on forestry and fisheries.', '我们在今天的课程中重点讨论了“木材”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "mùcái".', 'Chúng tôi đã thảo luận trọng tâm về “gỗ xây dựng” trong buổi học hôm nay.', 'Lâm nghiệp', 20, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0739', 'reforestation', '重新造林', 'chóngxīn zàolín', '/ˌriːˌfɔːrɪˈsteɪʃən/', 'tái trồng rừng', 'noun', 'Clear notes on ''reforestation'' help learners recall the concept faster.', '关于“重新造林”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "chóngxīn zàolín" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “tái trồng rừng” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Lâm nghiệp', 20, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0740', 'aquaculture', '水产养殖', 'shuǐchǎn yǎngzhí', '/ˈækwəkʌltʃər/', 'nuôi trồng thủy sản', 'noun', 'Understanding the role of ''aquaculture'' is essential in forestry and fisheries.', '在相关场景中，理解“水产养殖”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "shuǐchǎn yǎngzhí" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “nuôi trồng thủy sản” rất quan trọng trong chủ đề Thủy sản.', 'Thủy sản', 20, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0741', 'coral reef', '珊瑚礁', 'shānhújiāo', '/ˈkɔːrəl riːf/', 'rạn san hô', 'noun', 'The team reviewed the details about ''coral reef'' before the meeting.', '团队在会议前仔细核对了关于“珊瑚礁”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "shānhújiāo" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “rạn san hô” trước cuộc họp.', 'Hệ sinh thái biển', 20, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
