INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0754', 'humidity', '湿度', 'shīdù', '/hjuːˈmɪdəti/', 'độ ẩm không khí', 'noun', 'We discussed ''humidity'' during today''s lesson on environmental sustainability.', '我们在今天的课程中重点讨论了“湿度”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "shīdù".', 'Chúng tôi đã thảo luận trọng tâm về “độ ẩm không khí” trong buổi học hôm nay.', 'Thời tiết', 21, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0755', 'temperature', '温度', 'wēndù', '/ˈtemprətʃər/', 'nhiệt độ', 'noun', 'Clear notes on ''temperature'' help learners recall the concept faster.', '关于“温度”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "wēndù" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “nhiệt độ” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Thời tiết', 21, 'A1', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0756', 'glacier', '冰川', 'bīngchuān', '/ˈɡleɪʃər/', 'sông băng', 'noun', 'Understanding the role of ''glacier'' is essential in environmental sustainability.', '在相关场景中，理解“冰川”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "bīngchuān" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “sông băng” rất quan trọng trong chủ đề Thiên nhiên.', 'Thiên nhiên', 21, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0757', 'recycle', '回收', 'huíshōu', '/ˌriːˈsaɪkəl/', 'tái chế', 'verb', 'Please make sure to recycle carefully before moving to the next step.', '在进入下一步之前，请务必认真“回收”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "huíshōu".', 'Hãy nhớ tái chế cẩn thận trước khi chuyển sang bước tiếp theo.', 'Bảo vệ môi trường', 21, 'A2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0758', 'conserve', '节约保护', 'jiéyuē bǎohù', '/kənˈsɜːrv/', 'bảo tồn, tiết kiệm', 'verb', 'Our supervisor asked us to conserve without unnecessary delay.', '主管要求我们不要拖延，尽快“节约保护”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "jiéyuē bǎohù".', 'Quản lý đề nghị chúng tôi bảo tồn, tiết kiệm kịp thời, không trì hoãn.', 'Bảo vệ môi trường', 21, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0759', 'pollute', '污染', 'wūrǎn', '/pəˈluːt/', 'gây ô nhiễm', 'verb', 'Learners should practice how to pollute clearly in real situations.', '学习者应在实际情境中反复练习如何“污染”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "wūrǎn".', 'Người học nên luyện tập cách gây ô nhiễm rõ ràng trong tình huống thực tế.', 'Bảo vệ môi trường', 21, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0760', 'biodegradable', '可生物降解的', 'kě shēngwù jiàngjiě de', '/ˌbaɪoʊdɪˈɡreɪdəbəl/', 'phân hủy sinh học được', 'adjective', 'It is important to stay biodegradable when handling complex tasks.', '在处理复杂任务时，保持“可生物降解的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "kě shēngwù jiàngjiě de" fēicháng zhòngyào.', 'Giữ được tính chất phân hủy sinh học được rất quan trọng khi xử lý công việc phức tạp.', 'Bảo vệ môi trường', 21, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0761', 'eco-friendly', '环保的', 'huánbǎo de', '/ˌiːkoʊ ˈfrendli/', 'thân thiện với môi trường', 'adjective', 'Many readers found the explanation eco-friendly and easy to follow.', '许多读者认为这段解释十分“环保的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "huánbǎo de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất thân thiện với môi trường và dễ theo dõi.', 'Bảo vệ môi trường', 21, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0762', 'sunrise', '日出', 'rìchū', '/ˈsʌnraɪz/', 'bình minh', 'noun', 'We discussed ''sunrise'' during today''s lesson on everyday communication.', '我们在今天的课程中重点讨论了“日出”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "rìchū".', 'Chúng tôi đã thảo luận trọng tâm về “bình minh” trong buổi học hôm nay.', 'Thiên nhiên', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
