INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0827', 'achieve', '实现', 'shíxiàn', '/əˈtʃiːv/', 'đạt được', 'verb', 'Our supervisor asked us to achieve without unnecessary delay.', '主管要求我们不要拖延，尽快“实现”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "shíxiàn".', 'Quản lý đề nghị chúng tôi đạt được kịp thời, không trì hoãn.', 'Hành động cốt lõi', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0828', 'acquire', '获得', 'huòdé', '/əˈkwaɪər/', 'thu nhận, đạt được', 'verb', 'Learners should practice how to acquire clearly in real situations.', '学习者应在实际情境中反复练习如何“获得”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "huòdé".', 'Người học nên luyện tập cách thu nhận, đạt được rõ ràng trong tình huống thực tế.', 'Học thuật & kỹ năng', 2, 'B2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0829', 'adapt', '适应', 'shìyìng', '/əˈdæpt/', 'thích nghi', 'verb', 'Please make sure to adapt carefully before moving to the next step.', '在进入下一步之前，请务必认真“适应”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "shìyìng".', 'Hãy nhớ thích nghi cẩn thận trước khi chuyển sang bước tiếp theo.', 'Hành động cốt lõi', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0830', 'adjust', '调整', 'tiáozhěng', '/əˈdʒʌst/', 'điều chỉnh', 'verb', 'Our supervisor asked us to adjust without unnecessary delay.', '主管要求我们不要拖延，尽快“调整”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "tiáozhěng".', 'Quản lý đề nghị chúng tôi điều chỉnh kịp thời, không trì hoãn.', 'Hành động cốt lõi', 1, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0831', 'admire', '钦佩', 'qīnpèi', '/ədˈmaɪər/', 'ngưỡng mộ', 'verb', 'Learners should practice how to admire clearly in real situations.', '学习者应在实际情境中反复练习如何“钦佩”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "qīnpèi".', 'Người học nên luyện tập cách ngưỡng mộ rõ ràng trong tình huống thực tế.', 'Cảm xúc & thái độ', 1, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0832', 'admit', '承认', 'chéngrèn', '/ədˈmɪt/', 'thừa nhận', 'verb', 'Please make sure to admit carefully before moving to the next step.', '在进入下一步之前，请务必认真“承认”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "chéngrèn".', 'Hãy nhớ thừa nhận cẩn thận trước khi chuyển sang bước tiếp theo.', 'Giao tiếp', 1, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0833', 'adopt', '采用', 'cǎiyòng', '/əˈdɑːpt/', 'áp dụng, nhận nuôi', 'verb', 'Our supervisor asked us to adopt without unnecessary delay.', '主管要求我们不要拖延，尽快“采用”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "cǎiyòng".', 'Quản lý đề nghị chúng tôi áp dụng, nhận nuôi kịp thời, không trì hoãn.', 'Quyết định', 3, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
