INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0887', 'confuse', '使困惑', 'shǐ kùnhuò', '/kənˈfjuːz/', 'làm nhầm lẫn', 'verb', 'Our supervisor asked us to confuse without unnecessary delay.', '主管要求我们不要拖延，尽快“使困惑”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "shǐ kùnhuò".', 'Quản lý đề nghị chúng tôi làm nhầm lẫn kịp thời, không trì hoãn.', 'Giao tiếp', 1, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
