INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0964', 'express', '表达', 'biǎodá', '/ɪkˈspres/', 'bày tỏ', 'verb', 'Please make sure to express carefully before moving to the next step.', '在进入下一步之前，请务必认真“表达”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "biǎodá".', 'Hãy nhớ bày tỏ cẩn thận trước khi chuyển sang bước tiếp theo.', 'Giao tiếp', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0965', 'extend', '延长扩展', 'yáncháng kuòzhǎn', '/ɪkˈstend/', 'kéo dài, mở rộng', 'verb', 'Our supervisor asked us to extend without unnecessary delay.', '主管要求我们不要拖延，尽快“延长扩展”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "yáncháng kuòzhǎn".', 'Quản lý đề nghị chúng tôi kéo dài, mở rộng kịp thời, không trì hoãn.', 'Quản lý dự án', 7, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
