INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0989', 'grant', '授予准予', 'shòuyǔ zhǔnyǔ', '/ɡrænt/', 'cấp phép, ban tặng', 'verb', 'Our supervisor asked us to grant without unnecessary delay.', '主管要求我们不要拖延，尽快“授予准予”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "shòuyǔ zhǔnyǔ".', 'Quản lý đề nghị chúng tôi cấp phép, ban tặng kịp thời, không trì hoãn.', 'Hành chính', 40, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0990', 'grasp', '领会掌握', 'lǐnghuì zhǎngwò', '/ɡræsp/', 'nắm bắt hiểu rõ', 'verb', 'Learners should practice how to grasp clearly in real situations.', '学习者应在实际情境中反复练习如何“领会掌握”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "lǐnghuì zhǎngwò".', 'Người học nên luyện tập cách nắm bắt hiểu rõ rõ ràng trong tình huống thực tế.', 'Học tập', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-0991', 'guarantee', '担保保证', 'dānbǎo bǎozhèng', '/ˌɡærənˈtiː/', 'bảo đảm chắc chắn', 'verb', 'Please make sure to guarantee carefully before moving to the next step.', '在进入下一步之前，请务必认真“担保保证”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "dānbǎo bǎozhèng".', 'Hãy nhớ bảo đảm chắc chắn cẩn thận trước khi chuyển sang bước tiếp theo.', 'Dịch vụ', 3, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
