INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1014', 'insert', '插入', 'chārù', '/ɪnˈsɜːrt/', 'chèn vào', 'verb', 'Learners should practice how to insert clearly in real situations.', '学习者应在实际情境中反复练习如何“插入”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "chārù".', 'Người học nên luyện tập cách chèn vào rõ ràng trong tình huống thực tế.', 'Công nghệ', 9, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
