INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1039', 'monitor', '监控监测', 'jiānkòng jiāncè', '/ˈmɑːnɪtər/', 'giám sát, theo dõi', 'verb', 'Please make sure to monitor carefully before moving to the next step.', '在进入下一步之前，请务必认真“监控监测”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "jiānkòng jiāncè".', 'Hãy nhớ giám sát, theo dõi cẩn thận trước khi chuyển sang bước tiếp theo.', 'Vận hành', 9, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
