INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1064', 'prohibit', '明令禁止', 'mínglìng jìnzhǐ', '/prəˈhɪbɪt/', 'cấm theo quy định', 'verb', 'Our supervisor asked us to prohibit without unnecessary delay.', '主管要求我们不要拖延，尽快“明令禁止”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "mínglìng jìnzhǐ".', 'Quản lý đề nghị chúng tôi cấm theo quy định kịp thời, không trì hoãn.', 'Pháp luật', 6, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
