INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1113', 'satisfy', '满足使满意', 'mǎnzú shǐ mǎnyì', '/ˈsætɪsfaɪ/', 'làm hài lòng', 'verb', 'Learners should practice how to satisfy clearly in real situations.', '学习者应在实际情境中反复练习如何“满足使满意”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "mǎnzú shǐ mǎnyì".', 'Người học nên luyện tập cách làm hài lòng rõ ràng trong tình huống thực tế.', 'Dịch vụ', 3, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
