INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1161', 'urge', '敦促力劝', 'dūncù lìquàn', '/ɜːrdʒ/', 'thúc giục', 'verb', 'Learners should practice how to urge clearly in real situations.', '学习者应在实际情境中反复练习如何“敦促力劝”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "dūncù lìquàn".', 'Người học nên luyện tập cách thúc giục rõ ràng trong tình huống thực tế.', 'Giao tiếp', 1, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1162', 'utilize', '有效利用', 'yǒuxiào lìyòng', '/ˈjuːtəlaɪz/', 'tận dụng hiệu quả', 'verb', 'Please make sure to utilize carefully before moving to the next step.', '在进入下一步之前，请务必认真“有效利用”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "yǒuxiào lìyòng".', 'Hãy nhớ tận dụng hiệu quả cẩn thận trước khi chuyển sang bước tiếp theo.', 'Vận hành', 3, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1163', 'validate', '验证确认', 'yànzhèng quèrèn', '/ˈvælɪdeɪt/', 'xác thực tính hợp lệ', 'verb', 'Our supervisor asked us to validate without unnecessary delay.', '主管要求我们不要拖延，尽快“验证确认”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "yànzhèng quèrèn".', 'Quản lý đề nghị chúng tôi xác thực tính hợp lệ kịp thời, không trì hoãn.', 'Kiểm thử', 12, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1164', 'value', '重视估价', 'zhòngshì gūjià', '/ˈvæljuː/', 'coi trọng, định giá', 'verb', 'Learners should practice how to value clearly in real situations.', '学习者应在实际情境中反复练习如何“重视估价”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "zhòngshì gūjià".', 'Người học nên luyện tập cách coi trọng, định giá rõ ràng trong tình huống thực tế.', 'Kinh doanh', 3, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1165', 'vary', '变化各异', 'biànhuà gèyì', '/ˈveri/', 'thay đổi đa dạng', 'verb', 'Please make sure to vary carefully before moving to the next step.', '在进入下一步之前，请务必认真“变化各异”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "biànhuà gèyì".', 'Hãy nhớ thay đổi đa dạng cẩn thận trước khi chuyển sang bước tiếp theo.', 'Học thuật', 2, 'B2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1166', 'warn', '警告提醒', 'jǐnggào tíxǐng', '/wɔːrn/', 'cảnh báo', 'verb', 'Our supervisor asked us to warn without unnecessary delay.', '主管要求我们不要拖延，尽快“警告提醒”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "jǐnggào tíxǐng".', 'Quản lý đề nghị chúng tôi cảnh báo kịp thời, không trì hoãn.', 'An toàn', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1167', 'weigh', '称重权衡', 'chēngzhòng quánhéng', '/weɪ/', 'cân nặng, cân nhắc', 'verb', 'Learners should practice how to weigh clearly in real situations.', '学习者应在实际情境中反复练习如何“称重权衡”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "chēngzhòng quánhéng".', 'Người học nên luyện tập cách cân nặng, cân nhắc rõ ràng trong tình huống thực tế.', 'Đời sống', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1168', 'whisper', '低声说', 'dīshēng shuō', '/ˈwɪspər/', 'nói thì thầm', 'verb', 'Please make sure to whisper carefully before moving to the next step.', '在进入下一步之前，请务必认真“低声说”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "dīshēng shuō".', 'Hãy nhớ nói thì thầm cẩn thận trước khi chuyển sang bước tiếp theo.', 'Giao tiếp', 1, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1169', 'withdraw', '撤回取钱', 'chèhuí qǔqián', '/wɪðˈdrɔː/', 'rút tiền, rút lui', 'verb', 'Our supervisor asked us to withdraw without unnecessary delay.', '主管要求我们不要拖延，尽快“撤回取钱”。', 'Zhǔguǎn yāoqiú wǒmen bùyào tuōyán, jǐnkuài "chèhuí qǔqián".', 'Quản lý đề nghị chúng tôi rút tiền, rút lui kịp thời, không trì hoãn.', 'Ngân hàng', 5, 'B2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1170', 'wrap', '包装包裹', 'bāozhuāng bāoguǒ', '/ræp/', 'gói bọc lại', 'verb', 'Learners should practice how to wrap clearly in real situations.', '学习者应在实际情境中反复练习如何“包装包裹”。', 'Xuéxízhě yīng zài shíjì qíngjìng zhōng fǎnfù liànxí rúhé "bāozhuāng bāoguǒ".', 'Người học nên luyện tập cách gói bọc lại rõ ràng trong tình huống thực tế.', 'Đời sống', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1171', 'yield', '产出屈服', 'chǎnchū qūfú', '/jiːld/', 'mang lại sản lượng, nhường đường', 'verb', 'Please make sure to yield carefully before moving to the next step.', '在进入下一步之前，请务必认真“产出屈服”。', 'Zài jìnrù xià yībù zhīqián, qǐng wùbì rènzhēn "chǎnchū qūfú".', 'Hãy nhớ mang lại sản lượng, nhường đường cẩn thận trước khi chuyển sang bước tiếp theo.', 'Nông nghiệp', 19, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1172', 'abundant', '丰富的', 'fēngfù de', '/əˈbʌndənt/', 'dồi dào, phong phú', 'adjective', 'Many readers found the explanation abundant and easy to follow.', '许多读者认为这段解释十分“丰富的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "fēngfù de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất dồi dào, phong phú và dễ theo dõi.', 'Mô tả mức độ', 21, 'B2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1173', 'accessible', '易获取的', 'yì huòqǔ de', '/əkˈsesəbəl/', 'dễ tiếp cận', 'adjective', 'The report highlighted a accessible factor that shaped the final decision.', '报告重点指出了一项“易获取的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "yì huòqǔ de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố dễ tiếp cận đã tác động tới quyết định cuối cùng.', 'Công nghệ', 9, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1174', 'adequate', '充足的', 'chōngzú de', '/ˈædɪkwət/', 'đầy đủ, thỏa đáng', 'adjective', 'It is important to stay adequate when handling complex tasks.', '在处理复杂任务时，保持“充足的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "chōngzú de" fēicháng zhòngyào.', 'Giữ được tính chất đầy đủ, thỏa đáng rất quan trọng khi xử lý công việc phức tạp.', 'Đánh giá', 3, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1175', 'adjacent', '相邻的', 'xiānglín de', '/əˈdʒeɪsənt/', 'liền kề', 'adjective', 'Many readers found the explanation adjacent and easy to follow.', '许多读者认为这段解释十分“相邻的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "xiānglín de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất liền kề và dễ theo dõi.', 'Không gian', 16, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1176', 'advanced', '先进的', 'xiānjìn de', '/ədˈvænst/', 'tiên tiến, nâng cao', 'adjective', 'The report highlighted a advanced factor that shaped the final decision.', '报告重点指出了一项“先进的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "xiānjìn de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố tiên tiến, nâng cao đã tác động tới quyết định cuối cùng.', 'Công nghệ', 9, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1177', 'adverse', '不利的', 'bùlì de', '/ædˈvɜːrs/', 'bất lợi, có hại', 'adjective', 'It is important to stay adverse when handling complex tasks.', '在处理复杂任务时，保持“不利的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "bùlì de" fēicháng zhòngyào.', 'Giữ được tính chất bất lợi, có hại rất quan trọng khi xử lý công việc phức tạp.', 'Rủi ro', 35, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1178', 'alert', '警觉的', 'jǐngjué de', '/əˈlɜːrt/', 'cảnh giác, tỉnh táo', 'adjective', 'Many readers found the explanation alert and easy to follow.', '许多读者认为这段解释十分“警觉的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "jǐngjué de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất cảnh giác, tỉnh táo và dễ theo dõi.', 'An toàn', 11, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1179', 'alternative', '替代的', 'tìdài de', '/ɔːlˈtɜːrnətɪv/', 'thay thế', 'adjective', 'The report highlighted a alternative factor that shaped the final decision.', '报告重点指出了一项“替代的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "tìdài de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố thay thế đã tác động tới quyết định cuối cùng.', 'Giải pháp', 3, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1180', 'ambitious', '有抱负的', 'yǒu bàofù de', '/æmˈbɪʃəs/', 'đầy tham vọng', 'adjective', 'It is important to stay ambitious when handling complex tasks.', '在处理复杂任务时，保持“有抱负的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "yǒu bàofù de" fēicháng zhòngyào.', 'Giữ được tính chất đầy tham vọng rất quan trọng khi xử lý công việc phức tạp.', 'Tính cách', 7, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1181', 'ample', '充裕的', 'chōngyù de', '/ˈæmpəl/', 'rộng rãi, dư dả', 'adjective', 'Many readers found the explanation ample and easy to follow.', '许多读者认为这段解释十分“充裕的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "chōngyù de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất rộng rãi, dư dả và dễ theo dõi.', 'Mô tả mức độ', 1, 'C1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1182', 'ancient', '古老的', 'gǔlǎo de', '/ˈeɪnʃənt/', 'cổ đại', 'adjective', 'The report highlighted a ancient factor that shaped the final decision.', '报告重点指出了一项“古老的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "gǔlǎo de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố cổ đại đã tác động tới quyết định cuối cùng.', 'Lịch sử', 40, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
