INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1452', 'tough', '艰难的坚韧的', 'jiānnán de jiānrèn de', '/tʌf/', 'khó khăn, cứng rắn', 'adjective', 'The report highlighted a tough factor that shaped the final decision.', '报告重点指出了一项“艰难的坚韧的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "jiānnán de jiānrèn de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố khó khăn, cứng rắn đã tác động tới quyết định cuối cùng.', 'Đời sống', 1, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
