INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1474', 'vulnerable', '脆弱的易受攻击的', 'cuìruò de yì shòu gōngjī de', '/ˈvʌlnərəbəl/', 'dễ bị tổn thương', 'adjective', 'It is important to stay vulnerable when handling complex tasks.', '在处理复杂任务时，保持“脆弱的易受攻击的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "cuìruò de yì shòu gōngjī de" fēicháng zhòngyào.', 'Giữ được tính chất dễ bị tổn thương rất quan trọng khi xử lý công việc phức tạp.', 'An ninh mạng', 11, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1475', 'wealthy', '富有的富裕的', 'fùyǒu de fùyù de', '/ˈwelθi/', 'giàu có', 'adjective', 'Many readers found the explanation wealthy and easy to follow.', '许多读者认为这段解释十分“富有的富裕的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "fùyǒu de fùyù de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất giàu có và dễ theo dõi.', 'Tài chính', 5, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1476', 'widespread', '广泛流传的普遍的', 'guǎngfàn liúchuán de pǔbiàn de', '/ˈwaɪdspred/', 'phổ biến rộng rãi', 'adjective', 'The report highlighted a widespread factor that shaped the final decision.', '报告重点指出了一项“广泛流传的普遍的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "guǎngfàn liúchuán de pǔbiàn de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố phổ biến rộng rãi đã tác động tới quyết định cuối cùng.', 'Xã hội', 29, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1477', 'willing', '愿意的乐意的', 'yuànyì de lèyì de', '/ˈwɪlɪŋ/', 'sẵn lòng', 'adjective', 'It is important to stay willing when handling complex tasks.', '在处理复杂任务时，保持“愿意的乐意的”非常重要。', 'Zài chǔlǐ fùzá rènwù shí, bǎochí "yuànyì de lèyì de" fēicháng zhòngyào.', 'Giữ được tính chất sẵn lòng rất quan trọng khi xử lý công việc phức tạp.', 'Thái độ', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1478', 'wise', '明智的聪明的', 'míngzhì de cōngmíng de', '/waɪz/', 'khôn ngoan', 'adjective', 'Many readers found the explanation wise and easy to follow.', '许多读者认为这段解释十分“明智的聪明的”，而且容易理解。', 'Xǔduō dúzhě rènwéi zhè duàn jiěshì shífēn "míngzhì de cōngmíng de", érqiě róngyì lǐjiě.', 'Nhiều người đọc nhận xét phần giải thích rất khôn ngoan và dễ theo dõi.', 'Triết học', 40, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1479', 'worthwhile', '值得花时间的', 'zhídé huā shíjiān de', '/ˌwɜːrθˈwaɪl/', 'đáng giá, bõ công', 'adjective', 'The report highlighted a worthwhile factor that shaped the final decision.', '报告重点指出了一项“值得花时间的”因素，它影响了最终决定。', 'Bàogào zhòngdiǎn zhǐchū le yīxiàng "zhídé huā shíjiān de" yīnsù, tā yǐngxiǎng le zuìzhōng juédìng.', 'Báo cáo nhấn mạnh một yếu tố đáng giá, bõ công đã tác động tới quyết định cuối cùng.', 'Đánh giá', 1, 'B2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1480', 'ability', '能力', 'nénglì', '/əˈbɪləti/', 'năng lực, khả năng', 'noun', 'Understanding the role of ''ability'' is essential in everyday communication.', '在相关场景中，理解“能力”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "nénglì" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “năng lực, khả năng” rất quan trọng trong chủ đề Năng lực cá nhân.', 'Năng lực cá nhân', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1481', 'absence', '缺席', 'quēxí', '/ˈæbsəns/', 'sự vắng mặt', 'noun', 'The team reviewed the details about ''absence'' before the meeting.', '团队在会议前仔细核对了关于“缺席”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "quēxí" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “sự vắng mặt” trước cuộc họp.', 'Học tập & công việc', 2, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1482', 'access', '访问权限', 'fǎngwèn quánxiàn', '/ˈækses/', 'quyền truy cập', 'noun', 'We discussed ''access'' during today''s lesson on information technology.', '我们在今天的课程中重点讨论了“访问权限”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "fǎngwèn quánxiàn".', 'Chúng tôi đã thảo luận trọng tâm về “quyền truy cập” trong buổi học hôm nay.', 'Công nghệ', 9, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1483', 'accomplishment', '成就', 'chéngjiù', '/əˈkɑːmplɪʃmənt/', 'thành tựu', 'noun', 'Clear notes on ''accomplishment'' help learners recall the concept faster.', '关于“成就”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "chéngjiù" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “thành tựu” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Sự nghiệp', 7, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
