INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1488', 'administration', '行政管理', 'xíngzhèng guǎnlǐ', '/ədˌmɪnɪˈstreɪʃən/', 'quản trị hành chính', 'noun', 'Understanding the role of ''administration'' is essential in public administration and history.', '在相关场景中，理解“行政管理”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "xíngzhèng guǎnlǐ" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “quản trị hành chính” rất quan trọng trong chủ đề Hành chính công.', 'Hành chính công', 40, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
