INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1608', 'entrance', '入口入场', 'rùkǒu rùchǎng', '/ˈentrəns/', 'lối vào', 'noun', 'Understanding the role of ''entrance'' is essential in architecture and construction.', '在相关场景中，理解“入口入场”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "rùkǒu rùchǎng" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “lối vào” rất quan trọng trong chủ đề Không gian.', 'Không gian', 16, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
