INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1675', 'integration', '整合一体化', 'zhěnghé yītǐhuà', '/ˌɪntɪˈɡreɪʃən/', 'sự tích hợp, hội nhập', 'noun', 'Clear notes on ''integration'' help learners recall the concept faster.', '关于“整合一体化”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "zhěnghé yītǐhuà" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “sự tích hợp, hội nhập” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Phần mềm', 12, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
