INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1854', 'usage', '用法使用量', 'yòngfǎ shǐyòngliàng', '/ˈjuːsɪdʒ/', 'cách dùng, mức sử dụng', 'noun', 'We discussed ''usage'' during today''s lesson on academic study.', '我们在今天的课程中重点讨论了“用法使用量”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "yòngfǎ shǐyòngliàng".', 'Chúng tôi đã thảo luận trọng tâm về “cách dùng, mức sử dụng” trong buổi học hôm nay.', 'Ngôn ngữ', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1855', 'validity', '有效性合法性', 'yǒuxiàoxìng héfǎxìng', '/vəˈlɪdəti/', 'tính hợp lệ', 'noun', 'Clear notes on ''validity'' help learners recall the concept faster.', '关于“有效性合法性”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "yǒuxiàoxìng héfǎxìng" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “tính hợp lệ” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Pháp lý', 6, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1856', 'variation', '变化变体', 'biànhuà biàntǐ', '/ˌveriˈeɪʃən/', 'sự biến thiên', 'noun', 'Understanding the role of ''variation'' is essential in mathematics.', '在相关场景中，理解“变化变体”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "biànhuà biàntǐ" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “sự biến thiên” rất quan trọng trong chủ đề Thống kê.', 'Thống kê', 25, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1857', 'variety', '多样化品种', 'duōyànghuà pǐnzhǒng', '/vəˈraɪəti/', 'sự đa dạng', 'noun', 'The team reviewed the details about ''variety'' before the meeting.', '团队在会议前仔细核对了关于“多样化品种”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "duōyànghuà pǐnzhǒng" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “sự đa dạng” trước cuộc họp.', 'Mô tả', 1, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1858', 'version', '版本说法', 'bǎnběn shuōfǎ', '/ˈvɜːrʒən/', 'phiên bản', 'noun', 'We discussed ''version'' during today''s lesson on software engineering.', '我们在今天的课程中重点讨论了“版本说法”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "bǎnběn shuōfǎ".', 'Chúng tôi đã thảo luận trọng tâm về “phiên bản” trong buổi học hôm nay.', 'Phần mềm', 12, 'A2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1859', 'viewpoint', '观点立场', 'guāndiǎn lìchǎng', '/ˈvjuːpɔɪnt/', 'quan điểm', 'noun', 'Clear notes on ''viewpoint'' help learners recall the concept faster.', '关于“观点立场”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "guāndiǎn lìchǎng" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “quan điểm” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
