INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1864', 'well-being', '幸福安康', 'xìngfú ānkāng', '/ˌwel ˈbiːɪŋ/', 'sức khỏe và hạnh phúc', 'noun', 'Understanding the role of ''well-being'' is essential in psychology.', '在相关场景中，理解“幸福安康”的作用非常重要。', 'Zài xiāngguān chǎngjǐng zhōng, lǐjiě "xìngfú ānkāng" de zuòyòng fēicháng zhòngyào.', 'Hiểu rõ vai trò của “sức khỏe và hạnh phúc” rất quan trọng trong chủ đề Sức khỏe tinh thần.', 'Sức khỏe tinh thần', 28, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1865', 'wisdom', '智慧才智', 'zhìhuì cáizhì', '/ˈwɪzdəm/', 'trí tuệ, sự khôn ngoan', 'noun', 'The team reviewed the details about ''wisdom'' before the meeting.', '团队在会议前仔细核对了关于“智慧才智”的细节。', 'Tuánduì zài huìyì qián zǐxì héduì le guānyú "zhìhuì cáizhì" de xìjié.', 'Cả nhóm đã rà soát kỹ các chi tiết liên quan đến “trí tuệ, sự khôn ngoan” trước cuộc họp.', 'Triết học', 40, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1866', 'workplace', '工作场所', 'gōngzuò chǎngsuǒ', '/ˈwɜːrkpleɪs/', 'nơi làm việc', 'noun', 'We discussed ''workplace'' during today''s lesson on workplace management.', '我们在今天的课程中重点讨论了“工作场所”。', 'Wǒmen zài jīntiān de kèchéng zhōng zhòngdiǎn tǎolùn le "gōngzuò chǎngsuǒ".', 'Chúng tôi đã thảo luận trọng tâm về “nơi làm việc” trong buổi học hôm nay.', 'Công việc', 7, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1867', 'workshop', '研讨班车间', 'yántǎobān chējiān', '/ˈwɜːrkʃɑːp/', 'hội thảo thực hành, phân xưởng', 'noun', 'Clear notes on ''workshop'' help learners recall the concept faster.', '关于“研讨班车间”的清晰笔记有助于学习者更快记住该概念。', 'Guānyú "yántǎobān chējiān" de qīngxī bǐjì yǒuzhùyú xuéxízhě gèng kuài jìzhù gāi gàiniàn.', 'Ghi chú rõ ràng về “hội thảo thực hành, phân xưởng” giúp người học ghi nhớ khái niệm nhanh hơn.', 'Đào tạo', 2, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1868', 'actually', '实际上', 'shíjìshang', '/ˈæktʃuəli/', 'thực ra là', 'adverb', 'She spoke actually so that everyone in the room could follow.', '她“实际上”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "shíjìshang" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày thực ra là để mọi người trong phòng đều dễ dàng theo kịp.', 'Từ nối & trạng từ', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1869', 'additionally', '此外', 'cǐwài', '/əˈdɪʃənəli/', 'thêm vào đó', 'adverb', 'The situation changed additionally over the past few months.', '在过去几个月里，情况“此外”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "cǐwài" fāshēng le biànhuà.', 'Tình hình đã thay đổi thêm vào đó trong vài tháng vừa qua.', 'Từ nối & trạng từ', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1870', 'adequately', '充分地', 'chōngfèn de', '/ˈædɪkwətli/', 'một cách đầy đủ', 'adverb', 'She spoke adequately so that everyone in the room could follow.', '她“充分地”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "chōngfèn de" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày một cách đầy đủ để mọi người trong phòng đều dễ dàng theo kịp.', 'Từ nối & trạng từ', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1871', 'altogether', '总共完全', 'zǒnggòng wánquán', '/ˌɔːltəˈɡeðər/', 'tổng cộng, hoàn toàn', 'adverb', 'The situation changed altogether over the past few months.', '在过去几个月里，情况“总共完全”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "zǒnggòng wánquán" fāshēng le biànhuà.', 'Tình hình đã thay đổi tổng cộng, hoàn toàn trong vài tháng vừa qua.', 'Từ nối & trạng từ', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1872', 'approximately', '大约左右', 'dàyuē zuǒyòu', '/əˈprɑːksɪmətli/', 'xấp xỉ khoảng', 'adverb', 'She spoke approximately so that everyone in the room could follow.', '她“大约左右”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "dàyuē zuǒyòu" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày xấp xỉ khoảng để mọi người trong phòng đều dễ dàng theo kịp.', 'Số liệu', 25, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1873', 'automatically', '自动地', 'zìdòng de', '/ˌɔːtəˈmætɪkli/', 'một cách tự động', 'adverb', 'The situation changed automatically over the past few months.', '在过去几个月里，情况“自动地”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "zìdòng de" fāshēng le biànhuà.', 'Tình hình đã thay đổi một cách tự động trong vài tháng vừa qua.', 'Công nghệ', 9, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1874', 'briefly', '简短地', 'jiǎnduǎn de', '/ˈbriːfli/', 'một cách ngắn gọn', 'adverb', 'She spoke briefly so that everyone in the room could follow.', '她“简短地”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "jiǎnduǎn de" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày một cách ngắn gọn để mọi người trong phòng đều dễ dàng theo kịp.', 'Giao tiếp', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1875', 'carefully', '仔细地', 'zǐxì de', '/ˈkerfəli/', 'một cách cẩn thận', 'adverb', 'The situation changed carefully over the past few months.', '在过去几个月里，情况“仔细地”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "zǐxì de" fāshēng le biànhuà.', 'Tình hình đã thay đổi một cách cẩn thận trong vài tháng vừa qua.', 'Đời sống', 1, 'A1', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
