INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1922', 'locally', '在当地', 'zài dāngdì', '/ˈloʊkəli/', 'tại địa phương', 'adverb', 'She spoke locally so that everyone in the room could follow.', '她“在当地”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "zài dāngdì" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày tại địa phương để mọi người trong phòng đều dễ dàng theo kịp.', 'Địa lý', 19, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1923', 'mainly', '主要地', 'zhǔyào de', '/ˈmeɪnli/', 'chủ yếu là', 'adverb', 'The situation changed mainly over the past few months.', '在过去几个月里，情况“主要地”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "zhǔyào de" fāshēng le biànhuà.', 'Tình hình đã thay đổi chủ yếu là trong vài tháng vừa qua.', 'Từ nối & trạng từ', 1, 'A2', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
