INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1988', 'tightly', '紧紧地严密地', 'jǐnjǐn de yánmì de', '/ˈtaɪtli/', 'chặt chẽ', 'adverb', 'She spoke tightly so that everyone in the room could follow.', '她“紧紧地严密地”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "jǐnjǐn de yánmì de" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày chặt chẽ để mọi người trong phòng đều dễ dàng theo kịp.', 'Cách thức', 1, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
