INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1990', 'traditionally', '传统上历来', 'chuántǒng shàng lìlái', '/trəˈdɪʃənəli/', 'theo truyền thống', 'adverb', 'She spoke traditionally so that everyone in the room could follow.', '她“传统上历来”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "chuántǒng shàng lìlái" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày theo truyền thống để mọi người trong phòng đều dễ dàng theo kịp.', 'Văn hóa', 29, 'B2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1991', 'truly', '真正地确实', 'zhēnzhèng de quèshí', '/ˈtruːli/', 'thực sự, chân thành', 'adverb', 'The situation changed truly over the past few months.', '在过去几个月里，情况“真正地确实”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "zhēnzhèng de quèshí" fāshēng le biànhuà.', 'Tình hình đã thay đổi thực sự, chân thành trong vài tháng vừa qua.', 'Thái độ', 1, 'A2', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1992', 'typically', '通常典型地', 'tōngcháng diǎnxíng de', '/ˈtɪpɪkli/', 'thường thấy, điển hình', 'adverb', 'She spoke typically so that everyone in the room could follow.', '她“通常典型地”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "tōngcháng diǎnxíng de" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày thường thấy, điển hình để mọi người trong phòng đều dễ dàng theo kịp.', 'Học thuật', 2, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1993', 'ultimately', '最终归根结底', 'zuìzhōng guīgēn jiédǐ', '/ˈʌltɪmətli/', 'suy cho cùng, cuối cùng', 'adverb', 'The situation changed ultimately over the past few months.', '在过去几个月里，情况“最终归根结底”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "zuìzhōng guīgēn jiédǐ" fāshēng le biànhuà.', 'Tình hình đã thay đổi suy cho cùng, cuối cùng trong vài tháng vừa qua.', 'Từ nối & trạng từ', 3, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1994', 'unexpectedly', '出乎意料地', 'chūhū yìliào de', '/ˌʌnɪkˈspektɪdli/', 'bất ngờ, ngoài dự kiến', 'adverb', 'She spoke unexpectedly so that everyone in the room could follow.', '她“出乎意料地”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "chūhū yìliào de" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày bất ngờ, ngoài dự kiến để mọi người trong phòng đều dễ dàng theo kịp.', 'Đời sống', 1, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1995', 'universally', '普遍地全世界', 'pǔbiàn de quán shìjiè', '/ˌjuːnɪˈvɜːrsəli/', 'phổ quát khắp nơi', 'adverb', 'The situation changed universally over the past few months.', '在过去几个月里，情况“普遍地全世界”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "pǔbiàn de quán shìjiè" fāshēng le biànhuà.', 'Tình hình đã thay đổi phổ quát khắp nơi trong vài tháng vừa qua.', 'Học thuật', 2, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1996', 'urgently', '紧急地迫切地', 'jǐnjí de pòqiè de', '/ˈɜːrdʒəntli/', 'khẩn cấp', 'adverb', 'She spoke urgently so that everyone in the room could follow.', '她“紧急地迫切地”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "jǐnjí de pòqiè de" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày khẩn cấp để mọi người trong phòng đều dễ dàng theo kịp.', 'Công việc', 7, 'B1', 'HSK 4', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1997', 'usually', '通常一般', 'tōngcháng yībān', '/ˈjuːʒuəli/', 'thường xuyên', 'adverb', 'The situation changed usually over the past few months.', '在过去几个月里，情况“通常一般”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "tōngcháng yībān" fāshēng le biànhuà.', 'Tình hình đã thay đổi thường xuyên trong vài tháng vừa qua.', 'Tần suất', 1, 'A1', 'HSK 3', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1998', 'virtually', '几乎实质上', 'jīhū shízhì shàng', '/ˈvɜːrtʃuəli/', 'hầu như, qua mạng', 'adverb', 'She spoke virtually so that everyone in the room could follow.', '她“几乎实质上”表达了自己的观点，让在场每个人都听得很清楚。', 'Tā "jīhū shízhì shàng" biǎodá le zìjǐ de guāndiǎn, ràng zàichǎng měigè rén dōu tīng de hěn qīngchu.', 'Cô ấy trình bày hầu như, qua mạng để mọi người trong phòng đều dễ dàng theo kịp.', 'Công nghệ', 9, 'B2', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
INSERT OR REPLACE INTO wb_flashcard_deck_items (id, en, zh, pinyin, ipa, vi, pos, example_en, example_zh, example_pinyin, example_vi, topic, domain_id, level_en, level_zh, deck_scope, status) VALUES ('FC-1999', 'widely', '广泛地普遍地', 'guǎngfàn de pǔbiàn de', '/ˈwaɪdli/', 'rộng rãi', 'adverb', 'The situation changed widely over the past few months.', '在过去几个月里，情况“广泛地普遍地”发生了变化。', 'Zài guòqù jǐgè yuè lǐ, qíngkuàng "guǎngfàn de pǔbiàn de" fāshēng le biànhuà.', 'Tình hình đã thay đổi rộng rãi trong vài tháng vừa qua.', 'Học thuật', 2, 'B1', 'HSK 5', 'FLASHCARD_ONLY', 'REVIEW_REQUIRED');
